// Phase 24 (2026-09-28): guided tours (tutorials/engine.js draws the overlay, tutorials/registry.js
// holds the words) are loaded by loadGuidedTours() with a dynamic import, not imported here: a
// server started before tutorials/ was on its static allowlist 404s them, and a failed static
// import would stop the whole app from loading. Without them the app simply has no tours.

const DB_NAME = "environmental-crm-foundation";
const DB_VERSION = 3;
const AUTH_SESSION_KEY = "enviroCrm.pkce";
const ACCESS_TOKEN_KEY = "enviroCrm.accessToken";
const STAGES = ["Lead", "Qualify", "Develop", "Proposal", "Negotiation", "Won"];
const STAGE_PROBABILITY = {
  Lead: 15,
  Qualify: 30,
  Develop: 45,
  Proposal: 60,
  Negotiation: 80,
  Won: 100,
};
const STAGE_DESCRIPTIONS = {
  Lead: "Qualify fit, urgency, site risk, and decision path.",
  Qualify: "Confirm timeframe, budget, purchase process, and decision maker.",
  Develop: "Scope the solution, site walk, stakeholders, competitors, and needed resources.",
  Proposal: "Build pricing, alternates, schedule, and compliance language.",
  Negotiation: "Resolve buyer questions, approvals, and final terms.",
  Won: "Handoff to project setup, scheduling, and document control.",
};

// Fields required to be filled in before an opportunity can enter a given stage.
// Keyed by the stage being entered; only scalar status/dropdown/text fields are gated
// here (list-type items like stakeholders/competitors/assignments are not required to
// be non-empty to advance, per product decision). Populated incrementally as each
// stage's edit dialogs land.
const STAGE_REQUIRED_FIELDS = {
  Lead: [],
  Qualify: [
    { key: "opportunityName", label: "Opportunity name" },
    { key: "accountId", label: "Account" },
    // Owner, 2026-09-25: a site, not specifically a facility — a linked location (a roadside, a
    // right-of-way) qualifies the deal too. Applies to every opportunity, not only field work.
    { key: "facilityId", label: "Site (facility or location)", validate: (opportunity) => opportunitySiteNames(opportunity).length > 0 },
    { key: "contaminationNotes", label: "Contamination" },
    { key: "serviceType", label: "Opportunity type" },
    // Phase 03/06 (2026-09-23): an opportunity inherits its account's industry, so a blank own
    // value doesn't block the gate when the account's industry is set.
    { key: "industry", label: "Industry", validate: (opportunity) => Boolean(opportunity.industry || primaryIndustryNameForAccount(opportunity.accountId)) },
    { key: "description", label: "Description" },
    { key: "currentSituation", label: "Current situation" },
  ],
  Develop: [
    { key: "contactLinked", label: "Account contact", validate: (opportunity) => contactsForOpportunity(opportunity.id).length > 0 },
    { key: "purchaseTimeframe", label: "Purchase time frame" },
    { key: "budgetAmount", label: "Estimated budget", validate: (opportunity) => Number(opportunity.budgetAmount || 0) > 0 },
    { key: "purchaseProcess", label: "Purchase process" },
    {
      key: "decisionMakerFound",
      label: "Decision maker found",
      // Prefer the real signal (a stakeholder actually tagged "Decision maker" in Associated
      // Contacts) over the manual dropdown, but don't regress anything already marked Complete
      // by hand before a tagged stakeholder existed to back it up.
      validate: (opportunity) => opportunity.decisionMakerFound === "Complete" || hasDecisionMakerStakeholder(opportunity.id),
    },
    { key: "captureSummary", label: "Capture summary" },
  ],
  Proposal: [
    { key: "customerNeed", label: "Customer need" },
    { key: "proposedSolution", label: "Proposed solution" },
    { key: "siteWalkStatus", label: "Site walk status" },
  ],
  Negotiation: [
    // Phase 13 (2026-09-24): the office-approved requirement, not "is a file attached".
    { key: "customerPacketApproved", label: "New customer packet approved", validate: (opportunity) => paperworkApproved(opportunity.accountId, "customer-packet", opportunity.id) },
    { key: "wasteAuthorizationApproved", label: "Waste authorization approved", validate: (opportunity) => paperworkApproved(opportunity.accountId, "waste-authorization", opportunity.id) },
    { key: "proposalDevelopedStatus", label: "Develop proposal", validate: (opportunity) => opportunity.proposalDevelopedStatus === "Complete" },
    { key: "internalReviewStatus", label: "Complete internal review", validate: (opportunity) => opportunity.internalReviewStatus === "Complete" },
    { key: "proposalPresentedStatus", label: "Present proposal", validate: (opportunity) => opportunity.proposalPresentedStatus === "Complete" },
    { key: "quoteId", label: "Quote", validate: (opportunity) => Boolean(opportunity.quoteId) },
  ],
  Won: [
    { key: "accountPaperworkStatus", label: "New account paperwork signed", validate: (opportunity) => opportunity.accountPaperworkStatus === "Signed" },
    // Phase 25 Wave E (2026-09-29): the legacy sign-off dropdown, or the signed copy itself — an
    // Approved/Waived signed-quote / work-authorization requirement for this deal (or its project).
    { key: "quoteSignedStatus", label: "Quote signed", validate: (opportunity) => opportunity.quoteSignedStatus === "Signed" || opportunityPaperworkSatisfied(opportunity, "signed-quote") },
    { key: "workAuthorizationStatus", label: "Work authorization signed", validate: (opportunity) => opportunity.workAuthorizationStatus === "Signed" || opportunityPaperworkSatisfied(opportunity, "work-authorization") },
  ],
};

function getMissingStageFields(opportunity, stage) {
  const core = getCoreOpportunity(opportunity);
  return (STAGE_REQUIRED_FIELDS[stage] || []).filter((requirement) =>
    requirement.validate ? !requirement.validate(opportunity) : !String(core[requirement.key] ?? "").trim(),
  );
}

function getMissingFieldsThroughStage(opportunity, targetStage) {
  const targetIndex = STAGES.indexOf(targetStage);
  if (targetIndex < 0) return [];
  return STAGES.slice(0, targetIndex + 1).flatMap((stage) => getMissingStageFields(opportunity, stage));
}

// Phase 06 item 32 — the same check the Advance button uses (the next stage's required fields,
// not the cumulative through-current-stage set the Summary banner shows), reused to drive a red
// dot on the tab and a highlight on the specific panel, so there is one source of truth instead of
// a second parallel list.
function getNextStageMissingFields(opportunity) {
  const currentIndex = STAGES.indexOf(opportunity.stage);
  const nextStage = STAGES[currentIndex + 1];
  if (!nextStage) return [];
  return getMissingStageFields(opportunity, nextStage);
}

// Maps each gated field key to the tab and panel that actually holds it, so a real UI location
// backs every dot/highlight — not a guess. Fields not listed here (list-type items like
// stakeholders are never gated) have no panel to highlight.
const OPPORTUNITY_FIELD_LOCATIONS = {
  opportunityName: { tab: "summary", panel: "opportunity-core" },
  accountId: { tab: "summary", panel: "opportunity-core" },
  serviceType: { tab: "summary", panel: "opportunity-core" },
  contactLinked: { tab: "summary", panel: "associated-contacts" },
  facilityId: { tab: "lead-qualification", panel: "lead-details" },
  contaminationNotes: { tab: "lead-qualification", panel: "lead-details" },
  industry: { tab: "lead-qualification", panel: "lead-details" },
  description: { tab: "lead-qualification", panel: "lead-details" },
  currentSituation: { tab: "lead-qualification", panel: "lead-details" },
  purchaseTimeframe: { tab: "lead-qualification", panel: "qualification" },
  budgetAmount: { tab: "lead-qualification", panel: "qualification" },
  purchaseProcess: { tab: "lead-qualification", panel: "qualification" },
  decisionMakerFound: { tab: "lead-qualification", panel: "qualification" },
  captureSummary: { tab: "lead-qualification", panel: "qualification" },
  // Item 35 sub-piece 1 — customerNeed moved to Lead & Qualification's Lead details panel.
  customerNeed: { tab: "lead-qualification", panel: "lead-details" },
  proposedSolution: { tab: "develop-planning", panel: "develop-details" },
  siteWalkStatus: { tab: "develop-planning", panel: "develop-details" },
  proposalDevelopedStatus: { tab: "proposal-documents", panel: "proposal-status" },
  internalReviewStatus: { tab: "proposal-documents", panel: "proposal-status" },
  proposalPresentedStatus: { tab: "proposal-documents", panel: "proposal-status" },
  quoteId: { tab: "proposal-documents", panel: "quote" },
  accountPaperworkStatus: { tab: "proposal-documents", panel: "negotiation-signoff" },
  customerPacketApproved: { tab: "proposal-documents", panel: "paperwork" },
  wasteAuthorizationApproved: { tab: "proposal-documents", panel: "paperwork" },
  quoteSignedStatus: { tab: "proposal-documents", panel: "negotiation-signoff" },
  workAuthorizationStatus: { tab: "proposal-documents", panel: "negotiation-signoff" },
};

function tabNeedsAttention(missingFields, tabId) {
  return missingFields.some((field) => OPPORTUNITY_FIELD_LOCATIONS[field.key]?.tab === tabId);
}

function panelNeedsAttention(missingFields, panelId) {
  return missingFields.some((field) => OPPORTUNITY_FIELD_LOCATIONS[field.key]?.panel === panelId);
}

// A Project's operational lifecycle, distinct from the sales-side opportunity STAGES above.
// Plan/Mobilize/Field Work/Closeout have no dedicated UI yet — only Intake is built out this pass.
const PROJECT_STAGES = ["Intake", "Plan", "Mobilize", "Field Work", "Closeout"];

// Fields required before a project can be considered to have left Intake. Keyed by the
// stage being entered, same convention as STAGE_REQUIRED_FIELDS. `sitePhotoRefs` is
// deliberately not required (list-type, matches the opportunity-side gate-scope decision).
const PROJECT_STAGE_REQUIRED_FIELDS = {
  Plan: [
    { key: "generatorName", label: "Generator", validate: (job) => Boolean(job.generatorName || projectIntakeFallbacks(job).generatorName) },
    // Owner, 2026-09-25: the project's site is a facility or a location — a spill on a road
    // shoulder has no facility and must still be able to leave Intake.
    { key: "facilityId", label: "Site (facility or location)", validate: (job) => Boolean(projectSite(job).name) },
    { key: "insuranceCarrier", label: "Insurance", validate: (job) => Boolean(job.insuranceCarrier || projectIntakeFallbacks(job).insuranceCarrier) },
    { key: "epaId", label: "EPA ID", validate: (job) => Boolean(job.epaId || projectIntakeFallbacks(job).epaId) },
    { key: "tceqId", label: "TCEQ ID", validate: (job) => Boolean(job.tceqId || projectIntakeFallbacks(job).tceqId) },
    { key: "serviceProfile", label: "Services" },
    { key: "siteWalkStatus", label: "Site walk" },
    { key: "jobClass", label: "Project type" },
  ],
};

function getMissingProjectStageFields(job, stage) {
  return (PROJECT_STAGE_REQUIRED_FIELDS[stage] || []).filter((requirement) =>
    requirement.validate ? !requirement.validate(job) : !String(job[requirement.key] ?? "").trim(),
  );
}

