// ---- Phase 10, Part 2: Forms tile ----
//
// Reuses `jobFormSubmissions` (the same collection Job Book's typed task capture writes to) as a
// general-purpose form browser: a small catalog of standalone forms not tied to a template step, e.g.
// a daily safety checklist or an incident report. Checked what already existed before inventing
// anything: `jobTypeTemplates` only defines task types *inside* a work-plan template, there was no
// "fill this out any time, not tied to a job step" form catalog anywhere in the prototype, so this is
// a small hardcoded one rather than a guess at a bigger config system nobody asked for yet.
const FRONTLINE_STANDALONE_FORMS = [
  {
    key: "daily-safety-checklist",
    name: "Daily Safety Checklist",
    type: "Checklist",
    options: [
      "PPE inspected and worn",
      "Vehicle pre-trip inspection complete",
      "Site hazards reviewed with crew",
      "Emergency contacts confirmed",
    ],
  },
  { key: "incident-report", name: "Incident Report", type: "Note" },
  {
    key: "vehicle-inspection",
    name: "Vehicle Inspection",
    type: "Checklist",
    options: ["Tires and brakes checked", "Fluids checked", "Lights and signals working", "No visible damage"],
  },
  { key: "near-miss-report", name: "Near-Miss Report", type: "Note" },
];

function findFrontlineStandaloneForm(key) {
  return FRONTLINE_STANDALONE_FORMS.find((form) => form.key === key);
}

function frontlineStandaloneSubmissions(employeeId) {
  return (state.backend.jobFormSubmissions || [])
    .filter((submission) => submission.standalone && submission.submittedByEmployeeId === employeeId)
    .sort((a, b) => new Date(b.submittedAt) - new Date(a.submittedAt));
}

// ---- Phase 10, Part 2: Messaging tile (inbox + thread redesign, 2026-09-23) ----
//
// `messages` rows are threaded by dispatch job (`threadKey` = the job id) or the shared "general"
// thread between a crew and Dispatch. The field side is an inbox -- one row per conversation, latest
// first, unread counts -- that opens into a thread with a pinned composer. The office answers the same
// rows from the dispatch job's Messages tab and the Dispatch Board's Field messages panel; before this
// pass nothing office-side could read or reply, so field messages went nowhere. `readAt` means "read by
// the other side": the field marks office messages read when it opens the thread, the office marks
// field messages read when it opens the job's Messages tab (or the board, for the general channel).
function frontlineThreadKey(jobId) {
  return jobId || "general";
}

function getMessages() {
  return (state.backend.messages || []).filter((message) => !message.deletedAt);
}

function frontlineMessagesForThread(threadKey) {
  return getMessages()
    .filter((message) => message.threadKey === threadKey)
    .sort((a, b) => new Date(a.sentAt) - new Date(b.sentAt));
}

function unreadMessageCount(threadKey, fromRole) {
  return getMessages().filter((message) => message.threadKey === threadKey && message.senderRole === fromRole && !message.readAt).length;
}

// Conversations a field worker can see: Dispatch (the general channel), their open jobs, and earlier
// jobs that still hold a conversation. Closed jobs with nothing said stay out of the way.
function frontlineConversations(employeeId) {
  const myJobs = frontlineMyDispatchJobs(employeeId);
  const row = (threadKey, job) => {
    const latest = frontlineMessagesForThread(threadKey).slice(-1)[0] || null;
    const sortAt = latest ? new Date(latest.sentAt).getTime() : new Date(job?.scheduledStart || 0).getTime() || 0;
    return { threadKey, job, latest, unread: unreadMessageCount(threadKey, "office"), sortAt };
  };
  const bySortAt = (a, b) => b.sortAt - a.sortAt;
  return {
    general: row("general", null),
    open: myJobs
      .filter((job) => !isTerminalDispatchStatus(job.status))
      .map((job) => row(job.id, job))
      .sort(bySortAt),
    earlier: myJobs
      .filter((job) => isTerminalDispatchStatus(job.status))
      .map((job) => row(job.id, job))
      .filter((entry) => entry.latest)
      .sort(bySortAt),
  };
}

function frontlineUnreadTotal(employeeId) {
  const conversations = frontlineConversations(employeeId);
  return [conversations.general, ...conversations.open, ...conversations.earlier].reduce((sum, entry) => sum + entry.unread, 0);
}

// "Just now", "12m", a time for today, "Yesterday", a weekday inside the week, otherwise "Sep 17".
function chatRelativeTime(value) {
  const date = parseDate(value);
  if (!value || Number.isNaN(date.getTime())) return "";
  const now = new Date();
  const minutes = Math.round((now - date) / 60000);
  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes}m`;
  if (localIsoDate(date) === localIsoDate(now)) return formatShortTime(value);
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (localIsoDate(date) === localIsoDate(yesterday)) return "Yesterday";
  if (now - date < 6 * 86400000) return new Intl.DateTimeFormat("en-US", { weekday: "short" }).format(date);
  return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(date);
}

function chatDateLabel(value) {
  const date = parseDate(value);
  const now = new Date();
  const day = localIsoDate(date);
  if (day === localIsoDate(now)) return "Today";
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (day === localIsoDate(yesterday)) return "Yesterday";
  return new Intl.DateTimeFormat("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    ...(date.getFullYear() === now.getFullYear() ? {} : { year: "numeric" }),
  }).format(date);
}

// Shared by the phone and the office. `reader` is who is looking: `{ role: "field", id }` puts only
// that worker's own messages on the right (the general channel carries every crew, and another
// crew's message must not read as "yours"); `{ role: "office" }` puts every office message on the
// right, since the office shares one screen. Every bubble names its sender either way -- several
// office people and several crews can write into one thread. Messages are grouped under a date pill.
function renderChatThread(messages, reader, emptyText) {
  if (!messages.length) return `<div class="chat-empty">${escapeHtml(emptyText)}</div>`;
  let lastDay = "";
  return messages
    .map((message) => {
      const day = localIsoDate(parseDate(message.sentAt));
      const separator = day !== lastDay ? `<div class="chat-date"><span>${escapeHtml(chatDateLabel(message.sentAt))}</span></div>` : "";
      lastDay = day;
      const fromOffice = message.senderRole === "office";
      const mine = message.senderRole === reader.role && (reader.role === "office" || !reader.id || message.senderId === reader.id);
      const side = fromOffice ? "Dispatch" : "Field";
      const name = message.senderName || (fromOffice ? "Dispatch" : "Field crew");
      const sender = name === side ? name : `${name} · ${side}`;
      return `
        ${separator}
        <article class="chat-bubble ${mine ? "mine" : `theirs ${fromOffice ? "office" : "field"}`}">
          <span class="chat-sender">${escapeHtml(sender)}</span>
          <p>${escapeHtml(message.body)}</p>
          <time datetime="${escapeAttribute(message.sentAt)}">${formatShortTime(message.sentAt)}</time>
        </article>
      `;
    })
    .join("");
}

function renderChatComposer(formName, hiddenFields, placeholder) {
  return `
    <form class="chat-composer" data-form="${escapeAttribute(formName)}">
      ${Object.entries(hiddenFields)
        .map(([name, value]) => `<input type="hidden" name="${escapeAttribute(name)}" value="${escapeAttribute(value)}" />`)
        .join("")}
      <textarea name="body" rows="1" maxlength="1000" placeholder="${escapeAttribute(placeholder)}" aria-label="Message" required></textarea>
      <button class="chat-send" type="submit" aria-label="Send" title="Send">
        <svg aria-hidden="true" viewBox="0 0 24 24" focusable="false" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2 11 13" /><path d="M22 2 15 22l-4-9-9-4Z" /></svg>
      </button>
    </form>
  `;
}

function scrollChatToBottom() {
  requestAnimationFrame(() => {
    document.querySelectorAll(".chat-scroll").forEach((element) => {
      element.scrollTop = element.scrollHeight;
    });
  });
}

function renderFrontlineMessaging() {
  const employeeId = state.frontlineSession?.employeeId;
  if (state.frontlineMessagingThreadKey) {
    renderFrontlineMessageThread(state.frontlineMessagingThreadKey);
    return;
  }
  const conversations = frontlineConversations(employeeId);
  const unreadTotal = [conversations.general, ...conversations.open, ...conversations.earlier].reduce((sum, entry) => sum + entry.unread, 0);

  app.innerHTML = `
    <div class="frontline-shell">
      <div class="frontline-device">
        ${renderFrontlineHeader()}
        <div class="frontline-body">
          <div class="frontline-page-head">
            <h2>Messages</h2>
            <span class="help-text">${unreadTotal ? `${unreadTotal} unread` : "Dispatch and your jobs"}</span>
          </div>
          <div class="frontline-thread-list">
            ${renderFrontlineConversationRow(conversations.general)}
          </div>
          <h3 class="frontline-section-label">Your jobs</h3>
          <div class="frontline-thread-list">
            ${conversations.open.map(renderFrontlineConversationRow).join("") || `<div class="empty-state compact">No open jobs assigned to you.</div>`}
          </div>
          ${
            conversations.earlier.length
              ? `
                <h3 class="frontline-section-label">Earlier jobs</h3>
                <div class="frontline-thread-list">${conversations.earlier.map(renderFrontlineConversationRow).join("")}</div>
              `
              : ""
          }
        </div>
      </div>
    </div>
  `;
}

function renderFrontlineConversationRow(entry) {
  const { threadKey, job, latest, unread } = entry;
  const title = job ? job.jobNumber : "Dispatch";
  const subtitle = job ? job.jobName : "General channel for anything not about one job";
  const preview = latest ? `${latest.senderRole === "field" ? "You: " : ""}${latest.body}` : job ? "No messages yet" : "Start a conversation with dispatch";
  return `
    <button class="frontline-thread-row ${unread ? "unread" : ""}" type="button" data-action="frontline-messaging-open-thread" data-thread="${escapeAttribute(threadKey)}">
      <span class="frontline-thread-avatar ${job ? "job" : "office"}">${frontlineTileIcon(job ? "jobbook" : "messaging")}</span>
      <span class="frontline-thread-main">
        <span class="frontline-thread-title"><strong>${escapeHtml(title)}</strong>${latest ? `<time>${escapeHtml(chatRelativeTime(latest.sentAt))}</time>` : ""}</span>
        <span class="frontline-thread-sub">${escapeHtml(subtitle)}</span>
        <span class="frontline-thread-preview">${escapeHtml(preview)}</span>
      </span>
      ${unread ? `<span class="frontline-unread-count" aria-label="${unread} unread">${unread}</span>` : ""}
    </button>
  `;
}

function renderFrontlineMessageThread(threadKey) {
  const job = threadKey === "general" ? null : findDispatchJob(threadKey);
  const messages = frontlineMessagesForThread(job ? job.id : "general");
  const title = job ? job.jobNumber : "Dispatch";
  const subtitle = job ? `${job.jobName} · ${job.customerName}` : "General channel";
  const emptyText = job ? `No messages about ${job.jobNumber} yet. Dispatch sees what you send here right away.` : "No messages yet. Dispatch sees what you send here right away.";

  app.innerHTML = `
    <div class="frontline-shell">
      <div class="frontline-device">
        ${renderFrontlineHeader()}
        <div class="frontline-body frontline-body-chat">
          <div class="frontline-thread-head">
            <button class="frontline-back-link" type="button" data-action="frontline-messaging-inbox">&lsaquo; Messages</button>
            <div class="frontline-thread-head-text">
              <strong>${escapeHtml(title)}</strong>
              <span>${escapeHtml(subtitle)}</span>
            </div>
            ${job ? `<button class="mini-button" type="button" data-action="frontline-open-job" data-id="${escapeAttribute(job.id)}">Open job</button>` : ""}
          </div>
          <div class="chat-scroll">
            ${renderChatThread(messages, { role: "field", id: state.frontlineSession?.employeeId }, emptyText)}
          </div>
          ${renderChatComposer("frontline-message", { jobId: job ? job.id : "" }, job ? `Message dispatch about ${job.jobNumber}` : "Message dispatch")}
        </div>
      </div>
    </div>
  `;
  scrollChatToBottom();
  // Opening a thread marks the office's unread messages in it as read -- a real write, not a fake badge.
  frontlineMarkMessagesRead(job ? job.id : "");
}

async function frontlineSendMessage(form) {
  const submitButton = form.querySelector('button[type="submit"]');
  if (submitButton?.disabled) return;

  const data = new FormData(form);
  const jobId = (data.get("jobId") || "").toString();
  const body = (data.get("body") || "").toString().trim();
  if (!body) return;
  if (submitButton) submitButton.disabled = true;
  const employee = findEmployee(state.frontlineSession?.employeeId);
  const job = jobId ? findDispatchJob(jobId) : null;

  try {
    await saveBackendRecord(
      "messages",
      {
        id: makeId("message"),
        threadKey: frontlineThreadKey(jobId),
        dispatchJobId: jobId || "",
        senderId: employee?.id || "",
        senderName: employee?.displayName || "Field worker",
        senderRole: "field",
        recipientId: "office",
        recipientName: job ? `Dispatch (${job.jobNumber})` : "Dispatch",
        body,
        sentAt: new Date().toISOString(),
        readAt: null,
      },
      { refresh: false },
    );
    await refreshBackendState();
    form.reset();
    render();
  } catch (error) {
    if (submitButton) submitButton.disabled = false;
    showToast(error.message || "Could not send that message.");
  }
}

async function markThreadMessagesRead(threadKey, fromRole) {
  const unread = getMessages().filter((message) => message.threadKey === threadKey && message.senderRole === fromRole && !message.readAt);
  if (!unread.length) return;
  const readAt = new Date().toISOString();
  for (const message of unread) {
    await saveBackendRecord("messages", { ...message, readAt }, { refresh: false });
  }
  await refreshBackendState();
}

function frontlineMarkMessagesRead(jobId) {
  return markThreadMessagesRead(frontlineThreadKey(jobId), "office");
}

function dispatchMarkFieldMessagesRead(jobId) {
  return markThreadMessagesRead(frontlineThreadKey(jobId), "field");
}

// Red-dot rule: unread field messages on a job dot its Messages tab, its list row and its board card.
function dispatchJobMessageAlertTitle(job) {
  const unread = unreadMessageCount(job.id, "field");
  return unread ? `${unread} unread field message${unread === 1 ? "" : "s"}` : "";
}

function renderDispatchJobMessagesTab(job) {
  const messages = frontlineMessagesForThread(job.id);
  const lead = findEmployee(job.fieldLeadEmployeeId);
  const crew = dispatchAssignmentsForJob(job.id);
  scrollChatToBottom();
  dispatchMarkFieldMessagesRead(job.id);
  return `
    <section class="detail-stack">
      <article class="panel dispatch-job-messages">
        <div class="panel-header">
          <div>
            <h3>Messages with the crew</h3>
            <span>${lead ? `Field lead ${escapeHtml(lead.displayName)}` : "No field lead yet"} · ${crew.length} assigned · the crew sees this thread in Front Line under ${escapeHtml(job.jobNumber)}</span>
          </div>
        </div>
        <div class="panel-body">
          <div class="chat-scroll">
            ${renderChatThread(messages, { role: "office" }, `No messages on ${job.jobNumber} yet. Anything you send here reaches the crew's Front Line inbox.`)}
          </div>
          ${renderChatComposer("dispatch-message", { jobId: job.id }, `Message the crew on ${job.jobNumber}`)}
        </div>
      </article>
    </section>
  `;
}

// Dispatch Board: the general channel with every crew, plus the job threads waiting on a reply.
function renderDispatchFieldMessagesPanel() {
  const general = frontlineMessagesForThread("general");
  const unreadGeneral = unreadMessageCount("general", "field");
  const waiting = getDispatchJobs()
    .map((job) => ({ job, unread: unreadMessageCount(job.id, "field"), latest: frontlineMessagesForThread(job.id).slice(-1)[0] }))
    .filter((entry) => entry.unread)
    .sort((a, b) => new Date(b.latest?.sentAt || 0) - new Date(a.latest?.sentAt || 0));
  const waitingCount = waiting.reduce((sum, entry) => sum + entry.unread, 0);
  const summary = waiting.length
    ? `${waitingCount} unread on ${waiting.length} job${waiting.length === 1 ? "" : "s"}`
    : "The general channel every Front Line crew sees, plus the job threads waiting on a reply";
  scrollChatToBottom();
  // The general channel is not marked read just because the board rendered -- it sits below the
  // columns and may never have been looked at. Replying marks it read; so does the explicit button.
  return `
    <article class="panel dispatch-field-messages ${unreadGeneral || waiting.length ? "panel-needs-attention" : ""}">
      <div class="panel-header">
        <div><h3>Field messages</h3><span>${summary}</span></div>
        ${unreadGeneral ? `<button class="mini-button" type="button" data-action="dispatch-mark-general-read">Mark general channel read</button>` : ""}
      </div>
      <div class="panel-body dispatch-messages-layout">
        <div>
          <h4 class="frontline-section-label">General channel${unreadGeneral ? ` · ${unreadGeneral} new` : ""}</h4>
          <div class="chat-scroll">
            ${renderChatThread(general, { role: "office" }, "Nothing in the general channel yet. Crews use it for anything not about one job.")}
          </div>
          ${renderChatComposer("dispatch-message", { jobId: "" }, "Message every Front Line crew")}
        </div>
        <div>
          <h4 class="frontline-section-label">Job threads waiting on a reply</h4>
          <div class="dispatch-unread-list">
            ${
              waiting
                .map(
                  ({ job, unread, latest }) => `
                    <button class="frontline-thread-row unread" type="button" data-action="view-dispatch-job-messages" data-id="${escapeAttribute(job.id)}">
                      <span class="frontline-thread-avatar job">${frontlineTileIcon("jobbook")}</span>
                      <span class="frontline-thread-main">
                        <span class="frontline-thread-title"><strong>${escapeHtml(job.jobNumber)}</strong><time>${escapeHtml(chatRelativeTime(latest?.sentAt))}</time></span>
                        <span class="frontline-thread-sub">${escapeHtml(job.jobName)}</span>
                        <span class="frontline-thread-preview">${escapeHtml(latest ? `${latest.senderName}: ${latest.body}` : "")}</span>
                      </span>
                      <span class="frontline-unread-count" aria-label="${unread} unread">${unread}</span>
                    </button>
                  `,
                )
                .join("") || `<div class="empty-state compact">No job messages waiting. Each job's Messages tab holds its own thread.</div>`
            }
          </div>
        </div>
      </div>
    </article>
  `;
}

async function dispatchSendMessage(form) {
  const submitButton = form.querySelector('button[type="submit"]');
  if (submitButton?.disabled) return;
  const data = new FormData(form);
  const jobId = (data.get("jobId") || "").toString();
  const body = (data.get("body") || "").toString().trim();
  if (!body) return;
  if (submitButton) submitButton.disabled = true;
  const job = jobId ? findDispatchJob(jobId) : null;
  const lead = job ? findEmployee(job.fieldLeadEmployeeId) : null;

  try {
    await saveBackendRecord(
      "messages",
      {
        id: makeId("message"),
        threadKey: frontlineThreadKey(jobId),
        dispatchJobId: jobId,
        senderId: "office",
        senderName: state.currentUser?.name || "Dispatch",
        senderRole: "office",
        recipientId: lead?.id || "field",
        recipientName: lead?.displayName || (job ? "Crew" : "All crews"),
        body,
        sentAt: new Date().toISOString(),
        readAt: null,
      },
      { refresh: false },
    );
    // Replying in the general channel means it was read.
    if (!jobId) await markThreadMessagesRead("general", "field");
    await refreshBackendState();
    form.reset();
    render();
  } catch (error) {
    if (submitButton) submitButton.disabled = false;
    showToast(error.message || "Could not send that message.");
  }
}

// ---- Phase 10, Part 2: Location tile ----
//
// Reuses the existing `locations` GPS-point collection (Phase 02's rename target for the old
// mapLocations -- see GLOSSARY.md) and the same Leaflet satellite-tile pattern the Facility detail
// page uses (renderFacilityMapPanel/initializeFacilityMap) rather than inventing a second map
// component. Shows the field worker's own recent pings plus any GPS points tied to their assigned
// jobs' projects, and lets them record a real "here now" ping via the browser's geolocation API -- a
// genuine write to the shared `locations` collection, not a fake status string.
function frontlineLocationsForEmployee(employeeId) {
  const myJobs = frontlineMyDispatchJobs(employeeId);
  const projectIds = new Set(myJobs.map((job) => job.projectId).filter(Boolean));
  return (state.backend.locations || [])
    .filter((location) => projectIds.has(location.projectId) || location.reportedByEmployeeId === employeeId)
    .sort((a, b) => new Date(b.lastPingAt || 0) - new Date(a.lastPingAt || 0));
}

let frontlineLocationLeafletMap = null;

function renderFrontlineLocation() {
  const employeeId = state.frontlineSession?.employeeId;
  const myJobs = frontlineMyDispatchJobs(employeeId);
  const points = frontlineLocationsForEmployee(employeeId);

  app.innerHTML = `
    <div class="frontline-shell">
      <div class="frontline-device">
        ${renderFrontlineHeader()}
        <div class="frontline-body">
          <h2>Location</h2>
          <p class="help-text">Your last recorded position and the GPS points tied to your assigned jobs.</p>
          <div id="frontlineLocationMap" class="project-sample-map"></div>

          <form class="frontline-action-form" data-form="frontline-location-ping">
            <label>Job (optional)
              <select name="jobId">
                <option value="">Not tied to a specific job</option>
                ${myJobs.map((job) => `<option value="${escapeAttribute(job.id)}">${escapeHtml(frontlineJobOptionLabel(job))}</option>`).join("")}
              </select>
            </label>
            <label>Label
              <input name="label" maxlength="90" value="Field check-in" />
            </label>
            <button class="primary-button" type="submit">Record my current location</button>
          </form>

          <h3>Recent points</h3>
          <div class="record-list">
            ${
              points
                .map(
                  (location) => `
                    <div class="frontline-action-row">
                      <span>${escapeHtml(location.label || "GPS point")}${location.reportedByEmployeeId === employeeId ? " (you)" : ""}</span>
                      <span>${formatDateTime(location.lastPingAt)}</span>
                    </div>
                  `,
                )
                .join("") || `<div class="empty-state compact">No GPS points yet.</div>`
            }
          </div>
        </div>
      </div>
    </div>
  `;
  requestAnimationFrame(() => initializeFrontlineLocationMap(points));
}

function initializeFrontlineLocationMap(points) {
  const mapElement = document.querySelector("#frontlineLocationMap");
  if (!mapElement) return;
  const leaflet = window.L;
  const plottable = points.filter(hasGpsCoordinates);
  if (!leaflet) {
    mapElement.innerHTML = `<div class="map-loading">Map library did not load.</div>`;
    return;
  }
  if (!plottable.length) {
    mapElement.innerHTML = `<div class="map-loading">No GPS points captured yet — record your current location, or it will fill in as field work is logged with a location.</div>`;
    return;
  }
  if (frontlineLocationLeafletMap) {
    frontlineLocationLeafletMap.remove();
    frontlineLocationLeafletMap = null;
  }
  mapElement.innerHTML = "";
  frontlineLocationLeafletMap = leaflet.map(mapElement, { scrollWheelZoom: false });
  leaflet
    .tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}", {
      attribution: "Tiles &copy; Esri",
      maxZoom: 19,
    })
    .addTo(frontlineLocationLeafletMap);
  const bounds = [];
  plottable.forEach((location) => {
    const latLng = [Number(location.latitude), Number(location.longitude)];
    bounds.push(latLng);
    leaflet
      .marker(latLng, { icon: gpsPointIcon(leaflet), title: location.label || "GPS point" })
      .addTo(frontlineLocationLeafletMap)
      .bindPopup(
        `<div class="map-popup"><strong>${escapeHtml(location.label || "GPS point")}</strong><span>${formatDateTime(location.lastPingAt)}</span></div>`,
      );
  });
  frontlineLocationLeafletMap.fitBounds(bounds, { padding: [24, 24], maxZoom: 17 });
  setTimeout(() => frontlineLocationLeafletMap?.invalidateSize(), 80);
}

async function frontlineRecordLocationPing(form) {
  const submitButton = form.querySelector('button[type="submit"]');
  if (submitButton?.disabled) return;
  if (submitButton) submitButton.disabled = true;

  const data = new FormData(form);
  const jobId = (data.get("jobId") || "").toString();
  const label = (data.get("label") || "Field check-in").toString().trim();
  const employee = findEmployee(state.frontlineSession?.employeeId);
  const job = jobId ? findDispatchJob(jobId) : null;

  if (!navigator.geolocation) {
    showToast("This device doesn't support geolocation.");
    if (submitButton) submitButton.disabled = false;
    return;
  }

  navigator.geolocation.getCurrentPosition(
    async (position) => {
      try {
        await saveBackendRecord(
          "locations",
          {
            id: makeId("location"),
            projectId: job?.projectId || "",
            label,
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
            assetTags: [],
            status: "Field ping",
            reportedByEmployeeId: employee?.id || "",
            lastPingAt: new Date().toISOString(),
            // Phase 18 item 4: a ping from a personal phone names its consent and ages out.
            ...(state.session?.kind === "dispatch-link" && state.session.consentId
              ? { consentId: state.session.consentId, isTemporary: true, retainUntil: addDays(90), retentionReason: "Personal-device location consent" }
              : {}),
          },
          { refresh: false },
        );
        await refreshBackendState();
        render();
        showToast("Location recorded.");
      } catch (error) {
        showToast(error.message || "Could not record location.");
      } finally {
        if (submitButton) submitButton.disabled = false;
      }
    },
    (error) => {
      showToast(error.message || "Could not get your location.");
      if (submitButton) submitButton.disabled = false;
    },
    { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 },
  );
}

async function frontlineLogin() {
  const select = document.getElementById("frontlineFieldLeadSelect");
  const employeeId = select?.value || "";
  if (!employeeId) {
    showToast("Choose a field lead first.");
    return;
  }
  // Phase 18 item 3 — a suspended or retired device must not be usable for Front Line sign-in, not
  // merely show a badge on the register. This simulator has no real per-device hardware check, so
  // the enforcement point is here: block sign-in for an employee whose *only* devices are all
  // suspended/retired. An employee with no registered device at all (or at least one Active device)
  // can still sign in — the block is specifically about a known-bad device, not about registration.
  const employeeDevices = devicesForEmployee(employeeId);
  const hasUsableDevice = employeeDevices.length === 0 || employeeDevices.some((device) => !["Suspended", "Retired"].includes(device.registrationStatus));
  if (!hasUsableDevice) {
    showToast("This employee's registered device is suspended or retired. Assign or reinstate a device before signing in.");
    return;
  }
  state.frontlineSession = { employeeId, loginAt: new Date().toISOString() };
  state.view = "field-home";
  render();
}
// (Phase 12a: a session already tied to an employee skips this picker -- see render().)

function frontlineExit() {
  state.frontlineSession = null;
  state.frontlineJobFilter = { scope: "mine", region: "all" };
  state.frontlineSelectedJobId = "";
  state.frontlineOpenActionId = "";
  state.frontlineMessagingThreadKey = null;
  state.view = "home";
  render();
}

function findJobAction(actionId) {
  return (state.backend.jobActions || []).find((action) => action.id === actionId);
}

function attachmentsForAction(actionId) {
  if (!actionId) return [];
  return (state.backend.jobTaskAttachments || []).filter((attachment) => attachment.actionId === actionId);
}

// The signature is kept as stroke geometry in state, never as canvas pixels: render() rewrites the
// whole view via innerHTML, so a bitmap would be lost on any re-render. Strokes are replayed onto
// whatever canvas exists after the next paint.
function cleanupSignaturePad() {
  if (signaturePadCleanup) {
    signaturePadCleanup();
    signaturePadCleanup = null;
  }
}

function initializeSignaturePad() {
  cleanupSignaturePad();
  const canvas = document.getElementById("frontlineSignaturePad");
  if (!canvas) return;
  const context = canvas.getContext("2d");
  const paint = () => {
    context.clearRect(0, 0, canvas.width, canvas.height);
    context.lineWidth = 2;
    context.lineCap = "round";
    context.lineJoin = "round";
    context.strokeStyle = "#13241b";
    for (const stroke of state.frontlineSignatureStrokes) {
      if (stroke.length < 2) continue;
      context.beginPath();
      context.moveTo(stroke[0].x, stroke[0].y);
      for (const point of stroke.slice(1)) context.lineTo(point.x, point.y);
      context.stroke();
    }
  };
  paint();

  let active = null;
  const positionOf = (event) => {
    const rect = canvas.getBoundingClientRect();
    return {
      x: ((event.clientX - rect.left) / rect.width) * canvas.width,
      y: ((event.clientY - rect.top) / rect.height) * canvas.height,
    };
  };
  const onDown = (event) => {
    event.preventDefault();
    active = [positionOf(event)];
    canvas.setPointerCapture?.(event.pointerId);
  };
  const onMove = (event) => {
    if (!active) return;
    event.preventDefault();
    active.push(positionOf(event));
    state.frontlineSignatureStrokes = [...state.frontlineSignatureStrokes.filter((stroke) => stroke !== active), active];
    paint();
  };
  const onUp = () => {
    if (active && active.length > 1) {
      state.frontlineSignatureStrokes = [...state.frontlineSignatureStrokes.filter((stroke) => stroke !== active), active];
    }
    active = null;
    paint();
  };

  canvas.addEventListener("pointerdown", onDown);
  canvas.addEventListener("pointermove", onMove);
  canvas.addEventListener("pointerup", onUp);
  canvas.addEventListener("pointerleave", onUp);
  signaturePadCleanup = () => {
    canvas.removeEventListener("pointerdown", onDown);
    canvas.removeEventListener("pointermove", onMove);
    canvas.removeEventListener("pointerup", onUp);
    canvas.removeEventListener("pointerleave", onUp);
  };
}

function signatureToBlob() {
  const canvas = document.getElementById("frontlineSignaturePad");
  if (!canvas || !state.frontlineSignatureStrokes.length) return null;
  return new Promise((resolve) => canvas.toBlob(resolve, "image/png"));
}

async function frontlineCaptureGps() {
  const hint = document.getElementById("frontlineGpsHint");
  if (!navigator.geolocation) {
    if (hint) hint.textContent = "This device cannot provide GPS. You can still submit without it.";
    return;
  }
  if (hint) hint.textContent = "Getting a fix...";
  navigator.geolocation.getCurrentPosition(
    (position) => {
      state.frontlineGps = {
        latitude: position.coords.latitude,
        longitude: position.coords.longitude,
        accuracy: position.coords.accuracy || 0,
      };
      if (hint) {
        hint.textContent = `${state.frontlineGps.latitude.toFixed(5)}, ${state.frontlineGps.longitude.toFixed(5)} (±${Math.round(state.frontlineGps.accuracy)} m)`;
      }
    },
    (error) => {
      const reason =
        error.code === error.PERMISSION_DENIED
          ? "Location permission denied"
          : error.code === error.TIMEOUT
            ? "Location timed out"
            : "Location unavailable";
      if (hint) hint.textContent = `${reason}. You can still submit without coordinates.`;
    },
    { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 },
  );
}

// Uploads send the file as the raw request body with the metadata in headers, which is the
// contract every upload route on the server expects.
async function uploadRawFile(url, file, headers = {}) {
  return apiRequest(url, {
    method: "POST",
    body: file,
    headers: {
      "Content-Type": file.type || "application/octet-stream",
      "X-CRM-User": state.currentUser?.name || "Local user",
      "X-File-Name": encodeURIComponent(file.name || "upload.png"),
      ...headers,
    },
  });
}

async function frontlineCompleteAction(form) {
  const submitButton = form.querySelector('button[type="submit"]');
  if (submitButton?.disabled) return;
  if (submitButton) submitButton.disabled = true;

  const data = new FormData(form);
  const jobId = data.get("jobId").toString();
  const stepId = data.get("stepId").toString();
  const actionId = data.get("actionId").toString();
  const summary = (data.get("summary") || "").toString().trim();
  const action = findJobAction(actionId);
  const job = findDispatchJob(jobId);
  if (!action || !job) return;
  const config = normalizeTaskConfig(action.type, action.config);
  const fieldLead = findEmployee(state.frontlineSession?.employeeId);
  const submittedBy = fieldLead?.displayName || "Front Line";
  const files = [...(form.elements.photos?.files || [])];

  if (action.type === "Photo" && files.length < Number(config.minPhotos)) {
    showToast(`This task needs at least ${Number(config.minPhotos)} photo${Number(config.minPhotos) === 1 ? "" : "s"}.`);
    if (submitButton) submitButton.disabled = false;
    return;
  }
  if (action.type === "Signature" && !state.frontlineSignatureStrokes.length) {
    showToast("Capture a signature before submitting.");
    if (submitButton) submitButton.disabled = false;
    return;
  }
  if (action.type === "Sample") {
    const hasAll = form.elements.northViewPhoto?.files?.[0] && form.elements.intervalPhoto?.files?.[0] && form.elements.containerLabelPhoto?.files?.[0];
    if (!hasAll) {
      showToast("North view, sample interval, and container label photos are all required.");
      if (submitButton) submitButton.disabled = false;
      return;
    }
  }
  if (action.type === "Odometer") {
    const startOdometer = Number(data.get("startOdometer") || 0);
    const arrivalOdometer = Number(data.get("arrivalOdometer") || 0);
    if (arrivalOdometer < startOdometer) {
      showToast("Arrival odometer can't be less than the start odometer.");
      if (submitButton) submitButton.disabled = false;
      return;
    }
  }

  const payload = buildTaskPayload(action, config, data, form);

  // Gap item "PPE quantity handling" (Phase 10, Part 2): never block on a resulting negative
  // balance -- confirm with the worker, and if they proceed, force it through and let the server
  // flag the ops manager (inventoryAlerts). Declining just returns them to the form to fix the qty.
  if (action.type === "Material" && payload.materials?.length) {
    for (const line of payload.materials) {
      if (line.writeInName) continue;
      const item = findInventoryItem(line.inventoryItemId);
      if (!item) continue;
      if (Number(item.onHand || 0) - Number(line.quantity) < 0) {
        const proceed = window.confirm(
          `This will take ${item.materialType} negative (${Number(item.onHand || 0)} ${item.unit} on hand, ${line.quantity} requested). Log it anyway and flag the ops manager?`,
        );
        if (!proceed) {
          if (submitButton) submitButton.disabled = false;
          showToast("Adjust the quantity, or confirm to log it as negative inventory.");
          return;
        }
        line.force = true;
      }
    }
  }

  try {
    // Attachments upload first so they are self-describing by actionId: if a later write fails the
    // files are still recoverable, rather than a submission pointing at ids that never landed.
    for (const file of files) {
      await uploadRawFile(`/api/job-actions/${encodeURIComponent(actionId)}/attachments`, file, {
        "X-Attachment-Kind": "photo",
        "X-Caption": encodeURIComponent(summary.slice(0, 120)),
      });
    }
    if (action.type === "Signature") {
      const blob = await signatureToBlob();
      if (blob) {
        const file = new File([blob], `signature-${actionId}.png`, { type: "image/png" });
        await uploadRawFile(`/api/job-actions/${encodeURIComponent(actionId)}/attachments`, file, {
          "X-Attachment-Kind": "signature",
          "X-Caption": encodeURIComponent(payload.signedBy || ""),
        });
      }
    }
    if (action.type === "Material" && payload.materials?.length) {
      await apiRequest(`/api/job-actions/${encodeURIComponent(actionId)}/consume`, {
        method: "POST",
        body: JSON.stringify({ items: payload.materials }),
        headers: { "X-CRM-User": submittedBy },
      });
    }
    if (action.type === "Sample") {
      const namedPhotos = [
        { file: form.elements.northViewPhoto?.files?.[0], caption: "North view" },
        { file: form.elements.intervalPhoto?.files?.[0], caption: "Sample interval" },
        { file: form.elements.containerLabelPhoto?.files?.[0], caption: "Container label" },
      ];
      for (const { file, caption } of namedPhotos) {
        if (!file) continue;
        await uploadRawFile(`/api/job-actions/${encodeURIComponent(actionId)}/attachments`, file, {
          "X-Attachment-Kind": "photo",
          "X-Caption": encodeURIComponent(caption),
        });
      }
      await saveSampleFromTask(action, job, data, summary, submittedBy);
    }
    if (action.type === "Odometer") {
      await saveBackendRecord(
        "jobMileageEntries",
        {
          id: makeId("mileage"),
          employeeId: fieldLead?.id || "",
          dispatchJobId: jobId,
          mileageType: "job",
          beginningOdometer: payload.startOdometer,
          endingOdometer: payload.arrivalOdometer,
          calculatedDistance: payload.calculatedDistance,
          capturedAt: new Date().toISOString(),
          notes: `${payload.siteLabel}${summary ? ` — ${summary}` : ""}`,
        },
        { refresh: false },
      );
    }
    if (action.type === "Timer" && fieldLead && Number(payload.hours) > 0) {
      // The labor section's hoursWorked was previously only ever carried over unchanged from the
      // existing value in saveEmployee — nothing wrote to it when a worker was scheduled or when they
      // actually logged time in the field, so it silently never tracked real hours (item 12). A Timer
      // task submission is the one place the app captures real logged hours, so that's where this adds
      // the write.
      await saveBackendRecord(
        "employees",
        { ...fieldLead, hoursWorked: Number(fieldLead.hoursWorked || 0) + Number(payload.hours) },
        { refresh: false },
      );
    }

    await saveBackendRecord(
      "jobFormSubmissions",
      {
        id: makeId("form-sub"),
        jobId,
        actionId,
        formName: action.formName || action.name,
        status: "Submitted",
        submittedBy,
        submittedAt: new Date().toISOString(),
        summary: summary || describeTaskPayload(action.type, payload),
        payload,
      },
      { refresh: false },
    );
    await frontlineMarkActionComplete(actionId);
    await frontlineAdvanceStepIfComplete(stepId, [actionId]);
    await refreshBackendState();
    await frontlineAutoAdvanceJob(jobId, stepId);

    state.frontlineOpenActionId = "";
    state.frontlineSignatureStrokes = [];
    state.frontlineGps = null;
    render();
    showToast("Submitted -- visible on the job's dispatch dashboard now.");
  } catch (error) {
    if (submitButton) submitButton.disabled = false;
    showToast(error.message || "Could not submit.");
  }
}

function buildTaskPayload(action, config, data, form) {
  if (action.type === "Checklist") {
    const checked = data.getAll("checklistOption").map((value) => value.toString());
    return { options: config.options, checked, unchecked: config.options.filter((option) => !checked.includes(option)) };
  }
  if (action.type === "Signature") {
    return { signerRole: config.signerRole, signedBy: (data.get("signedBy") || "").toString().trim() };
  }
  if (action.type === "Timer") {
    return {
      hours: Number(data.get("hours") || 0),
      computedHours: Number(data.get("computedHours") || 0),
      anchor: (data.get("timerAnchor") || "").toString(),
    };
  }
  if (action.type === "Material") {
    // Gap item "PPE quantity handling" (Phase 10, Part 2): a row is either a catalog pick
    // (inventoryItemId) or a free-text write-in (materialWriteInName) alongside it -- write-ins never
    // touch inventory on-hand, they are just tracked as used, per the owner's ask.
    const ids = data.getAll("materialItemId").map((value) => value.toString());
    const quantities = data.getAll("materialQuantity").map((value) => Number(value));
    const writeInNames = data.getAll("materialWriteInName").map((value) => value.toString().trim());
    const writeInUnits = data.getAll("materialWriteInUnit").map((value) => value.toString().trim());
    const materials = ids
      .map((inventoryItemId, index) => {
        const quantity = quantities[index];
        if (!Number.isFinite(quantity) || quantity <= 0) return null;
        const writeInName = writeInNames[index];
        if (writeInName) return { writeInName, unit: writeInUnits[index] || "", quantity };
        if (!inventoryItemId) return null;
        return { inventoryItemId, quantity };
      })
      .filter(Boolean);
    return {
      materials,
      lines: materials.map((entry) =>
        entry.writeInName
          ? { ...entry, name: entry.writeInName }
          : { ...entry, name: findInventoryItem(entry.inventoryItemId)?.materialType || "Material", unit: findInventoryItem(entry.inventoryItemId)?.unit || "" },
      ),
    };
  }
  if (action.type === "Photo") {
    return { photoCount: [...(form.elements.photos?.files || [])].length, minPhotos: Number(config.minPhotos) };
  }
  if (action.type === "Sample") {
    return { sampleId: (data.get("sampleId") || "").toString().trim() };
  }
  if (action.type === "Odometer") {
    const startOdometer = Number(data.get("startOdometer") || 0);
    const arrivalOdometer = Number(data.get("arrivalOdometer") || 0);
    return {
      siteLabel: (data.get("siteLabel") || "").toString().trim(),
      startOdometer,
      arrivalOdometer,
      calculatedDistance: Math.max(0, arrivalOdometer - startOdometer),
    };
  }
  return {};
}

function describeTaskPayload(type, payload) {
  if (type === "Checklist") return `${payload.checked.length} of ${payload.options.length} checked.`;
  if (type === "Timer") return `${payload.hours} hours logged.`;
  if (type === "Material") return `${payload.lines.map((line) => `${line.quantity} ${line.unit} ${line.name}`).join(", ")}.`;
  if (type === "Photo") return `${payload.photoCount} photo${payload.photoCount === 1 ? "" : "s"} attached.`;
  if (type === "Signature") return `Signed by ${payload.signedBy}.`;
  if (type === "Odometer") return `${payload.siteLabel || "Leg"}: ${payload.calculatedDistance} mi (${payload.startOdometer} to ${payload.arrivalOdometer}).`;
  if (type === "Equipment usage") return `${payload.assetTag || "Equipment"}: ${payload.hours ? `${payload.hours} hrs` : payload.days ? `${payload.days} day${payload.days === 1 ? "" : "s"}` : "logged"}${payload.condition ? ` · ${payload.condition}` : ""}.`;
  if (type === "Waste") return `${payload.containerType || "Container"}${payload.count ? ` x${payload.count}` : ""}${payload.contents ? `: ${payload.contents}` : ""}${payload.manifestNumber ? ` · manifest ${payload.manifestNumber}` : ""}.`;
  return "Completed in Front Line.";
}

// ---- Phase 10, Part 2: "+ Activity" ad hoc capture ----
//
// Gap item 4: the template-driven work plan stays primary, but a field worker can add a note, extra
// sample, signature, photo, or travel leg that doesn't fit a predefined template step. Rather than
// build a second, parallel data model for "things that happened on a job outside the template," this
// creates a real jobActions row on the fly (filed under one shared, hidden "Additional field
// activity" step per job that never gates the real work plan) and reuses every existing
// attachment/consume/sample write path unchanged. That is the concrete design implication the phase
// doc's gap item flagged: the template no longer fully describes what jobActions can exist for a job.
function renderFrontlineAdHocCaptureForm(type, job) {
  const config = normalizeTaskConfig(type, {});
  const notes = (label, placeholder, required = true) => `
    <label>${escapeHtml(label)}
      <textarea name="summary" placeholder="${escapeAttribute(placeholder)}" ${required ? "required" : ""}></textarea>
    </label>
  `;
  let fields = "";
  if (type === "Note") {
    fields = notes("Note", "What's worth flagging that doesn't fit the template?");
  } else if (type === "Photo") {
    fields = `
      <label>Photos
        <input type="file" name="photos" accept="image/png,image/jpeg" multiple required />
      </label>
      ${notes("What do these show?", "Before, progress, after...", false)}
    `;
  } else if (type === "Signature") {
    fields = `
      <label>Signature
        <canvas id="frontlineSignaturePad" class="frontline-signature-pad" width="360" height="150"></canvas>
      </label>
      <div class="inline-actions">
        <button class="mini-button" type="button" data-action="frontline-clear-signature">Clear</button>
      </div>
      <label>Signed by
        <input name="signedBy" maxlength="90" placeholder="Print name" required />
      </label>
      ${notes("Notes", "Anything the signer said?", false)}
    `;
  } else if (type === "Sample") {
    fields = renderFrontlineSampleCapture(null, job, config);
  } else if (type === "Odometer") {
    fields = `
      <div class="form-grid">
        <label>Site / relocation label
          <input name="siteLabel" maxlength="90" placeholder="e.g. Site C, third relocation" required />
        </label>
        <label>Start odometer
          <input type="number" name="startOdometer" min="0" step="1" required />
        </label>
        <label>Arrival odometer
          <input type="number" name="arrivalOdometer" min="0" step="1" required />
        </label>
      </div>
      ${notes("Notes", "Anything about this leg?", false)}
    `;
  }
  return `
    <form class="frontline-action-form" data-form="frontline-adhoc-activity">
      <input type="hidden" name="jobId" value="${escapeAttribute(job.id)}" />
      <input type="hidden" name="activityType" value="${escapeAttribute(type)}" />
      ${fields}
      <div class="inline-actions">
        <button class="mini-button" type="button" data-action="frontline-adhoc-cancel">Cancel</button>
        <button class="primary-button" type="submit">Add to job</button>
      </div>
    </form>
  `;
}

async function ensureFrontlineAdHocStep(jobId) {
  const existing = (state.backend.jobSteps || []).find((step) => step.jobId === jobId && step.adHoc);
  if (existing) return existing;
  const allSteps = stepsForDispatchJob(jobId);
  return saveBackendRecord(
    "jobSteps",
    {
      id: makeId("job-step"),
      jobId,
      name: "Additional field activity",
      // Sorts after every template step but is filtered out of the rendered work-plan list --
      // see renderFrontlineJobDetail -- so it never appears as something to "complete in order."
      sequence: (allSteps[allSteps.length - 1]?.sequence || 0) + 1000,
      status: "Complete",
      adHoc: true,
    },
    { refresh: false },
  );
}

async function frontlineSubmitAdHocActivity(form) {
  const submitButton = form.querySelector('button[type="submit"]');
  if (submitButton?.disabled) return;
  if (submitButton) submitButton.disabled = true;

  const data = new FormData(form);
  const jobId = data.get("jobId").toString();
  const type = data.get("activityType").toString();
  const job = findDispatchJob(jobId);
  if (!job) return;
  const summary = (data.get("summary") || "").toString().trim();
  const fieldLead = findEmployee(state.frontlineSession?.employeeId);
  const submittedBy = fieldLead?.displayName || "Front Line";
  const files = [...(form.elements.photos?.files || [])];

  if (type === "Photo" && !files.length) {
    showToast("Attach at least one photo.");
    if (submitButton) submitButton.disabled = false;
    return;
  }
  if (type === "Signature" && !state.frontlineSignatureStrokes.length) {
    showToast("Capture a signature before submitting.");
    if (submitButton) submitButton.disabled = false;
    return;
  }
  if (type === "Sample") {
    const hasAll = form.elements.northViewPhoto?.files?.[0] && form.elements.intervalPhoto?.files?.[0] && form.elements.containerLabelPhoto?.files?.[0];
    if (!hasAll) {
      showToast("North view, sample interval, and container label photos are all required.");
      if (submitButton) submitButton.disabled = false;
      return;
    }
  }
  if (type === "Odometer") {
    const startOdometer = Number(data.get("startOdometer") || 0);
    const arrivalOdometer = Number(data.get("arrivalOdometer") || 0);
    if (arrivalOdometer < startOdometer) {
      showToast("Arrival odometer can't be less than the start odometer.");
      if (submitButton) submitButton.disabled = false;
      return;
    }
  }

  try {
    const adHocStep = await ensureFrontlineAdHocStep(job.id);
    const existingAdHocActions = actionsForDispatchStep(adHocStep.id);
    const action = await saveBackendRecord(
      "jobActions",
      {
        id: makeId("job-action"),
        jobId: job.id,
        stepId: adHocStep.id,
        sequence: existingAdHocActions.length + 1,
        name: `Ad hoc: ${type}`,
        formName: `Ad hoc: ${type}`,
        type,
        assigneeScope: "Any assigned worker",
        status: "Complete",
        adHoc: true,
        config: {},
      },
      { refresh: false },
    );

    const config = normalizeTaskConfig(type, {});
    const payload = buildTaskPayload({ type }, config, data, form);

    for (const file of files) {
      await uploadRawFile(`/api/job-actions/${encodeURIComponent(action.id)}/attachments`, file, {
        "X-Attachment-Kind": "photo",
        "X-Caption": encodeURIComponent(summary.slice(0, 120)),
      });
    }
    if (type === "Signature") {
      const blob = await signatureToBlob();
      if (blob) {
        const file = new File([blob], `signature-${action.id}.png`, { type: "image/png" });
        await uploadRawFile(`/api/job-actions/${encodeURIComponent(action.id)}/attachments`, file, {
          "X-Attachment-Kind": "signature",
          "X-Caption": encodeURIComponent(payload.signedBy || ""),
        });
      }
    }
    if (type === "Sample") {
      const namedPhotos = [
        { file: form.elements.northViewPhoto?.files?.[0], caption: "North view" },
        { file: form.elements.intervalPhoto?.files?.[0], caption: "Sample interval" },
        { file: form.elements.containerLabelPhoto?.files?.[0], caption: "Container label" },
      ];
      for (const { file, caption } of namedPhotos) {
        if (!file) continue;
        await uploadRawFile(`/api/job-actions/${encodeURIComponent(action.id)}/attachments`, file, {
          "X-Attachment-Kind": "photo",
          "X-Caption": encodeURIComponent(caption),
        });
      }
      await saveSampleFromTask(action, job, data, summary, submittedBy);
    }
    if (type === "Odometer") {
      await saveBackendRecord(
        "jobMileageEntries",
        {
          id: makeId("mileage"),
          employeeId: fieldLead?.id || "",
          dispatchJobId: job.id,
          mileageType: "job",
          beginningOdometer: payload.startOdometer,
          endingOdometer: payload.arrivalOdometer,
          calculatedDistance: payload.calculatedDistance,
          capturedAt: new Date().toISOString(),
          notes: `${payload.siteLabel}${summary ? ` — ${summary}` : ""}`,
        },
        { refresh: false },
      );
    }

    await saveBackendRecord(
      "jobFormSubmissions",
      {
        id: makeId("form-sub"),
        jobId: job.id,
        actionId: action.id,
        formName: `Ad hoc: ${type}`,
        status: "Submitted",
        submittedBy,
        submittedAt: new Date().toISOString(),
        summary: summary || describeTaskPayload(type, payload),
        payload,
        adHoc: true,
      },
      { refresh: false },
    );

    await refreshBackendState();
    state.frontlineAdHocType = "";
    state.frontlineSignatureStrokes = [];
    state.frontlineGps = null;
    render();
    showToast("Added to the job -- visible on the dispatch dashboard now.");
  } catch (error) {
    if (submitButton) submitButton.disabled = false;
    showToast(error.message || "Could not add that activity.");
  }
}

// A sample is a real record, not just a submission: it lands on the dispatch job AND on the
// operations project the job belongs to, so it shows up in the project and account sample lists.
async function saveSampleFromTask(action, job, data, summary, submittedBy) {
  const collectionTime = (data.get("collectionTime") || "").toString();
  const analyses = (data.get("requestedAnalyses") || "")
    .toString()
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
  await saveBackendRecord(
    "sampleRecords",
    {
      id: makeId("sample"),
      sampleId: (data.get("sampleId") || "").toString().trim(),
      samplingSessionId: "",
      samplingSessionName: job.jobName || "",
      projectId: job.projectId || "",
      dispatchJobId: job.id,
      actionId: action.id,
      accountId: job.accountId || "",
      facilityId: findProject(job.projectId)?.facilityId || "",
      sampleLocation: (data.get("sampleLocation") || "").toString().trim(),
      sampleType: (data.get("sampleType") || "").toString().trim() || "Field sample",
      sampleMatrix: (data.get("sampleMatrix") || "").toString().trim(),
      collectionMethod: (data.get("collectionMethod") || "").toString().trim(),
      depthInterval: (data.get("depthInterval") || "").toString().trim(),
      collectionTime: collectionTime ? new Date(collectionTime).toISOString() : new Date().toISOString(),
      collector: (data.get("collector") || "").toString().trim() || submittedBy,
      gpsAccuracyMeters: state.frontlineGps?.accuracy || 0,
      latitude: state.frontlineGps?.latitude || 0,
      longitude: state.frontlineGps?.longitude || 0,
      containerSummary: (data.get("containerSummary") || "").toString().trim(),
      preservation: (data.get("preservation") || "").toString().trim(),
      requestedAnalyses: analyses,
      fieldNotes: summary,
      chainOfCustody: (data.get("chainOfCustody") || "").toString().trim(),
      labName: "",
      labStatus: "Logged in field",
      labResults: "",
      photos: [],
    },
    { refresh: false },
  );
}

// Phase 25 A.1 (2026-09-29): the status move goes through advanceJobFromField() (field/job.js) -- the
// POST /api/field/jobs/:id/advance command through the offline outbox, the same path as the phone's
// bottom button -- not advanceDispatchJob(), whose raw dispatchJobs save a field login can't make
// (the server drops `status`, then 403s the jobStatusEvents write, and the success toast hid it).
async function frontlineCompleteStatusAction(actionId) {
  const action = findJobAction(actionId);
  if (!action) return;
  const { jobId, stepId } = action;
  try {
    await frontlineMarkActionComplete(actionId);
    await frontlineAdvanceStepIfComplete(stepId, [actionId]);
    await refreshBackendState();
  } catch (error) {
    render();
    showToast(error.message || "Could not record that step.");
    return;
  }
  const job = findDispatchJob(jobId);
  const transition = getNextDispatchTransition(job?.status);
  if (transition?.status !== "acknowledged") {
    render();
    showToast(`${action.name} recorded.`);
    return;
  }
  const result = await advanceJobFromField(jobId, transition.status);
  render();
  if (!result.ok) showToast(`${action.name} recorded, but the job is still ${formatDispatchStatus(job.status)}: ${result.reason || "the status change was refused."}`);
  else if (result.queued) showToast(`${action.name} recorded -- offline, so the job will be acknowledged when the phone syncs.`);
  else showToast(`${action.name} -- job is now ${formatDispatchStatus(result.job?.status || transition.status)}.`);
}

// These chain several writes without refetching between them, so they must not re-read a record
// they have already written. Instead the caller passes the ids it just completed and they are
// treated as complete locally; the caller refreshes once when the whole chain is done.
async function frontlineMarkActionComplete(actionId) {
  const action = findJobAction(actionId);
  if (!action || action.status === "Complete") return;
  await saveBackendRecord("jobActions", { ...action, status: "Complete" }, { refresh: false });
  const nextAction = actionsForDispatchStep(action.stepId).find(
    (candidate) => candidate.id !== actionId && candidate.status !== "Complete",
  );
  if (nextAction) {
    await saveBackendRecord("jobActions", { ...nextAction, status: "Available" }, { refresh: false });
  }
}

async function frontlineAdvanceStepIfComplete(stepId, completedActionIds = []) {
  const step = (state.backend.jobSteps || []).find((item) => item.id === stepId);
  if (!step || step.status === "Complete") return;
  const outstanding = actionsForDispatchStep(stepId).filter(
    (action) => action.required !== false && action.status !== "Complete" && !completedActionIds.includes(action.id),
  );
  if (outstanding.length) return;
  await saveBackendRecord("jobSteps", { ...step, status: "Complete" }, { refresh: false });
  const nextStep = stepsForDispatchJob(step.jobId).find((candidate) => Number(candidate.sequence) === Number(step.sequence) + 1);
  if (!nextStep || nextStep.status === "Complete") return;
  await saveBackendRecord("jobSteps", { ...nextStep, status: "Available" }, { refresh: false });
  const firstAction = actionsForDispatchStep(nextStep.id).find((action) => action.status !== "Complete");
  if (firstAction) {
    await saveBackendRecord("jobActions", { ...firstAction, status: "Available" }, { refresh: false });
  }
}

function renderQueueItem(item) {
  return `
    <article class="queue-item">
      <strong>${escapeHtml(item.entity)} ${escapeHtml(item.action)}</strong>
      <div class="sync-meta">
        <span>${formatDate(item.createdAt)}</span>
        <span>${escapeHtml(item.status)}</span>
      </div>
    </article>
  `;
}

async function saveOpportunity(form) {
  const data = new FormData(form);
  const existingId = data.get("id").toString();
  const pauseBlock = !existingId ? accountPauseBlock((data.get("accountId") || "").toString(), "pauseOpportunities") : "";
  if (pauseBlock) {
    showToast(pauseBlock);
    return;
  }
  const existing = existingId ? findOpportunity(existingId) : null;
  const previousStage = existing?.stage || "";
  const stage = existing ? existing.stage : data.get("startingStage")?.toString() || "Lead";
  // Item 26 — closeBandSetAt only moves when the band itself actually changes, not on every save
  // of an unrelated field. That's what keeps the staleness reading ("set N days ago") meaningful.
  const newCloseBand = (data.get("closeBand") || "").toString();
  const closeBandChanged = (existing?.closeBand || "") !== newCloseBand;
  const opportunity = buildCoreOpportunityRecord({
    ...(existing || {}),
    id: existingId || makeId("opp"),
    accountId: (data.get("accountId") || "").toString(),
    name: data.get("name").toString().trim(),
    opportunityName: data.get("name").toString().trim(),
    value: Number(data.get("value")),
    amount: Number(data.get("value")),
    closeBand: newCloseBand,
    closeBandSetAt: closeBandChanged ? (newCloseBand ? new Date().toISOString() : "") : existing?.closeBandSetAt || "",
    stage,
    dealStage: stage,
    probability: STAGE_PROBABILITY[stage],
    closeProbability: STAGE_PROBABILITY[stage],
    serviceType: (data.get("serviceType") || "").toString(),
    status: stage === "Won" ? "Won" : (data.get("status") || "").toString(),
    nextStep: data.get("nextStep").toString().trim(),
    customerNeed: data.get("customerNeed").toString().trim(),
    weightedAmount: undefined,
    forecastAmount: undefined,
    rating: undefined,
    updatedAt: new Date().toISOString(),
  });

  try {
    await saveBackendRecord("opportunities", opportunity);
  } catch (error) {
    showToast(error.message || "Opportunity could not be saved.");
    return;
  }
  await queueChange("Opportunity", existing ? "updated" : "created", opportunity);
  if (opportunity.status === "Lost" && existing?.status !== "Lost") {
    await autoArchiveStakeholdersOnClose(opportunity.id);
    await closeProjectsForLostOpportunity(opportunity.id);
  }
  closeDialogs();
  await refreshState();
  viewOpportunity(opportunity.id);
  showToast(existing ? "Opportunity updated." : "Opportunity saved.");
  await maybeOfferProjectForWonOpportunity(previousStage, opportunity);
}

async function saveAccount(form) {
  const data = new FormData(form);
  const existingId = data.get("id").toString();
  const existing = existingId ? findAccount(existingId) : null;
  const now = new Date().toISOString();
  const businessDescription = data.get("businessDescription").toString().trim();
  const ownerEmployeeId = (data.get("ownerEmployeeId") || "").toString();
  const ownerName = ownerEmployeeId === "system" ? "System" : ownerEmployeeId ? findEmployee(ownerEmployeeId)?.displayName || "" : "";
  const industryId = (data.get("industryId") || "").toString();
  const enteredCity = data.get("addressCity").toString().trim();
  const enteredState = data.get("addressState").toString().trim();
  const account = buildCoreAccountRecord({
    ...(existing || {}),
    id: existingId || makeId("acct"),
    name: data.get("name").toString().trim(),
    accountName: data.get("name").toString().trim(),
    website: data.get("website").toString().trim(),
    accountType: (data.get("accountType") || "").toString(),
    contact: existing?.contact || "",
    email: data.get("email").toString().trim(),
    phone: data.get("phone").toString().trim(),
    mainPhoneNumber: data.get("phone").toString().trim(),
    faxNumber: data.get("fax").toString().trim(),
    parentAccountId: (data.get("parentAccountId") || "").toString(),
    city: enteredCity || existing?.city || "",
    addressOneCity: enteredCity || existing?.addressOneCity || "",
    addressOneState: enteredState || existing?.addressOneState || "",
    concern: data.get("concern").toString().trim(),
    // Phase 11 (2026-09-23): optional override for the customer name a real QuickBooks export uses;
    // blank means the export falls back to the account name.
    qboCustomerName: data.get("qboCustomerName").toString().trim(),
    owner: ownerName || existing?.owner || "Unassigned",
    ownerEmployeeId: ownerEmployeeId === "system" ? "system" : ownerEmployeeId || existing?.ownerEmployeeId || "",
    lastContact: existing?.lastContact || todayIso(),
    nextAction: existing?.nextAction || "Qualify cleanup scope and decision process",
    createdBy: existing?.createdBy || state.currentUser?.name || "Local user",
    createdOn: existing?.createdOn || now,
  });

  await saveBackendRecord("accounts", account, { refresh: false });

  if (industryId) {
    const currentLinks = industriesForAccount(account.id);
    const existingLink = currentLinks.find((link) => link.industryId === industryId);
    await saveBackendRecord("accountIndustries", {
      id: existingLink?.id || makeId("acct-industry"),
      accountId: account.id,
      industryId,
      isPrimary: true,
      deletedAt: "",
    });
    for (const link of currentLinks) {
      if (link.industryId !== industryId && link.isPrimary) {
        await saveBackendRecord("accountIndustries", { ...link, isPrimary: false });
      }
    }
  }

  const addressStreet1 = data.get("addressStreet1").toString().trim();
  const addressCity = data.get("addressCity").toString().trim();
  const addressState = data.get("addressState").toString().trim();
  const addressPostalCode = data.get("addressPostalCode").toString().trim();
  const addressCountry = data.get("addressCountry").toString().trim();
  if (addressStreet1 || addressCity || addressState || addressPostalCode) {
    const existingPrimary = addressesForAccount(account.id).find((address) => address.isPrimary);
    await saveBackendRecord("addresses", {
      id: existingPrimary?.id || makeId("address"),
      accountId: account.id,
      addressName: existingPrimary?.addressName || "Primary address",
      addressType: existingPrimary?.addressType || "Primary",
      isPrimary: true,
      suiteNumber: existingPrimary?.suiteNumber || "",
      street1: addressStreet1,
      street2: existingPrimary?.street2 || "",
      street3: existingPrimary?.street3 || "",
      city: addressCity,
      county: existingPrimary?.county || "",
      stateOrProvince: addressState,
      postalCode: addressPostalCode,
      countryOrRegion: addressCountry || existingPrimary?.countryOrRegion || "United States",
      phone: existingPrimary?.phone || "",
      latitude: existingPrimary?.latitude ?? null,
      longitude: existingPrimary?.longitude ?? null,
      freightTerms: existingPrimary?.freightTerms || "",
      shippingMethod: existingPrimary?.shippingMethod || "",
      contactId: existingPrimary?.contactId || "",
      deliveryInstructions: existingPrimary?.deliveryInstructions || "",
    });
  }

  if (businessDescription) {
    await saveRelationshipExtensionPatch(account.id, { businessDescription });
  }
  await queueChange("Account", existing ? "updated" : "created", account);
  closeDialogs();
  await refreshState({ backend: false });
  state.selectedAccountId = account.id;
  state.view = "account-detail";
  render();
  showToast(existing ? "Account updated." : "Account saved. Add a facility from the Locations & Addresses tab when you're ready.");
}

