async function receivePurchaseOrder(orderId) {
  const order = getPurchaseOrders().find((item) => item.id === orderId);
  if (!order) {
    showToast("Purchase order was not found.");
    return;
  }

  try {
    const result = await apiRequest(`/api/purchase-orders/${encodeURIComponent(orderId)}/receive`, {
      method: "POST",
      body: JSON.stringify({
        receivedBy: state.currentUser?.name || "Local user",
      }),
    });
    await refreshBackendState();
    render();
    const item = result.inventoryItem;
    showToast(`${order.materialType} received. On hand is now ${item?.onHand ?? "updated"}.`);
  } catch (error) {
    showToast(error.message || "Purchase order could not be received.");
  }
}

async function saveEquipmentAsset(form) {
  const data = new FormData(form);
  const id = data.get("id").toString();
  const existing = id ? getEquipmentStatus().find((item) => item.id === id) : null;
  const specs = {};
  form.querySelectorAll("[data-spec-key]").forEach((input) => {
    const value = input.value.trim();
    if (value) specs[input.dataset.specKey] = value;
  });
  try {
    await saveBackendRecord("equipmentAssets", {
      id,
      assetTag: data.get("assetTag").toString().trim(),
      equipment: data.get("equipment").toString().trim(),
      category: (data.get("category") || "").toString() || "General equipment",
      status: (data.get("status") || "").toString(),
      lastUsed: data.get("lastUsed").toString(),
      maintenanceDue: data.get("maintenanceDue").toString(),
      issue: data.get("issue").toString().trim(),
      assignedProjectId: existing?.assignedProjectId || "",
      productId: data.get("productId")?.toString() || "",
      ownership: (data.get("ownership") || "").toString() || existing?.ownership || "Owned",
      specs,
      // Phase 11 (2026-09-23): PM interval + meter plan. This form is the only place a user can
      // edit or clear these, so we read them straight from the form rather than falling back to
      // `existing` (a fallback would make it impossible to ever clear a value here).
      pmIntervalDays: numberOrNull(data.get("pmIntervalDays")),
      pmIntervalMeter: numberOrNull(data.get("pmIntervalMeter")),
      meterUnit: data.get("meterUnit")?.toString() || "",
      currentMeter: numberOrNull(data.get("currentMeter")),
      maintenanceDueMeter: numberOrNull(data.get("maintenanceDueMeter")),
    });
    const newTag = data.get("assetTag").toString().trim();
    if (existing && existing.assetTag && newTag && existing.assetTag !== newTag) {
      const touched = await cascadeAssetTagRename(existing.assetTag, newTag);
      await refreshBackendState();
      closeDialogs();
      render();
      showToast(`Equipment asset saved. ${touched} record${touched === 1 ? "" : "s"} moved from ${existing.assetTag} to ${newTag}.`);
      return;
    }
    closeDialogs();
    render();
    showToast("Equipment asset saved on the backend.");
  } catch (error) {
    showToast(error.message || "Equipment asset could not be saved.");
  }
}

// The asset tag is the key every log, dispatch resource, maintenance record, restock item and GPS
// point uses for equipment, so a rename has to follow it everywhere (found 2026-09-23: "VAC-204"
// had been renamed "VAC TRAILER - 204" and its history detached).
async function cascadeAssetTagRename(oldTag, newTag) {
  let touched = 0;
  const update = async (collection, rows, patch) => {
    for (const row of rows) {
      await saveBackendRecord(collection, patch(row), { refresh: false });
      touched += 1;
    }
  };
  await update("equipmentLogs", (state.backend.equipmentLogs || []).filter((row) => row.assetTag === oldTag), (row) => ({ ...row, assetTag: newTag }));
  await update("jobResources", (state.backend.jobResources || []).filter((row) => row.assetTag === oldTag), (row) => ({ ...row, assetTag: newTag }));
  await update("equipmentMaintenanceRecords", (state.backend.equipmentMaintenanceRecords || []).filter((row) => row.assetTag === oldTag), (row) => ({ ...row, assetTag: newTag }));
  await update("equipmentRestockItems", (state.backend.equipmentRestockItems || []).filter((row) => row.assetTag === oldTag), (row) => ({ ...row, assetTag: newTag }));
  await update("locations", (state.backend.locations || []).filter((row) => (row.assetTags || []).includes(oldTag)), (row) => ({ ...row, assetTags: row.assetTags.map((tag) => (tag === oldTag ? newTag : tag)) }));
  return touched;
}

// Phase 11 (2026-09-23): the dialog's Type options ("Scheduled service", "Repair", "Inspection",
// "Decontamination", "Other") have no dedicated "Preventive maintenance" entry — "Scheduled
// service" is the existing stand-in for it, so that's what qualifies a record for PM-interval math.
const PM_MAINTENANCE_TYPE = "Scheduled service";

async function saveEquipmentMaintenanceRecord(form) {
  const data = new FormData(form);
  const assetTag = data.get("assetTag").toString().trim();
  const type = (data.get("type") || "").toString();
  const date = data.get("date").toString() || todayIso();
  const status = data.get("status")?.toString() || "Completed";
  const meterReading = numberOrNull(data.get("meterReading"));
  const meterUnit = data.get("meterUnit")?.toString() || "hours";
  let nextDueDate = data.get("nextDueDate").toString();
  const asset = findEquipmentAssetByTag(assetTag);

  // If this is a completed PM/service record on an asset with a PM interval configured, and the
  // user left "Next due" blank, compute both the next due date and next due meter from the
  // interval instead of leaving the asset's plan stale.
  let nextDueMeter = asset?.maintenanceDueMeter ?? null;
  if (asset && status === "Completed" && type === PM_MAINTENANCE_TYPE && !nextDueDate) {
    if (asset.pmIntervalDays) nextDueDate = addDaysFrom(date, Number(asset.pmIntervalDays));
    if (meterReading != null && asset.pmIntervalMeter) nextDueMeter = meterReading + Number(asset.pmIntervalMeter);
  }

  try {
    await saveBackendRecord("equipmentMaintenanceRecords", {
      assetTag,
      type,
      date,
      description: data.get("description").toString().trim(),
      performedBy: data.get("performedBy").toString().trim() || state.currentUser?.name || "Local user",
      cost: Number(data.get("cost") || 0),
      nextDueDate,
      vendor: data.get("vendor")?.toString().trim() || "",
      workOrderNumber: data.get("workOrderNumber")?.toString().trim() || "",
      meterReading,
      meterUnit,
      downtimeHours: Number(data.get("downtimeHours") || 0),
      status,
    });

    if (asset) {
      const assetUpdates = { ...asset };
      let changed = false;
      if (nextDueDate) {
        assetUpdates.maintenanceDue = nextDueDate;
        changed = true;
      }
      if (nextDueMeter != null && Number(nextDueMeter) !== Number(asset.maintenanceDueMeter ?? NaN)) {
        assetUpdates.maintenanceDueMeter = nextDueMeter;
        changed = true;
      }
      // Any record with a meter reading higher than the asset's current meter moves it forward,
      // regardless of maintenance type/status — it's evidence of usage, not just PM bookkeeping.
      if (meterReading != null && meterReading > Number(asset.currentMeter || 0)) {
        assetUpdates.currentMeter = meterReading;
        changed = true;
      }
      if (changed) await saveBackendRecord("equipmentAssets", assetUpdates);
    }
    closeDialogs();
    render();
    showToast("Maintenance record saved.");
  } catch (error) {
    showToast(error.message || "Maintenance record could not be saved.");
  }
}

