async function saveLocation(form) {
  const data = new FormData(form);
  // GPS or an address (owner, 2026-09-25). Half a coordinate pair is a typo, not "no GPS".
  const latitudeText = (data.get("latitude") || "").toString().trim();
  const longitudeText = (data.get("longitude") || "").toString().trim();
  const addressText = (data.get("addressText") || "").toString().trim();
  if (Boolean(latitudeText) !== Boolean(longitudeText) || (latitudeText && (!Number.isFinite(Number(latitudeText)) || !Number.isFinite(Number(longitudeText))))) {
    showToast("Enter both latitude and longitude as numbers, or leave both blank.");
    return;
  }
  if (!latitudeText && !addressText) {
    showToast("A location needs an address or a GPS point.");
    return;
  }
  const latitude = latitudeText ? Number(latitudeText) : "";
  const longitude = longitudeText ? Number(longitudeText) : "";

  const existing = findGpsLocation((data.get("id") || "").toString());
  const scheduleEventId = (data.get("scheduleEventId") || "").toString();
  const scheduleEvent = getScheduleEvents().find((event) => event.id === scheduleEventId);
  const projectId = (data.get("projectId") || "").toString() || scheduleEvent?.projectId || "";
  const assetTags = data
    .get("assetTags")
    .toString()
    .split(",")
    .map((assetTag) => assetTag.trim())
    .filter(Boolean);
  const isTemporary = form.elements.isTemporary?.checked || false;

  try {
    await saveBackendRecord("locations", {
      // Keep what this dialog doesn't edit (accountId, facilityId, reportedByEmployeeId, consentId).
      ...(existing || {}),
      id: data.get("id").toString() || "",
      accountId: findProject(projectId)?.accountId || existing?.accountId || "",
      projectId,
      scheduleEventId,
      label: data.get("label").toString().trim(),
      addressText,
      latitude,
      longitude,
      assetTags,
      status: (data.get("status") || "").toString(),
      source: data.get("source").toString() || "Manual",
      lastPingAt: new Date().toISOString(),
      locationType: (data.get("locationType") || "").toString(),
      linearReference: data.get("linearReference").toString().trim(),
      isTemporary,
      retainUntil: isTemporary ? data.get("retainUntil").toString() : "",
      retentionReason: isTemporary ? data.get("retentionReason").toString().trim() : "",
    });
    closeDialogs();
    render();
    showToast(latitudeText ? "Location saved on the map." : "Location saved. It goes on the map once it has GPS.");
  } catch (error) {
    showToast(error.message || "Location could not be saved.");
  }
}

async function saveEmployee(form) {
  const data = new FormData(form);
  const existingId = data.get("id").toString();
  const existing = existingId ? findEmployee(existingId) : null;
  const firstName = data.get("firstName").toString().trim();
  const lastName = data.get("lastName").toString().trim();
  const employee = {
    ...(existing || {}),
    id: existingId || makeId("emp"),
    employeeNumber: data.get("employeeNumber").toString().trim(),
    systemUserId: existing?.systemUserId || "",
    firstName,
    lastName,
    displayName: `${firstName} ${lastName}`.trim(),
    jobTitle: data.get("jobTitle").toString().trim(),
    employmentStatus: (data.get("employmentStatus") || "").toString(),
    employmentType: (data.get("employmentType") || "").toString(),
    primaryEmail: data.get("primaryEmail").toString().trim(),
    mobilePhone: data.get("mobilePhone").toString().trim(),
    managerEmployeeId: (data.get("managerEmployeeId") || "").toString(),
    businessUnit: (data.get("businessUnit") || "").toString(),
    teamId: (data.get("teamId") || "").toString(),
    crewId: (data.get("crewId") || "").toString(),
    homeBase: data.get("homeBase").toString().trim(),
    availabilitySummary: existing?.availabilitySummary || "Standard calendar not assigned",
    hoursWorked: existing?.hoursWorked || 0,
    capacity: existing?.capacity || 40,
    dispatchEligible: form.elements.dispatchEligible.checked,
    frontlineEnabled: form.elements.frontlineEnabled.checked,
    readinessStatus: form.elements.dispatchEligible.checked ? "Ready" : "Office",
    hireDate: data.get("hireDate").toString(),
    skills: data
      .get("skills")
      .toString()
      .split(",")
      .map((skill) => skill.trim())
      .filter(Boolean),
  };

  try {
    const saved = await saveBackendRecord("employees", employee);
    closeDialogs();
    state.selectedEmployeeId = saved.id;
    state.view = "employee-detail";
    render();
    // Item 3: crews are cert-gated. Adding/keeping someone on a crew whose required certs they
    // don't hold isn't blocked (per the owner's ask — a warning is enough), but it's flagged here
    // right when the assignment happens, not just discovered later on the crew card.
    const crew = employee.crewId ? findCrewProfile(employee.crewId) : null;
    const gaps = crew ? crewCertGapsForEmployee(crew, saved.id) : [];
    if (gaps.length) {
      showToast(`${employee.displayName} is missing required certification(s) for ${crew.name}: ${gaps.join(", ")}.`);
    } else {
      showToast(existing ? "Employee updated." : "Employee added to the workforce directory.");
    }
  } catch (error) {
    showToast(error.message || "Employee could not be saved.");
  }
}

async function saveEmployeeCredential(form) {
  const data = new FormData(form);
  const employeeId = (data.get("employeeId") || "").toString();
  const employee = findEmployee(employeeId);
  if (!employee) {
    showToast("Select a valid employee.");
    return;
  }
  const certTypeId = data.get("certTypeId")?.toString().trim();
  const certType = certTypeId ? findCertificationType(certTypeId) : null;
  if (!certTypeId || !certType) {
    showToast("Select a certification type from the catalog — add one first if it doesn't exist yet.");
    return;
  }
  const existingId = data.get("id")?.toString().trim();
  const assignmentStatus = (data.get("assignmentStatus") || "").toString();
  const record = {
    id: existingId || makeId("cert"),
    employeeId,
    certTypeId,
    // Derived from the catalog, not typed — keeps existing table/eligibility copy working.
    recordType: (data.get("recordType") || "").toString(),
    code: certType.code || certType.name,
    name: certType.name,
    number: data.get("number").toString().trim(),
    issuedOn: data.get("issuedOn").toString(),
    expiresOn: data.get("expiresOn").toString(),
    status: (data.get("status") || "").toString(),
    assignmentStatus,
    trainingStartedOn: data.get("trainingStartedOn").toString(),
    trainingCompletedOn: data.get("trainingCompletedOn").toString(),
    verified: form.elements.verified.checked,
  };

  try {
    await saveBackendRecord("employeeCertifications", record);
    const issueStatuses = [...certificationsForEmployee(employeeId).map((item) => item.status), record.status];
    const readinessStatus = issueStatuses.some((status) => ["Expired", "Suspended", "Revoked"].includes(status))
      ? "Blocked"
      : issueStatuses.includes("Expiring")
        ? "Expiring"
        : employee.dispatchEligible
          ? "Ready"
          : "Office";
    await saveBackendRecord("employees", { ...employee, readinessStatus });
    closeDialogs();
    state.selectedEmployeeId = employeeId;
    state.view = "employee-detail";
    render();
    showToast("Credential saved and dispatch readiness recalculated.");
  } catch (error) {
    showToast(error.message || "Credential could not be saved.");
  }
}

