async function saveDispatchAssignEmployee(form) {
  const data = new FormData(form);
  const jobId = data.get("jobId").toString();
  const employeeId = (data.get("employeeId") || "").toString();
  const crewId = (data.get("crewId") || "").toString();
  if (crewId) {
    const memberIds = crewMemberIds(crewId);
    try {
      let added = 0;
      for (const memberId of memberIds) {
        if (await assignEmployeeToDispatchJob(jobId, memberId, "", crewId)) added += 1;
      }
      closeDialogs();
      await refreshBackendState();
      render();
      showToast(added ? `${added} crew member${added === 1 ? "" : "s"} assigned. Adjust individuals on the job as needed.` : "That crew has no members yet.");
    } catch (error) {
      showToast(error.message || "Crew could not be assigned.");
    }
    return;
  }
  const employee = findEmployee(employeeId);
  if (!employee) {
    showToast("Select an employee or a crew to assign.");
    return;
  }
  const existing = getJobAssignments().find((assignment) => assignment.jobId === jobId && assignment.employeeId === employeeId);
  try {
    await saveBackendRecord("jobAssignments", {
      ...(existing || {}),
      id: existing?.id || makeId("assignment"),
      jobId,
      employeeId,
      crewId: existing?.crewId || "",
      role: data.get("role").toString().trim() || employee.jobTitle || "Technician",
      isFieldLead: existing?.isFieldLead || false,
      status: "Assigned",
      eligibilityStatus: employee.readinessStatus === "Blocked" ? "Blocked" : employee.readinessStatus === "Expiring" ? "Warning" : "Eligible",
      eligibilityNote: employee.readinessStatus === "Blocked" ? "Employee has a blocking credential record" : "",
      plannedStart: existing?.plannedStart || new Date().toISOString(),
      plannedEnd: existing?.plannedEnd || "",
    });
    closeDialogs();
    render();
    showToast("Employee assigned to job.");
  } catch (error) {
    showToast(error.message || "Employee could not be assigned.");
  }
}

// Gap item "Projects with alerts have no way to resolve them" — project/account alert cards
// (renderAlertCard) previously only ever displayed status, with no write path anywhere in the app
// to move an alert out of "Open". saveProjectAlert() only ever created new alerts. This is the one
// function that flips status to "Resolved" so the alert stops counting against active-alert badges
// and drops off every `alert.status !== "Resolved"` filtered list across the app.
async function resolveProjectAlert(alertId) {
  const alert = (state.backend.projectAlerts || []).find((item) => item.id === alertId);
  if (!alert) return;
  try {
    await saveBackendRecord("projectAlerts", { ...alert, status: "Resolved", resolvedAt: new Date().toISOString(), resolvedBy: state.currentUser?.name || "Local user" });
    render();
    showToast("Alert resolved.");
  } catch (error) {
    showToast(error.message || "Alert could not be resolved.");
  }
}

