async function linkContactToOpportunity(contactId, opportunityId) {
  const contact = findContact(contactId);
  if (!contact || contact.opportunityIds?.includes(opportunityId)) return;
  // Every caller refreshes afterwards, so skip the per-write backend refetch.
  await saveBackendRecord(
    "contacts",
    { ...contact, opportunityIds: [...(contact.opportunityIds || []), opportunityId] },
    { refresh: false },
  );
}

async function saveIdentityConfig(form) {
  if (!userHasRole("Admin")) {
    showToast("Only an administrator can change the Microsoft sign-in configuration.");
    return;
  }
  const data = new FormData(form);
  const config = {
    tenantId: data.get("tenantId").toString().trim(),
    clientId: data.get("clientId").toString().trim(),
    scopes: data.get("scopes").toString().trim() || defaultIdentityConfig.scopes,
  };

  await putSetting("identityConfig", config);
  await putSetting("authError", "");
  await refreshState();
  render();
  showToast("Microsoft identity configuration saved.");
}

async function advanceOpportunity(id) {
  const opportunity = state.opportunities.find((item) => item.id === id);
  if (!opportunity) return;

  const currentIndex = STAGES.indexOf(opportunity.stage);
  const nextStage = STAGES[Math.min(currentIndex + 1, STAGES.length - 1)];
  await moveOpportunityToStage(id, nextStage);
}

function describeMissingFields(missingFields) {
  return missingFields.map((field) => field.label).join(", ");
}

function flashStageBlockBanner() {
  const banner = document.querySelector("[data-stage-block-banner]");
  if (!banner) return;
  banner.scrollIntoView({ behavior: "smooth", block: "center" });
  banner.classList.remove("stage-block-flash");
  // Force reflow so the animation restarts if it's already mid-flash.
  void banner.offsetWidth;
  banner.classList.add("stage-block-flash");
  setTimeout(() => banner.classList.remove("stage-block-flash"), 1400);
}

async function moveOpportunityToStage(id, nextStage) {
  const opportunity = state.opportunities.find((item) => item.id === id);
  if (!opportunity || !STAGES.includes(nextStage) || opportunity.stage === nextStage) return;
  const previousStage = opportunity.stage;

  const missingFields = getMissingStageFields(opportunity, nextStage);
  if (missingFields.length) {
    showToast(`Can't advance to ${nextStage} — missing: ${describeMissingFields(missingFields)}.`);
    flashStageBlockBanner();
    return;
  }

  const updated = {
    ...opportunity,
    stage: nextStage,
    dealStage: nextStage,
    probability: STAGE_PROBABILITY[nextStage],
    closeProbability: STAGE_PROBABILITY[nextStage],
    updatedAt: new Date().toISOString(),
  };

  try {
    await saveBackendRecord("opportunities", updated);
  } catch (error) {
    showToast(error.message || "Opportunity could not be moved.");
    return;
  }
  await queueChange("Opportunity", `moved to ${nextStage}`, updated);
  if (nextStage === "Won" && previousStage !== "Won") {
    await autoArchiveStakeholdersOnClose(id);
  }
  await refreshState();
  render();
  showToast(`Moved to ${nextStage}.`);
  await maybeOfferProjectForWonOpportunity(previousStage, updated);
}

function mapServiceTypeToServiceCategory(serviceType) {
  const map = {
    "Emergency Spill Response": "ER",
    "Environmental Sampling": "Sampling",
    "Scheduled Environmental Service": "Scheduled",
    "Remediation Field Work": "Remediation",
    "Asbestos Abatement": "Abatement",
  };
  return map[serviceType] || "Scheduled";
}

function mapServiceTypeToJobClass(serviceType) {
  if (serviceType === "Emergency Spill Response") return "Emergency Response";
  if (serviceType === "Remediation Field Work") return "Multi-Stage Remediation";
  return "Scheduled Work";
}

function mapJobClassToServiceCategory(jobClass) {
  if (jobClass === "Emergency Response") return "ER";
  if (jobClass === "Multi-Stage Remediation") return "Remediation";
  return "Scheduled";
}

async function maybeOfferProjectForWonOpportunity(previousStage, opportunity) {
  if (previousStage === "Won" || opportunity.stage !== "Won") return;
  const core = getCoreOpportunity(opportunity);
  const shouldCreate = window.confirm(
    `"${core.opportunityName}" is now Won. Create a project for it? You'll be able to push job requests to dispatch from the project once it exists.`,
  );
  if (!shouldCreate) return;
  if (!canAccessView("project-detail")) {
    showToast("Your current role cannot open Operations projects. Ask operations to create the project.");
    return;
  }
  openProjectFromOpportunityDialog(opportunity.id);
}

function openProjectFromOpportunityDialog(opportunityId) {
  const opportunity = findOpportunity(opportunityId);
  if (!opportunity) return;
  const core = getCoreOpportunity(opportunity);
  const dialog = document.querySelector("#projectCreateDialog");
  const form = dialog.querySelector("form");
  form.reset();
  form.elements.opportunityId.value = opportunity.id;
  form.elements.accountId.value = core.accountId;
  form.elements.name.value = core.opportunityName;
  form.elements.jobClass.value = mapServiceTypeToJobClass(core.serviceType);
  populateEmployeeSelect(dialog, "projectManagerEmployeeId", "Select project manager");
  form.elements.startDate.value = todayIso();
  // Item 26 — the opportunity's close band replaces the quarter as the rough anchor: an exact day
  // is still false precision, so use "today + the band's own day range" (its midpoint, offset by
  // how long the band has already been sitting) as a reasonable target, falling back to the same
  // "30 days out" default every other quick-create flow in the app uses when there's no band.
  const closeBandInfo = findCloseBand(core.closeBand);
  let targetDate = addDays(30);
  if (closeBandInfo && Number.isFinite(closeBandInfo.maxDays)) {
    const daysSinceSet = core.closeBandSetAt ? daysBetween(core.closeBandSetAt, todayIso()) : 0;
    const remainingDays = Math.max(7, closeBandInfo.maxDays - daysSinceSet);
    targetDate = addDays(remainingDays);
  }
  form.elements.targetDate.value = targetDate;
  // Item 3: default the project's value from the linked quote/estimate's computed total when one
  // exists (the "Current" one selected on the opportunity, i.e. opportunity.quoteId/estimateId) —
  // preferring a quote over an estimate since a quote is the more committed document. Falls back to
  // the opportunity's own amount (the pre-existing manual-entry behavior) when neither is attached.
  const currentQuote = opportunity.quoteId ? quotesForOpportunity(opportunity.id).find((item) => item.id === opportunity.quoteId) : null;
  const currentEstimate = opportunity.estimateId ? estimatesForOpportunity(opportunity.id).find((item) => item.id === opportunity.estimateId) : null;
  const documentTotal = Number(currentQuote?.totalAmount || currentEstimate?.totalAmount || 0);
  form.elements.budget.value = documentTotal > 0 ? documentTotal : core.amount || 0;
  dialog.showModal();
}

async function saveProjectFromOpportunity(form) {
  const data = new FormData(form);
  const account = findAccount(data.get("accountId").toString());
  if (!account) {
    showToast("That account is no longer available.");
    return;
  }
  const opportunityId = data.get("opportunityId").toString();
  const opportunity = findOpportunity(opportunityId);
  const projectManagerEmployeeId = (data.get("projectManagerEmployeeId") || "").toString();
  const projectManager = getEmployees().find((employee) => employee.id === projectManagerEmployeeId)?.displayName || "";
  // Project Stage is not user-choosable at creation (Phase 15 item 4) — the stage ladder owns it from here.
  const projectStage = "Intake";
  const job = buildCoreProjectRecord({
    id: makeId("proj"),
    accountId: account.id,
    // Default the intake "Site" to whichever facility was already selected during the sales process
    // (the opportunity's own facilityId), not an arbitrary "first facility on the account" — the two
    // can differ for accounts with multiple sites, which was the reported bug (item 13).
    // Owner, 2026-09-25: an opportunity sited at a location (no facility) hands that location to the
    // project; the "first facility on the account" guess is only for an opportunity with no site.
    facilityId: opportunity?.facilityId || opportunitySiteLinks(opportunity).facilityId || (opportunitySiteLinks(opportunity).locationId ? "" : facilitiesForAccount(account.id)[0]?.id || ""),
    siteLocationId: opportunitySiteLinks(opportunity).locationId,
    opportunityId,
    contactIds: contactsForAccount(account.id).map((contact) => contact.id),
    name: data.get("name").toString().trim(),
    jobClass: (data.get("jobClass") || "").toString(),
    status: "Pre-mobilization",
    activePhase: projectStage,
    projectManagerEmployeeId,
    projectManager,
    salesLead: account.owner,
    startDate: data.get("startDate").toString(),
    targetDate: data.get("targetDate").toString(),
    budget: Number(data.get("budget") || 0),
    notToExceed: "",
    marginWatch: "New project created from a won opportunity.",
    projectStage,
    // Phase 15 item 1 — carry the sales scope over instead of dropping it on the floor. Copied at
    // creation (owner decision: no provenance badging, no drift tracking — "we just need the data").
    // The opportunity keeps changing after the win; the project does not follow it.
    equipmentNeeds: opportunity?.equipmentNeeds || [],
    vendorNeeds: opportunity?.vendorNeeds || [],
    resourceNeeds: opportunity?.resourceNeeds || [],
    siteWalkStatus: opportunity?.siteWalkStatus || "Incomplete",
    sitePhotoRefs: [],
    // Quote/estimate lines aren't copied — the quote/estimate record itself is the priced baseline
    // (quoteLinesForQuote/estimateLinesForEstimate read live), so the project just keeps the same
    // reference the opportunity had at win time rather than duplicating line-item rows.
    quoteId: opportunity?.quoteId || "",
    estimateId: opportunity?.estimateId || "",
  });

  await saveBackendRecord("projects", job, { refresh: false });
  await queueChange("Project", "created", job);
  await linkSiteWalksToProject(job);
  closeDialogs();
  await refreshState();
  if (canAccessView("project-detail")) {
    state.selectedProjectId = job.id;
    state.view = "project-detail";
    showToast(`Project "${job.name}" created. Push a job request to dispatch when ready.`);
  } else {
    showToast(`Project "${job.name}" created. Ask operations to continue setup.`);
  }
  render();
}

// Phase 25 Wave B item 6 (2026-09-29): the won deal's site walk reports gain the new project's id. Only
// the report rows: the walk's scheduleEvents row keeps projectId "" on purpose (see siteWalksForProject).
// A report already stamped with an earlier project from the same opportunity keeps that stamp; readers
// also match on the opportunity, so the second project still sees the walk. Best effort: the project is
// saved either way, and a report this session cannot write (no sales access, or a phone saving it at
// the same moment) is still found through the opportunity.
async function linkSiteWalksToProject(project) {
  if (!project?.opportunityId) return;
  const reports = liveRows(state.backend.siteWalkReports).filter((report) => report.opportunityId === project.opportunityId && !report.projectId);
  for (const report of reports) {
    try {
      await saveBackendRecord("siteWalkReports", { ...report, projectId: project.id }, { refresh: false });
    } catch (error) {
      console.warn("Site walk report was not linked to the new project", report.id, error?.message || error);
    }
  }
}

function openProjectIntakeDialog(jobId) {
  const job = findProject(jobId);
  if (!job) return;
  const dialog = document.querySelector("#projectIntakeDialog");
  const form = dialog.querySelector("form");
  form.reset();
  form.elements.id.value = job.id;
  const fallback = projectIntakeFallbacks(job);
  form.elements.generatorName.value = job.generatorName || fallback.generatorName;
  form.elements.generatorSiteName.value = job.generatorSiteName || fallback.generatorSiteName;
  form.elements.generatorContactName.value = job.generatorContactName || fallback.generatorContactName;
  form.elements.generatorContactPhone.value = job.generatorContactPhone || fallback.generatorContactPhone;
  form.elements.epaId.value = job.epaId || fallback.epaId;
  form.elements.tceqId.value = job.tceqId || fallback.tceqId;
  form.elements.insuranceContact.value = job.insuranceContact || fallback.insuranceContact;
  form.elements.insuranceCarrier.value = job.insuranceCarrier || fallback.insuranceCarrier;
  form.elements.claimNumber.value = job.claimNumber || job.insuranceClaimNumber || "";
  form.elements.serviceProfile.value = job.serviceProfile || "";
  form.elements.jobClass.value = job.jobClass || "Scheduled Work";
  form.elements.siteWalkStatus.value = job.siteWalkStatus || "Incomplete";
  // Phase 25 item 14 (2026-09-29) — the free-text sitePhotos field is gone; the Site photos count on
  // the Intake tab now counts real photo documents (projectIntakePhotoCount). Any sitePhotoRefs a
  // project already has from the old field are shown read-only here so the text isn't lost, but this
  // dialog never writes to sitePhotoRefs again.
  const legacyPhotosNote = dialog.querySelector('[data-role="project-intake-legacy-site-photos"]');
  if (legacyPhotosNote) {
    const legacyRefs = job.sitePhotoRefs || [];
    if (legacyRefs.length) {
      legacyPhotosNote.hidden = false;
      legacyPhotosNote.innerHTML = `<strong>Photo notes (from the old intake field)</strong><br />${legacyRefs
        .map((photo) => escapeHtml(photo.note ? `${photo.caption} | ${photo.note}` : photo.caption))
        .join("<br />")}`;
    } else {
      legacyPhotosNote.hidden = true;
      legacyPhotosNote.innerHTML = "";
    }
  }
  // Item 6 (2026-09-28, "No way to edit down payment") — the mobilization/down-payment section,
  // shown only for Emergency Response projects (the only jobClass that gates on it).
  if (form.elements.hasInsurance) form.elements.hasInsurance.value = job.hasInsurance || "No";
  if (form.elements.isInsuranceClaim) form.elements.isInsuranceClaim.value = job.isInsuranceClaim || "No";
  if (form.elements.insurancePolicyNumber) form.elements.insurancePolicyNumber.value = job.insurancePolicyNumber || "";
  if (form.elements.policyCopyOnFile) form.elements.policyCopyOnFile.checked = Boolean(job.policyCopyOnFile);
  if (form.elements.downPaymentAmount) form.elements.downPaymentAmount.value = job.downPaymentAmount || "";
  if (form.elements.downPaymentBy) form.elements.downPaymentBy.value = job.downPaymentBy || "";
  if (form.elements.downPaymentReference) form.elements.downPaymentReference.value = job.downPaymentReference || "";
  if (form.elements.overrideMobilization) form.elements.overrideMobilization.checked = Boolean(job.overrideMobilization);
  if (form.elements.overrideBy) form.elements.overrideBy.value = job.overrideBy || "";
  if (form.elements.overrideReason) form.elements.overrideReason.value = job.overrideReason || "";
  const statusReadout = dialog.querySelector('[data-role="project-intake-mobilization-status"]');
  if (statusReadout) statusReadout.textContent = job.mobilizationStatus ? `Current: ${job.mobilizationStatus}${job.mobilizationNote ? ` — ${job.mobilizationNote}` : ""}` : "Mobilization has not been computed for this project yet.";
  toggleProjectIntakeMobilizationFields(form, job.jobClass || "Scheduled Work");
  dialog.showModal();
}

// Item 6 — the mobilization/down-payment fieldset only applies to Emergency Response projects.
function toggleProjectIntakeMobilizationFields(form, jobClass) {
  const fieldset = form.querySelector('[data-role="project-intake-mobilization-fieldset"]');
  if (fieldset) fieldset.hidden = jobClass !== "Emergency Response";
}

async function saveProjectIntake(form) {
  const data = new FormData(form);
  const job = findProject(data.get("id").toString());
  if (!job) return;
  // Read `claimNumber || insuranceClaimNumber` everywhere, write `claimNumber`, keep
  // `insuranceClaimNumber` in sync (item 6 — the intake wrote one, this dialog read the other).
  const claimNumber = data.get("claimNumber").toString().trim();
  const jobClass = (data.get("jobClass") || "").toString();
  const fields = {
    ...job,
    generatorName: data.get("generatorName").toString().trim(),
    generatorSiteName: data.get("generatorSiteName").toString().trim(),
    generatorContactName: data.get("generatorContactName").toString().trim(),
    generatorContactPhone: data.get("generatorContactPhone").toString().trim(),
    epaId: data.get("epaId").toString().trim(),
    tceqId: data.get("tceqId").toString().trim(),
    insuranceContact: data.get("insuranceContact").toString().trim(),
    insuranceCarrier: data.get("insuranceCarrier").toString().trim(),
    claimNumber,
    insuranceClaimNumber: claimNumber,
    serviceProfile: data.get("serviceProfile").toString().trim(),
    jobClass,
    siteWalkStatus: (data.get("siteWalkStatus") || "").toString(),
  };
  // The mobilization/down-payment section only exists (and only submits meaningful values) for
  // Emergency Response projects — don't let stale/default select values from a hidden fieldset
  // overwrite a non-ER project's (empty) mobilization fields.
  if (jobClass === "Emergency Response") {
    Object.assign(fields, {
      hasInsurance: (data.get("hasInsurance") || "").toString(),
      isInsuranceClaim: (data.get("isInsuranceClaim") || "").toString(),
      insurancePolicyNumber: data.get("insurancePolicyNumber").toString().trim(),
      policyCopyOnFile: form_checked(data, "policyCopyOnFile"),
      downPaymentAmount: Number(data.get("downPaymentAmount") || 0),
      downPaymentBy: data.get("downPaymentBy").toString().trim(),
      downPaymentReference: data.get("downPaymentReference").toString().trim(),
      overrideMobilization: form_checked(data, "overrideMobilization"),
      overrideBy: data.get("overrideBy").toString().trim(),
      overrideReason: data.get("overrideReason").toString().trim(),
    });
  }

  let updated = buildCoreProjectRecord(fields);
  let jobsToSave = [];
  if (updated.jobClass === "Emergency Response") {
    const result = applyMobilizationToProjectAndJob(updated, dispatchJobsForProject(updated.id));
    updated = result.project;
    jobsToSave = result.jobs;
  }

  try {
    await saveBackendRecord("projects", updated, { refresh: false });
    for (const dispatchJobRecord of jobsToSave) {
      await saveBackendRecord("dispatchJobs", dispatchJobRecord, { refresh: false });
    }
    await queueChange("Project", "intake updated", updated);
    closeDialogs();
    await refreshState();
    render();
    showToast(jobsToSave.length ? `Intake details saved — ${updated.mobilizationStatus}.` : "Intake details saved.");
  } catch (error) {
    showToast(error.message || "Intake details could not be saved.");
  }
}

async function completeTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task) return;

  const updated = {
    ...task,
    status: "Complete",
    completedAt: new Date().toISOString(),
  };

  await saveBackendRecord("tasks", updated, { refresh: false });
  await queueChange("Task", "completed", updated);
  await refreshState();
  render();
  showToast("Task completed.");
}

async function queueChange(entity, action, payload) {
  await putRecord("syncQueue", {
    id: makeId("sync"),
    entity,
    action,
    payload,
    status: "Pending",
    createdAt: new Date().toISOString(),
  });
}

async function simulateSync() {
  const queue = pendingQueue();
  if (!state.online) {
    showToast("Still offline. Changes remain queued.");
    return;
  }

  await Promise.all(
    queue.map((item) =>
      putRecord("syncQueue", {
        ...item,
        status: "Synced",
        syncedAt: new Date().toISOString(),
      }),
    ),
  );
  await refreshState();
  render();
  showToast(queue.length ? "Queued edits marked synced for the prototype." : "Nothing is waiting to sync.");
}


function openSettingsDialog() {
  if (!settingsDialog) return;
  const settings = {
    ...defaultPlatformSettings,
    ...state.platformSettings,
  };
  const form = settingsDialog.querySelector("form");
  form.reset();
  const sessionName = settingsDialog.querySelector("[data-settings-session-name]");
  const sessionRole = settingsDialog.querySelector("[data-settings-session-role]");
  if (sessionName) sessionName.textContent = state.currentUser?.name || "Signed in";
  if (sessionRole) sessionRole.textContent = `${describeRoles()}${state.currentUser?.email ? ` · ${state.currentUser.email}` : ""}${state.currentUser?.source ? ` · ${state.currentUser.source}` : ""}`;
  form.elements.theme.value = settings.theme;
  form.elements.density.value = settings.density;
  form.elements.gpsMode.value = settings.gpsMode;
  form.elements.gpsRefresh.value = settings.gpsRefresh;
  form.elements.gpsAccuracy.value = settings.gpsAccuracy;
  form.elements.geofenceAlerts.checked = Boolean(settings.geofenceAlerts);
  fillActiveRoleSelect(form);
  form.elements.schedulerBlockMode.value = settings.schedulerBlockMode;
  form.elements.qboMode.value = settings.qboMode;
  form.elements.inventoryAlertMode.value = settings.inventoryAlertMode;
  settingsDialog.showModal();
}

// Settings > Roles and Permissions > Active role (2026-09-24, owner). Options: everything the person
// holds, or one of those roles; an Admin can view as any role. The choice lives on the server
// session, so every API call honours it, and it ends with the session.
function fillActiveRoleSelect(form) {
  const select = form.elements.activeRole;
  const help = settingsDialog.querySelector("[data-settings-roles-help]");
  if (!select) return;
  const held = state.currentUser?.heldRoles || [];
  const isAdmin = held.includes("Admin");
  const activeRole = state.currentUser?.activeRole || "";
  const choices = isAdmin ? SYSTEM_USER_ROLES.filter((role) => role !== "Client Portal" || state.session?.clientAccountId) : held;
  const allLabel = held.length > 1 ? `All my roles (${held.join(" + ")})` : `${held[0] || "No role"} (my only role)`;
  select.innerHTML = [
    `<option value="">${escapeHtml(allLabel)}</option>`,
    ...choices.filter((role) => held.length > 1 || role !== held[0]).map((role) => `<option value="${escapeAttribute(role)}">${escapeHtml(role)}${held.includes(role) ? "" : " (view as)"}</option>`),
  ].join("");
  select.value = activeRole;
  select.disabled = !state.session || state.session.kind === "dispatch-link" || (held.length <= 1 && !isAdmin);
  if (help) {
    help.textContent = activeRole
      ? `Acting as ${activeRole} until you log out. Choose "${allLabel}" to get everything back.`
      : held.length > 1
        ? `You hold ${held.join(" + ")}; everything those roles can do is open. Pick one to work as that role only, until you log out.`
        : isAdmin
          ? "Admin sees everything. Pick a role to see the app as that role until you log out."
          : `Your role is ${held[0] || "not set"}.`;
  }
}

async function savePlatformSettings(form) {
  const data = new FormData(form);
  const activeRole = (data.get("activeRole") || "").toString();
  const roleChanged = Boolean(form.elements.activeRole) && !form.elements.activeRole.disabled && activeRole !== (state.currentUser?.activeRole || "");
  const settings = {
    ...defaultPlatformSettings,
    ...state.platformSettings,
    theme: (data.get("theme") || "").toString(),
    density: (data.get("density") || "").toString(),
    gpsMode: (data.get("gpsMode") || "").toString(),
    gpsRefresh: (data.get("gpsRefresh") || "").toString(),
    gpsAccuracy: (data.get("gpsAccuracy") || "").toString(),
    geofenceAlerts: form.elements.geofenceAlerts.checked,
    schedulerBlockMode: (data.get("schedulerBlockMode") || "").toString(),
    qboMode: (data.get("qboMode") || "").toString(),
    inventoryAlertMode: (data.get("inventoryAlertMode") || "").toString(),
  };

  await putSetting("platformSettings", settings);
  let roleMessage = "";
  if (roleChanged) {
    try {
      const session = await apiRequest("/api/auth/active-role", { method: "POST", body: JSON.stringify({ role: activeRole }) });
      state.session = session;
      state.currentUser = sessionToUser(session);
      state.authAdmin = null;
      roleMessage = session.activeRole ? `Acting as ${session.activeRole} until you log out.` : "All your roles are active again.";
    } catch (error) {
      roleMessage = error.message || "Could not change the active role.";
    }
  }

  closeDialogs();
  await refreshState();
  ensureAllowedView();
  render();
  showToast(roleMessage || "Settings saved.");
}

function openOpportunityDialog(accountId = "", opportunityId = "") {
  const dialog = document.querySelector("#opportunityDialog");
  const form = dialog.querySelector("form");
  form.reset();
  populateAccountSelect(dialog);
  const opportunity = opportunityId ? findOpportunity(opportunityId) : null;
  const startingStageField = dialog.querySelector(".opportunity-starting-stage");
  if (opportunity) {
    const core = getCoreOpportunity(opportunity);
    form.elements.id.value = core.id;
    form.elements.accountId.value = core.accountId;
    form.elements.name.value = core.opportunityName;
    form.elements.value.value = core.amount;
    populateCloseBandSelect(dialog, core.closeBand || "");
    form.elements.serviceType.value = core.serviceType || "Scheduled Environmental Service";
    form.elements.status.value = core.status === "Lost" ? "Lost" : "Open";
    form.elements.nextStep.value = core.nextStep;
    form.elements.customerNeed.value = core.customerNeed || "";
    if (startingStageField) startingStageField.hidden = true;
  } else {
    form.elements.id.value = "";
    if (accountId) form.elements.accountId.value = accountId;
    // Item 26 — no default band for a brand-new opportunity, unlike the old "next quarter"
    // default. A close-timing guess this early is exactly the false precision the band was built
    // to avoid; better to leave it genuinely unset until someone has a real answer.
    populateCloseBandSelect(dialog, "");
    if (startingStageField) startingStageField.hidden = false;
  }
  dialog.showModal();
}

