function openOpportunityLeadDialog(opportunityId) {
  const opportunity = findOpportunity(opportunityId);
  if (!opportunity) return;
  const dialog = document.querySelector("#opportunityLeadDialog");
  const form = dialog.querySelector("form");
  form.reset();
  const core = getCoreOpportunity(opportunity);
  populateFacilitySelect(dialog, core.accountId);
  populateContactSelect(dialog, core.accountId);
  form.elements.id.value = core.id;
  form.elements.contactId.value = contactsForOpportunity(opportunity.id)[0]?.id || "";
  form.elements.facilityId.value = opportunity.facilityId || "";
  // Item 30 — "+ Add new facility" opens the existing Account facility dialog (Phase 02/03), not a
  // new one. It closes this dialog when saved (saveFacility() closes every open dialog) rather than
  // staying inline — reopen Edit afterward to pick the new facility. See the phase doc's corrections.
  const addFacilityButton = dialog.querySelector('[data-action="open-facility"]');
  if (addFacilityButton) addFacilityButton.dataset.accountId = core.accountId;
  populateOpportunityIndustrySelect(form.elements.industry, core.industry || "", core.accountId);
  form.elements.contaminationNotes.value = opportunity.contaminationNotes || "";
  form.elements.originatingLeadId.value = core.originatingLeadId || "";
  form.elements.sourceCampaign.value = core.sourceCampaign || "";
  form.elements.description.value = core.description || "";
  // Pre-fill from the opportunity's own field only — `core.currentSituation` also carries a
  // fallback to the account's `concern` for display purposes, and saving this form unedited
  // must not silently commit that borrowed account-level text as this opportunity's own value
  // (that's exactly how every opportunity on a shared account ended up with identical
  // "current situation" text). Show the account's concern as a separate read-only hint instead.
  form.elements.currentSituation.value = opportunity.currentSituation || "";
  // Item 35 sub-piece 1 — Customer need moved here from Develop & Planning ("customer need is
  // something that should be in qualifications or lead stage" per the owner's note).
  form.elements.customerNeed.value = opportunity.customerNeed || "";
  const account = findAccount(core.accountId);
  const hint = form.querySelector("[data-account-concern-hint]");
  if (hint) {
    // Item 27 — relabelled from jargon ("Account context (not this opportunity's own value
    // yet)") to plain attribution, plus a "Use this text" button so adopting the account's
    // concern is a deliberate click, not an accidental unedited-save (see the comment above on
    // why the fallback lives here and not in buildCoreOpportunityRecord).
    if (!opportunity.currentSituation && account?.concern) {
      hint.hidden = false;
      hint.dataset.concernText = account.concern;
      hint.querySelector(".help-text").textContent = `From the account record — ${account.name || "this account"}'s current concern: "${account.concern}"`;
    } else {
      hint.hidden = true;
      hint.dataset.concernText = "";
      hint.querySelector(".help-text").textContent = "";
    }
  }
  dialog.showModal();
}

async function saveOpportunityLead(form) {
  const data = new FormData(form);
  const opportunity = findOpportunity(data.get("id").toString());
  if (!opportunity) return;
  const updated = buildCoreOpportunityRecord({
    ...opportunity,
    facilityId: (data.get("facilityId") || "").toString(),
    industry: (data.get("industry") || "").toString().trim(),
    contaminationNotes: data.get("contaminationNotes").toString().trim(),
    originatingLeadId: data.get("originatingLeadId").toString().trim(),
    sourceCampaign: data.get("sourceCampaign").toString().trim(),
    description: data.get("description").toString().trim(),
    currentSituation: data.get("currentSituation").toString().trim(),
    customerNeed: data.get("customerNeed").toString().trim(),
    updatedAt: new Date().toISOString(),
  });

  const contactId = (data.get("contactId") || "").toString();

  try {
    await saveBackendRecord("opportunities", updated);
    if (contactId) await linkContactToOpportunity(contactId, updated.id);
  } catch (error) {
    showToast(error.message || "Lead details could not be saved.");
    return;
  }
  closeDialogs();
  await refreshState();
  render();
  showToast("Lead details saved.");
}

