const OPPORTUNITY_NEEDS_LIST_CONFIG = {
  // Item 33 — display label only ("Heavy Equipment Needed"); the field itself stays
  // `equipmentNeeds` on purpose, a rename here buys nothing and costs a migration.
  equipment: { field: "equipmentNeeds", title: "Heavy Equipment Needed" },
  vendor: { field: "vendorNeeds", title: "Vendor / subcontractor needed" },
  resource: { field: "resourceNeeds", title: "Resources needed" },
};

// Item 33 (Q12 locked decision) — split on newlines AND commas unconditionally. A comma inside a
// note now ends the item; accepted tradeoff for a simpler rule. The `Name | Note` convention still
// works since `|` isn't a split character.
function splitNeedsListInput(text) {
  return text
    .split(/[\n,]/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const [name, ...noteParts] = line.split("|");
      return { name: name.trim(), note: noteParts.join("|").trim() };
    })
    .filter((item) => item.name);
}

function openOpportunityNeedsListDialog(opportunityId, kind) {
  const config = OPPORTUNITY_NEEDS_LIST_CONFIG[kind];
  const opportunity = findOpportunity(opportunityId);
  if (!config || !opportunity) return;
  const dialog = document.querySelector("#opportunityNeedsListDialog");
  const form = dialog.querySelector("form");
  form.reset();
  form.elements.id.value = opportunityId;
  form.elements.kind.value = kind;
  const titleField = dialog.querySelector('[data-role="needs-list-title"]');
  if (titleField) titleField.textContent = config.title;
  const items = opportunity[config.field] || [];
  form.elements.items.value = items.map((item) => (item.note ? `${item.name} | ${item.note}` : item.name)).join("\n");
  const picks = dialog.querySelector("[data-approved-sub-picks]");
  if (picks) picks.hidden = kind !== "vendor";
  if (kind === "vendor") renderApprovedSubPicks(dialog, opportunity.accountId);
  dialog.showModal();
}

// Item 33 — the combined "Add / Edit all" dialog: one popup, all three lists, one write. The
// per-list dialog/buttons above stay untouched — this is an addition, not a replacement.
//
// Item 7 (2026-09-28, "Scope from sales is not editable once a project is created") — generalised
// to a target `{collection, id}` so the same dialog edits either an opportunity's or a project's
// needs lists; `collection` defaults to "opportunities" so every existing call site (which only
// ever passed an opportunity id) keeps working unchanged.
function needsTargetRecord(recordId, collection) {
  return collection === "projects" ? findProject(recordId) : findOpportunity(recordId);
}

function openOpportunityNeedsCombinedDialog(recordId, collection = "opportunities") {
  const record = needsTargetRecord(recordId, collection);
  if (!record) return;
  const dialog = document.querySelector("#opportunityNeedsCombinedDialog");
  const form = dialog.querySelector("form");
  form.reset();
  form.elements.id.value = recordId;
  if (form.elements.targetCollection) form.elements.targetCollection.value = collection;
  Object.values(OPPORTUNITY_NEEDS_LIST_CONFIG).forEach((config) => {
    const items = record[config.field] || [];
    form.elements[config.field].value = items.map((item) => (item.note ? `${item.name} | ${item.note}` : item.name)).join("\n");
  });
  renderApprovedSubPicks(dialog, record.accountId);
  dialog.showModal();
}

async function saveOpportunityNeedsCombined(form) {
  const data = new FormData(form);
  const collection = (data.get("targetCollection") || "opportunities").toString();
  const record = needsTargetRecord(data.get("id").toString(), collection);
  if (!record) return;
  const updates = {};
  Object.values(OPPORTUNITY_NEEDS_LIST_CONFIG).forEach((config) => {
    updates[config.field] = splitNeedsListInput(data.get(config.field).toString());
  });

  const updated = collection === "projects"
    ? buildCoreProjectRecord({ ...record, ...updates })
    : buildCoreOpportunityRecord({ ...record, ...updates, updatedAt: new Date().toISOString() });

  try {
    await saveBackendRecord(collection, updated);
  } catch (error) {
    showToast(error.message || "Scope could not be saved.");
    return;
  }
  closeDialogs();
  await refreshState();
  render();
  showToast("Scope saved.");
}

async function saveOpportunityNeedsList(form) {
  const data = new FormData(form);
  const kind = data.get("kind").toString();
  const config = OPPORTUNITY_NEEDS_LIST_CONFIG[kind];
  const opportunity = findOpportunity(data.get("id").toString());
  if (!config || !opportunity) return;
  const items = splitNeedsListInput(data.get("items").toString());

  const updated = buildCoreOpportunityRecord({
    ...opportunity,
    [config.field]: items,
    updatedAt: new Date().toISOString(),
  });

  try {
    await saveBackendRecord("opportunities", updated);
  } catch (error) {
    showToast(error.message || "List could not be saved.");
    return;
  }
  closeDialogs();
  await refreshState();
  render();
  showToast(`${config.title} saved.`);
}

function openOpportunityProposalDialog(opportunityId) {
  const opportunity = findOpportunity(opportunityId);
  if (!opportunity) return;
  const dialog = document.querySelector("#opportunityProposalDialog");
  const form = dialog.querySelector("form");
  form.reset();
  form.elements.id.value = opportunity.id;
  form.elements.proposalDevelopedStatus.value = opportunity.proposalDevelopedStatus || "Incomplete";
  form.elements.internalReviewStatus.value = opportunity.internalReviewStatus || "Incomplete";
  form.elements.proposalPresentedStatus.value = opportunity.proposalPresentedStatus || "Incomplete";
  dialog.showModal();
}

async function saveOpportunityProposal(form) {
  const data = new FormData(form);
  const opportunity = findOpportunity(data.get("id").toString());
  if (!opportunity) return;
  const updated = buildCoreOpportunityRecord({
    ...opportunity,
    proposalDevelopedStatus: (data.get("proposalDevelopedStatus") || "").toString(),
    internalReviewStatus: (data.get("internalReviewStatus") || "").toString(),
    proposalPresentedStatus: (data.get("proposalPresentedStatus") || "").toString(),
    updatedAt: new Date().toISOString(),
  });

  try {
    await saveBackendRecord("opportunities", updated);
  } catch (error) {
    showToast(error.message || "Proposal status could not be saved.");
    return;
  }
  closeDialogs();
  await refreshState();
  render();
  showToast("Proposal status saved.");
}

