function getFilteredDispatchJobs() {
  const jobs = state.dispatchAccountFilter
    ? getDispatchJobs().filter((job) => job.accountId === state.dispatchAccountFilter)
    : getDispatchJobs();
  const filter = state.dispatchJobFilter;
  if (filter === "All") return jobs;
  if (filter === "Open") return jobs.filter((job) => !isTerminalDispatchStatus(job.status));
  if (filter === "Planning") return jobs.filter((job) => ["request_submitted", "dispatch_review", "draft", "ready"].includes(job.status));
  if (filter === "Scheduled") return jobs.filter((job) => ["scheduled", "dispatched"].includes(job.status));
  if (filter === "In field") return jobs.filter((job) => ["acknowledged", "en_route", "on_site", "in_progress", "paused"].includes(job.status));
  if (filter === "Review") return jobs.filter((job) => ["field_complete", "office_review"].includes(job.status));
  if (filter === "Closed") return jobs.filter((job) => isTerminalDispatchStatus(job.status));
  return jobs;
}

function isTerminalDispatchStatus(status) {
  return ["closed", "cancelled"].includes(status);
}

// Gap item "Closed projects should drop out of the active feed" — every "active jobs" filter across
// the Operations applet checked `job.status !== "Complete"`, but closeProject() (Phase 09) never sets
// `status` to "Complete" at all — it only stamps `closedAt`. That mismatch meant a fully closed project
// (closedAt set, cost report generated) still passed every one of those filters and kept showing up in
// the active feed forever. This is the one place "is this project still active" should be asked from.
function isActiveProject(project) {
  return !project?.closedAt;
}

function frontlineJobRegion(job) {
  const parts = String(job.addressText || "").split(",").map((part) => part.trim()).filter(Boolean);
  if (parts.length < 2) return "Unspecified";
  const last = parts[parts.length - 1].replace(/\s*\d{5}(-\d{4})?$/, "").trim();
  const city = parts[parts.length - 2];
  return last ? `${city}, ${last}` : city;
}

function frontlineStepUnlocked(step, allSteps) {
  if (step.status === "Complete") return true;
  if (Number(step.sequence) === 1) return true;
  const prior = allSteps.find((candidate) => Number(candidate.sequence) === Number(step.sequence) - 1);
  return !prior || prior.status === "Complete";
}

// Availability is positional rather than driven by the stored status, so a record whose status
// drifted out of sync (an unlocked step whose actions were all left "Not started") stays workable.
function frontlineActionUnlocked(action, stepActions) {
  if (action.status === "Complete") return false;
  const nextUp = stepActions.find((candidate) => candidate.status !== "Complete");
  return nextUp?.id === action.id;
}

function isStepSatisfied(step) {
  const actions = actionsForDispatchStep(step.id).filter((action) => action.required !== false);
  return actions.every((action) => action.status === "Complete");
}

function getWorkPlanGate(job) {
  const transition = job ? getNextDispatchTransition(job.status) : null;
  if (!transition) return { blocked: false };
  const steps = stepsForDispatchJob(job.id);
  // Phase 25 A.3: nobody starts work before today's briefing has someone on site and everyone on site
  // has signed it (server twin in fieldAdvanceJob). Acknowledge / en route / on site aren't held up.
  // A work-plan block below still takes precedence -- it names the step to finish first.
  const briefingGate = transition.status === "in_progress" ? briefingReadiness(job) : null;
  const briefingBlock = briefingGate && !briefingGate.ready ? { blocked: true, viaBriefing: true, reason: briefingGate.reason } : null;
  if (!steps.length) return briefingBlock || { blocked: false };

  if (transition.status === "acknowledged") {
    const pending = actionsForDispatchStep(steps[0].id).find(
      (action) => action.type === "Status transition" && action.status !== "Complete",
    );
    if (pending) {
      return {
        blocked: true,
        viaAction: pending,
        reason: `Complete "${pending.name}" in the work plan to acknowledge this job.`,
      };
    }
  }

  if (transition.status === "in_progress" && steps[0].status !== "Complete") {
    return { blocked: true, reason: `Finish the "${steps[0].name}" step before starting work.` };
  }
  if (briefingBlock) return briefingBlock;

  if (transition.status === "field_complete") {
    const outstanding = steps.filter((step) => step.required !== false && step.status !== "Complete");
    if (outstanding.length) {
      return {
        blocked: true,
        reason: `${outstanding.length} work plan step${outstanding.length === 1 ? "" : "s"} still open: ${outstanding.map((step) => step.name).join(", ")}.`,
      };
    }
  }

  return { blocked: false };
}

function getJobReadiness(job) {
  const assignments = dispatchAssignmentsForJob(job.id);
  const resources = resourcesForDispatchJob(job.id);
  const conflicts = conflictsForDispatchJob(job.id).filter((conflict) => conflict.status === "Open");
  const blocking = conflicts.filter((conflict) => conflict.severity === "Blocking");
  // Live eligibility per assignment (computeAssignmentEligibility), not the stale stored
  // `assignment.eligibilityStatus` snapshot — see item 5/6 corrections: a worker whose expired
  // credential gets renewed after being assigned must unblock the job without a remove/re-add.
  const liveEligibility = assignments.map((assignment) => computeAssignmentEligibility(assignment.employeeId));
  const workersBlocked = liveEligibility.filter((eligibility) => eligibility.status === "Blocked");
  const checks = [
    {
      label: "Job type version",
      status: job.jobType && job.jobTypeVersion ? "Pass" : "Block",
      detail: job.jobType ? `${job.jobType} version ${Number(job.jobTypeVersion || 1)}` : "No published job type selected",
    },
    {
      label: "Schedule window",
      status: job.scheduledStart && job.scheduledEnd ? "Pass" : "Block",
      detail: job.scheduledStart ? `${formatDateTime(job.scheduledStart)} to ${formatShortTime(job.scheduledEnd)}` : "Start and end time required",
    },
    {
      label: "Worker assignments",
      status: assignments.length ? (workersBlocked.length ? "Block" : liveEligibility.some((eligibility) => eligibility.status === "Warning") ? "Warning" : "Pass") : "Block",
      detail: assignments.length
        ? workersBlocked.length
          ? workersBlocked.map((eligibility) => eligibility.note).join(" ")
          : `${assignments.length} workers assigned`
        : "No employees assigned",
    },
    {
      label: "Resources",
      status: resources.length ? "Pass" : "Warning",
      detail: resources.length ? `${resources.length} resources allocated` : "No equipment or material reserved",
    },
    {
      label: "Open conflicts",
      status: blocking.length ? "Block" : conflicts.length ? "Warning" : "Pass",
      detail: conflicts.length ? `${conflicts.length} open conflict${conflicts.length === 1 ? "" : "s"}` : "No open conflicts",
    },
    // Phase 04 item 5 / Phase 07 item 4 (2026-09-23): added only when the job has subcontractors /
    // equipment, so an unapproved vendor or an asset on maintenance hold blocks dispatch.
    ...[vendorReadinessCheck(job), equipmentReadinessCheck(job)].filter(Boolean),
  ];
  const hasBlock = checks.some((check) => check.status === "Block");
  const hasWarning = checks.some((check) => check.status === "Warning");
  // Terminal jobs (closed/cancelled) must be checked first — without this, a completed job on the
  // calendar/dispatch board fell through every other branch and showed "Ready" (misheard/transcribed
  // as "Yeady" in the field notes that reported this bug), which reads as if it still needed dispatch.
  const status = isTerminalDispatchStatus(job.status)
    ? "Completed"
    : hasBlock
      ? "Blocked"
      : hasWarning
        ? "Warning"
        : ["in_progress", "on_site", "en_route", "acknowledged"].includes(job.status)
          ? "In field"
          : ["field_complete", "office_review"].includes(job.status)
            ? "Review"
            : "Ready";
  const summary = status === "Completed" ? "Job closed out" : hasBlock ? "Resolve blocking checks before dispatch" : hasWarning ? "Dispatcher review recommended" : status === "In field" ? "Job package active in Front Line" : status === "Review" ? "Field package returned for review" : "All required dispatch checks pass";
  return { status, summary, checks };
}

function renderReadinessBadge(status) {
  return `<span class="readiness-badge ${normalizeCssToken(status)}"><span aria-hidden="true"></span>${escapeHtml(status || "Not checked")}</span>`;
}

function renderDispatchStatusBadge(status) {
  return `<span class="dispatch-status-badge ${normalizeCssToken(status)}">${escapeHtml(status || "Not set")}</span>`;
}

function renderDeviceSyncBadge(status) {
  const tone = status === "Healthy" ? "low" : status?.includes("pending") ? "medium" : "high";
  return `<span class="risk-badge ${tone}">${escapeHtml(status || "Unknown")}</span>`;
}

function getReadinessTone(status) {
  if (["Ready", "Completed", "Valid", "Eligible", "Pass", "Information"].includes(status)) return "low";
  if (["Expiring", "Warning", "Overridden", "Review", "Office"].includes(status)) return "medium";
  return "high";
}

function getPriorityTone(priority) {
  if (priority === "Emergency") return "high";
  if (priority === "High") return "medium";
  return "low";
}

function getAvailabilityTone(type) {
  if (type === "Unavailable") return "high";
  if (["Restricted", "On call"].includes(type)) return "medium";
  return "low";
}

function credentialPriority(status) {
  if (["Expired", "Suspended", "Revoked"].includes(status)) return 0;
  if (status === "Expiring") return 1;
  return 2;
}

function conflictPriority(severity) {
  if (severity === "Blocking") return 0;
  if (severity === "Warning") return 1;
  return 2;
}

function normalizeCssToken(value) {
  return String(value || "unknown")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function formatDispatchStatus(status) {
  return String(status || "not_set")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function formatDuration(minutes) {
  const value = Number(minutes || 0);
  if (!value) return "Not estimated";
  const hours = Math.floor(value / 60);
  const remainder = value % 60;
  if (!remainder) return `${hours} hour${hours === 1 ? "" : "s"}`;
  return `${hours}h ${remainder}m`;
}

function formatFileSize(bytes) {
  const value = Number(bytes || 0);
  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${Math.round(value / 1024)} KB`;
  return `${(value / 1024 / 1024).toFixed(value >= 10 * 1024 * 1024 ? 0 : 1)} MB`;
}

function getFileExtension(fileName) {
  const extension = String(fileName || "").split(".").pop();
  return extension && extension !== fileName ? extension.slice(0, 4).toUpperCase() : "FILE";
}

function formatDocumentRole(role) {
  if (role === "customer_packet") return "Customer packet";
  if (role === "quote") return "Quote";
  return formatDispatchStatus(role);
}

function formatShortTime(value) {
  if (!value) return "Not set";
  return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(parseDate(value));
}

function getWorkforceScheduleDates() {
  const days = getDispatchCalendarDays();
  return days.map((day) => ({
    ...day,
    assignments: [
      ...getJobAssignments().filter((assignment) => assignment.plannedStart?.slice(0, 10) === day.date),
      ...siteWalkEvents()
        .filter((event) => event.date === day.date)
        .flatMap((event) => (event.participantEmployeeIds || []).map((employeeId) => ({ id: `${event.id}-${employeeId}`, siteWalkId: event.id, employeeId, role: "Site walk", plannedStart: siteWalkStart(event) }))),
    ].sort((a, b) => new Date(a.plannedStart) - new Date(b.plannedStart)),
  }));
}

// Phase 07 item 16 (locked Q32) — strictly today + 6, seven days, no skip-ahead to the first
// scheduled job. An empty week should look empty ("we want to show them nothing is scheduled and
// keep the day view predictable"), not quietly jump forward and look populated.
function getDispatchCalendarDays() {
  const start = new Date();
  start.setHours(0, 0, 0, 0);

  return Array.from({ length: 7 }, (_, index) => {
    const date = new Date(start);
    date.setDate(start.getDate() + index);
    const iso = localIsoDate(date);
    return {
      date: iso,
      label: index === 0 && iso === todayIso() ? "Today" : new Intl.DateTimeFormat("en-US", { weekday: "short" }).format(date),
      isToday: iso === todayIso(),
      jobs: getDispatchJobs()
        .filter((job) => job.scheduledStart?.slice(0, 10) === iso)
        .sort((a, b) => new Date(a.scheduledStart) - new Date(b.scheduledStart)),
    };
  });
}

function getNextDispatchTransition(status) {
  const transitions = {
    draft: { status: "ready", label: "Mark ready", dispatchStatus: "Ready to schedule", completionPercent: 0 },
    ready: { status: "scheduled", label: "Confirm schedule", dispatchStatus: "Scheduled", completionPercent: 0 },
    scheduled: { status: "dispatched", label: "Dispatch to Front Line", dispatchStatus: "Sent", completionPercent: 8 },
    dispatched: { status: "acknowledged", label: "Mark acknowledged", dispatchStatus: "Acknowledged", completionPercent: 10 },
    acknowledged: { status: "en_route", label: "Mark en route", dispatchStatus: "En route", completionPercent: 15 },
    en_route: { status: "on_site", label: "Mark on site", dispatchStatus: "On site", completionPercent: 20 },
    on_site: { status: "in_progress", label: "Start work", dispatchStatus: "In field", completionPercent: 25 },
    in_progress: { status: "field_complete", label: "Field complete", dispatchStatus: "Returned", completionPercent: 100 },
    field_complete: { status: "office_review", label: "Start office review", dispatchStatus: "Returned", completionPercent: 100 },
    office_review: { status: "closed", label: "Close job", dispatchStatus: "Closed", completionPercent: 100 },
  };
  return transitions[status] || null;
}

function getOfficeAlerts() {
  const projectAlerts = state.projectAlerts
    .filter((alert) => alert.status !== "Resolved")
    .map((alert) => ({
      group: "Operations",
      owner: alert.notified?.join(", ") || "Project team",
      title: alert.alertType,
      detail: alert.description,
      tone: alert.severity.toLowerCase() === "high" ? "high" : "medium",
    }));
  const negativeStockAlerts = liveInventoryAlerts().map((alert) => ({
    group: "Inventory",
    owner: findInventoryItem(alert.inventoryItemId)?.buyer || "Inventory Manager",
    title: `${alert.materialType} went negative on ${findDispatchJob(alert.jobId)?.jobNumber || "a dispatch job"}`,
    detail: `${alert.requestedBy || "A worker"} took ${alert.requestedQuantity} with ${alert.onHandAtRequest} on hand; balance is ${alert.resultingBalance}. Restock or correct the count.`,
    tone: "high",
  }));
  const consumableAlerts = getConsumableStatus()
    .filter((item) => item.status !== "Healthy")
    .map((item) => ({
      group: "Inventory",
      owner: item.buyer,
      title: `${item.materialType} ${item.status.toLowerCase()}`,
      detail: `${item.available} ${item.unit} available. Reorder point is ${item.reorderAt}.`,
      tone: item.tone,
    }));
  const equipmentAlerts = getEquipmentStatus()
    .filter((asset) => asset.statusTone === "high")
    .map((asset) => ({
      group: "Equipment",
      owner: "Scheduler",
      title: `${asset.assetTag} unavailable`,
      detail: asset.issue || `${asset.equipment} needs review before scheduling.`,
      tone: "high",
    }));
  const financeAlerts = getFinanceRows()
    .filter((row) => row.status === "Past due")
    .map((row) => ({
      group: "Finance",
      owner: row.job.salesLead,
      title: `${row.job.name} past due`,
      detail: `${money(row.pastDue)} needs collections follow-up.`,
      tone: "high",
    }));

  return [...projectAlerts, ...negativeStockAlerts, ...consumableAlerts, ...equipmentAlerts, ...financeAlerts];
}

function getFinanceRows() {
  const invoices = state.backend.invoices || [];
  return state.projects.map((job) => {
    const account = findAccount(job.accountId);
    const opportunity = findOpportunity(job.opportunityId);
    const invoice = invoices.find((item) => item.projectId === job.id);
    const materials = state.materialUsage.filter((item) => item.projectId === job.id);
    const equipment = state.equipmentLogs.filter((item) => item.projectId === job.id);
    // Once a project has a real generated cost report (Phase 09), use its numbers instead of the
    // rough portfolio-wide heuristic below — this is what "feeds" the real numbers into this table
    // and, through it, into openInvoiceDialog's prefill (it reads these same row.quoted/invoicePrep
    // fields). The heuristic below only still applies to projects that haven't been closed yet.
    const closeReport = job.closeReport;
    const materialCost = closeReport ? closeReport.costs.materials.total : materials.reduce((sum, item) => sum + Number(item.quantity || 0) * 42, 0);
    const equipmentCost = closeReport ? closeReport.costs.equipment.total : equipment.length * 650;
    const laborCost = closeReport ? closeReport.costs.labor.total : assignmentsForJob(job.id).length * 1200;
    const fieldExpenses = expensesForProject(job.id).reduce((sum, expense) => sum + Number(expense.amount || 0), 0);
    const expenses = closeReport ? closeReport.costs.total : materialCost + equipmentCost + laborCost + fieldExpenses;
    const quoted = Number(invoice?.quotedAmount || closeReport?.revenue.quoted || opportunity?.value || job.notToExceed || job.budget || 0);
    const invoicePrep = Number(invoice?.invoiceAmount || (closeReport ? closeReport.revenue.quoted : Math.max(quoted, expenses * 1.35)));
    const lastCommunication = activitiesForAccount(job.accountId)[0];
    const highAlert = alertsForJob(job.id).some((alert) => alert.severity === "High" && alert.status !== "Resolved");
    const pastDue = invoice?.status === "Past due" ? invoice.invoiceAmount : 0;
    const status = invoice?.status || (pastDue ? "Past due" : highAlert ? "Hold" : "Ready");
    const statusTone = pastDue || highAlert ? "high" : "low";

    return {
      job,
      account,
      invoice,
      materials,
      equipment,
      quoted,
      expenses,
      invoicePrep,
      lastCommunication,
      invoiceSignal: highAlert
        ? "Needs scope review before invoice"
        : closeReport
          ? `Cost report generated ${formatDate(job.closeReport.regeneratedAt || job.closeReport.generatedAt)} — costs ${money(closeReport.costs.total)}, margin ${money(closeReport.margin)}`
          : "Ready for invoice prep",
      pastDue,
      status,
      statusTone,
    };
  });
}

function getFinanceSummary(rows = getFinanceRows()) {
  return rows.reduce(
    (summary, row) => ({
      quoted: summary.quoted + row.quoted,
      expenses: summary.expenses + row.expenses,
      invoicePrep: summary.invoicePrep + row.invoicePrep,
      pastDue: summary.pastDue + row.pastDue,
    }),
    { quoted: 0, expenses: 0, invoicePrep: 0, pastDue: 0 },
  );
}

function makeId(prefix) {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function todayIso() {
  return localIsoDate(new Date());
}

function addDays(days) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return localIsoDate(date);
}

// Item 7 — same as addDays but relative to a given date string, not always today (for the quote
// "Effective to = Effective from + 30" live recompute).
function addDaysFrom(isoDate, days) {
  const date = parseDate(isoDate);
  if (Number.isNaN(date.getTime())) return "";
  date.setDate(date.getDate() + days);
  return localIsoDate(date);
}

function localIsoDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function toLocalDateTimeInput(date) {
  const value = date instanceof Date ? date : parseDate(date);
  const year = value.getFullYear();
  const month = String(value.getMonth() + 1).padStart(2, "0");
  const day = String(value.getDate()).padStart(2, "0");
  const hour = String(value.getHours()).padStart(2, "0");
  const minute = String(value.getMinutes()).padStart(2, "0");
  return `${year}-${month}-${day}T${hour}:${minute}`;
}

function timeInputValue(value) {
  const date = parseDate(value);
  return `${String(date.getHours()).padStart(2, "0")}:${String(date.getMinutes()).padStart(2, "0")}`;
}

// Whole-dollar amounts print without cents; anything with cents shows them. Rounding every amount
// to the dollar (the behaviour until 2026-09-23) made printed quotes disagree with their own math
// ($112.50 × 4 shown as "$113 … $450") and contradicted the owner's Q6 decision: cents allowed
// everywhere, no rounding to dollars.
function money(value) {
  const amount = Number(value) || 0;
  const hasCents = Math.round(amount * 100) % 100 !== 0;
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: hasCents ? 2 : 0,
    maximumFractionDigits: hasCents ? 2 : 0,
  }).format(amount);
}

// Always two decimals: for priced documents (quotes, estimates, rate cards) where a column of
// amounts should line up.
function moneyExact(value) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(value) || 0);
}

function formatDate(value) {
  if (!value) return "Not set";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(parseDate(value));
}

// Item 9: the report's per-day Chronology wants just a local clock time ("h:mm — what — who").
function formatTimeOnly(value) {
  if (!value) return "";
  return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(parseDate(value));
}

function formatDateTime(value) {
  if (!value) return "Not set";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(parseDate(value));
}

// Opportunity close dates were replaced with a coarser "close quarter" field (Phase 06 item 1 —
// the owner's note that exact close dates were "hard to follow"). Values are strings shaped
// "YYYY-Q#" (e.g. "2027-Q1"), which sort correctly with a plain string compare. These helpers
// convert between that shape and real Date objects only where day-level math is still needed
// internally (overdue/urgency scoring) — nothing here should push an exact day back into the UI.
// Phase 06 item 26 — replaces the closeQuarter family outright (Q10 locked decision). A quarter is
// an absolute calendar bucket, so an untouched deal silently changed band as the calendar rolled;
// "Q4 2026" answers "when on the calendar," not "how far out," which is what the pipeline actually
// asks. The replacement is a relative band (0-30/31-60/61-90/91-360/beyond-360 days) plus
// `closeBandSetAt`, so a stale forecast is visible instead of silently re-bucketing on its own —
// storing the band alone would mean a deal marked "0-30" stays "0-30" forever even 90 days later.
const CLOSE_BANDS = [
  { id: "0-30", label: "0–30 days", maxDays: 30 },
  { id: "31-60", label: "31–60 days", maxDays: 60 },
  { id: "61-90", label: "61–90 days", maxDays: 90 },
  { id: "91-360", label: "91–360 days", maxDays: 360 },
  { id: "beyond-360", label: "Beyond 360 days", maxDays: Infinity },
];

function findCloseBand(bandId) {
  return CLOSE_BANDS.find((band) => band.id === bandId) || null;
}

function formatCloseBand(bandId) {
  return findCloseBand(bandId)?.label || "No target";
}

function closeBandSortValue(bandId) {
  const index = CLOSE_BANDS.findIndex((band) => band.id === bandId);
  return index < 0 ? CLOSE_BANDS.length : index;
}

function populateCloseBandSelect(root, currentValue = "") {
  root.querySelectorAll("select[name='closeBand']").forEach((select) => {
    select.innerHTML = [
      `<option value="">No target</option>`,
      ...CLOSE_BANDS.map((band) => `<option value="${escapeAttribute(band.id)}">${escapeHtml(band.label)}</option>`),
    ].join("");
    select.value = currentValue || "";
  });
}

function parseDate(value) {
  if (typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
    const [year, month, day] = value.split("-").map(Number);
    return new Date(year, month - 1, day);
  }
  return new Date(value);
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function escapeAttribute(value) {
  return escapeHtml(value).replace(/`/g, "&#096;");
}

function showToast(message) {
  const toast = document.querySelector("#toast");
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("show"), 3200);
}

// --- Camera capture for file inputs (2026-09-24) -------------------------------------------------
// Every <input type="file"> in the app gets a "Take photo" button beside it, current and future ones
// alike (a MutationObserver decorates whatever a render inserts). On a phone the button opens the
// native camera through a hidden capture input; on a desktop with a webcam it opens
// #cameraCaptureDialog (getUserMedia) and the frame is saved as a JPEG. Either way the photo is
// appended to the input's FileList through DataTransfer and a change event fires, so the existing
// submit and upload handlers see it exactly like a picked file. The inputs themselves no longer carry
// capture="environment": that attribute forced the camera on phones and hid the photo library, and
// the button now covers the camera.
const CAMERA_IMAGE_ACCEPT = /image|\.(jpe?g|png|webp|heic|gif)\b/i;
let cameraCaptureStream = null;
let cameraCaptureResolve = null;

function installCameraCapture() {
  if (typeof MutationObserver === "undefined") return;
  decorateFileInputs(document.body);
  new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) if (node.nodeType === 1) decorateFileInputs(node);
    }
  }).observe(document.body, { childList: true, subtree: true });
}

function decorateFileInputs(root) {
  const inputs = root.matches?.('input[type="file"]') ? [root] : [...(root.querySelectorAll?.('input[type="file"]') || [])];
  inputs.forEach((input) => {
    if (input.dataset.cameraReady || input.dataset.cameraSource) return;
    input.dataset.cameraReady = "1";
    input.removeAttribute("capture");
    const button = document.createElement("button");
    button.type = "button";
    button.className = "camera-capture-button";
    button.innerHTML = `<span aria-hidden="true">&#128247;</span> Take photo`;
    button.title = input.multiple ? "Take a photo with the camera and add it to the files" : "Take a photo with the camera";
    button.hidden = !fileInputAcceptsImages(input);
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (!fileInputAcceptsImages(input)) {
        showToast("This field does not accept photos.");
        return;
      }
      captureFromCamera(input);
    });
    input.insertAdjacentElement("afterend", button);
  });
}

function fileInputAcceptsImages(input) {
  const accept = (input.getAttribute("accept") || "").trim();
  return !accept || CAMERA_IMAGE_ACCEPT.test(accept);
}

function cameraPrefersNativeCapture() {
  if (!navigator.mediaDevices?.getUserMedia) return true;
  return /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent) || (navigator.maxTouchPoints > 1 && /Macintosh/.test(navigator.userAgent));
}

async function captureFromCamera(input) {
  const file = cameraPrefersNativeCapture() ? await captureWithNativeCamera() : await captureWithWebcam();
  if (!file) return;
  addFileToInput(input, file);
  showToast(input.multiple ? `Photo added (${input.files.length} file${input.files.length === 1 ? "" : "s"} attached).` : "Photo attached.");
}

// The hidden input is what a phone browser turns into its camera sheet. It has to be clicked inside
// the user's tap, which is why this path never waits on anything first.
function captureWithNativeCamera() {
  return new Promise((resolve) => {
    const picker = document.createElement("input");
    picker.type = "file";
    picker.accept = "image/*";
    picker.setAttribute("capture", "environment");
    picker.dataset.cameraSource = "1";
    picker.hidden = true;
    let settled = false;
    const finish = (file) => {
      if (settled) return;
      settled = true;
      picker.remove();
      resolve(file || null);
    };
    picker.addEventListener("change", () => finish(picker.files?.[0]));
    picker.addEventListener("cancel", () => finish(null));
    document.body.append(picker);
    picker.click();
  });
}

async function captureWithWebcam() {
  const dialog = document.querySelector("#cameraCaptureDialog");
  if (!dialog) return captureWithNativeCamera();
  const status = dialog.querySelector(".camera-capture-status");
  const picker = dialog.querySelector(".camera-capture-picker");
  const select = picker.querySelector("select");
  const shoot = dialog.querySelector("[data-camera-shoot]");
  if (!dialog.dataset.bound) {
    dialog.dataset.bound = "1";
    dialog.querySelectorAll("[data-camera-cancel]").forEach((button) => button.addEventListener("click", () => dialog.close()));
    dialog.addEventListener("close", () => {
      stopCameraStream(dialog);
      const resolve = cameraCaptureResolve;
      cameraCaptureResolve = null;
      resolve?.(null);
    });
    shoot.addEventListener("click", () => snapCameraFrame(dialog));
    select.addEventListener("change", () => startCameraStream(dialog, select.value).catch(() => {}));
  }
  status.hidden = true;
  status.textContent = "";
  picker.hidden = true;
  shoot.disabled = true;
  const file = await new Promise((resolve) => {
    cameraCaptureResolve = resolve;
    dialog.showModal();
    startCameraStream(dialog).catch((error) => {
      const denied = error?.name === "NotAllowedError";
      status.textContent = denied
        ? "Camera access was blocked. Allow the camera for this site and try again, or choose a file instead."
        : "No camera was found on this device. Choose a file instead.";
      status.hidden = false;
    });
  });
  return file;
}

async function startCameraStream(dialog, deviceId = "") {
  stopCameraStream(dialog);
  const video = dialog.querySelector("video");
  const shoot = dialog.querySelector("[data-camera-shoot]");
  const constraints = {
    audio: false,
    video: deviceId
      ? { deviceId: { exact: deviceId }, width: { ideal: 1920 }, height: { ideal: 1080 } }
      : { facingMode: "environment", width: { ideal: 1920 }, height: { ideal: 1080 } },
  };
  const stream = await navigator.mediaDevices.getUserMedia(constraints);
  if (!dialog.open) {
    stream.getTracks().forEach((track) => track.stop());
    return;
  }
  cameraCaptureStream = stream;
  video.srcObject = stream;
  await video.play().catch(() => {});
  shoot.disabled = false;
  if (!deviceId) await populateCameraPicker(dialog, stream);
}

async function populateCameraPicker(dialog, stream) {
  const picker = dialog.querySelector(".camera-capture-picker");
  const select = picker.querySelector("select");
  const cameras = ((await navigator.mediaDevices.enumerateDevices?.()) || []).filter((device) => device.kind === "videoinput");
  if (cameras.length < 2) return;
  const activeId = stream.getVideoTracks()[0]?.getSettings?.().deviceId || "";
  select.innerHTML = cameras.map((camera, index) => `<option value="${escapeAttribute(camera.deviceId)}">${escapeHtml(camera.label || `Camera ${index + 1}`)}</option>`).join("");
  if (activeId) select.value = activeId;
  picker.hidden = false;
}

function stopCameraStream(dialog) {
  cameraCaptureStream?.getTracks().forEach((track) => track.stop());
  cameraCaptureStream = null;
  const video = dialog.querySelector("video");
  if (video) video.srcObject = null;
}

function snapCameraFrame(dialog) {
  const video = dialog.querySelector("video");
  if (!video.videoWidth) return;
  const canvas = document.createElement("canvas");
  canvas.width = video.videoWidth;
  canvas.height = video.videoHeight;
  canvas.getContext("2d").drawImage(video, 0, 0);
  canvas.toBlob(
    (blob) => {
      if (!blob) return;
      const file = new File([blob], cameraPhotoFileName(), { type: "image/jpeg", lastModified: Date.now() });
      const resolve = cameraCaptureResolve;
      cameraCaptureResolve = null;
      dialog.close();
      resolve?.(file);
    },
    "image/jpeg",
    0.92,
  );
}

function cameraPhotoFileName() {
  const now = new Date();
  const pad = (value) => String(value).padStart(2, "0");
  return `photo-${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}.jpg`;
}

function addFileToInput(input, file) {
  const transfer = new DataTransfer();
  if (input.multiple) [...(input.files || [])].forEach((existing) => transfer.items.add(existing));
  transfer.items.add(file);
  input.files = transfer.files;
  input.dispatchEvent(new Event("change", { bubbles: true }));
}

// 2026-09-24: releases land several times a day. A tab that was open before a release keeps the old
// code until it reloads, so when the new service worker takes over (skipWaiting + clients.claim) the
// tab shows a banner with a Reload button, and long-lived tabs check for a new version every 5 minutes.
function registerServiceWorker() {
  if (!("serviceWorker" in navigator)) return;
  const hadController = Boolean(navigator.serviceWorker.controller);
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (hadController || navigator.serviceWorker.controller) showUpdateBanner();
  });
  navigator.serviceWorker
    .register("./service-worker.js")
    .then((registration) => {
      setInterval(() => registration.update().catch(() => {}), 5 * 60 * 1000);
    })
    .catch(() => {
      showToast("Offline shell could not be registered in this browser.");
    });
}

function showUpdateBanner() {
  if (document.querySelector(".update-banner")) return;
  const banner = document.createElement("div");
  banner.className = "update-banner";
  banner.setAttribute("role", "status");
  banner.innerHTML = `<span>A newer version of the app is ready.</span><button class="primary-button" type="button" data-action="reload-app">Reload</button><button class="icon-button" type="button" data-action="dismiss-update-banner" aria-label="Not now" title="Not now">x</button>`;
  document.body.appendChild(banner);
}

init().catch((error) => {
  app.innerHTML = `
    <section class="empty-state">
      <h2>CRM could not start</h2>
      <p>${escapeHtml(error.message || error)}</p>
    </section>
  `;
});

// ---------------------------------------------------------------------------------------------
// Phase 21 (2026-09-25): the shared surface the field app (field/*.js) imports. Everything here
// already existed; exporting it changes no behaviour. Add to this list rather than duplicating a
// helper in field/. Bindings are live, so `state` is always the current object.
// ---------------------------------------------------------------------------------------------
// ---- Phase 21 W3 (2026-09-25): site walk report, walk map panels, facility reference layers ----
//
// The map component lives in field/map.js (window.fieldMap) and the walk logic in field/walk.js
// (window.fieldWalk); app.js reaches them through those globals so the import graph stays one-way
// (app.js → field/index.js → …). The panels below are plain renderers called from the existing
// tab renderers with one-line insertions.

// A facility's coordinates: its own latitude/longitude, else the first GPS point logged by a
// project at that facility. Used by the walk map, the parcel fetch and the tile download.
function facilityCoordinates(facility) {
  if (!facility) return null;
  if (Number.isFinite(Number(facility.latitude)) && Number.isFinite(Number(facility.longitude)) && facility.latitude !== "" && facility.longitude !== "") {
    return { lat: Number(facility.latitude), lng: Number(facility.longitude) };
  }
  const point = locationsForFacility(facility.id).find(hasGpsCoordinates);
  return point ? { lat: Number(point.latitude), lng: Number(point.longitude) } : null;
}

function siteWalkReportsForOpportunity(opportunityId) {
  return liveRows(state.backend.siteWalkReports).filter((report) => report.opportunityId === opportunityId).sort((a, b) => String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")));
}

function siteWalkObservationsForWalk(walkEventId) {
  return liveRows(state.backend.siteWalkObservations).filter((row) => row.walkEventId === walkEventId).sort((a, b) => Number(a.seq) - Number(b.seq));
}

function scheduleWalkMapMount() {
  requestAnimationFrame(() => window.fieldMap?.mountSummaryMaps?.(document));
}

function walkSectionLabel(key) {
  return (window.fieldWalk?.WALK_SECTIONS || []).find((section) => section.key === key)?.title || key;
}

function renderSiteWalkReportPanel(opportunity) {
  const walks = siteWalkEvents().filter((event) => event.opportunityId === opportunity.id).sort((a, b) => String(b.date).localeCompare(String(a.date)));
  const reports = siteWalkReportsForOpportunity(opportunity.id);
  const report = reports[0] || null;
  const walk = report ? walks.find((event) => event.id === report.walkEventId) || getScheduleEvents().find((event) => event.id === report.walkEventId) : walks[0] || null;
  const facility = findFacility(walk?.facilityId || opportunity.facilityId || "");
  const observations = walk ? siteWalkObservationsForWalk(walk.id) : [];
  const status = opportunity.siteWalkStatus || "Incomplete";
  const summary = walk || facilityCoordinates(facility) ? window.fieldMap?.renderWalkMapSummary?.(walk ? { walkEventId: walk.id } : { facilityId: facility?.id }, { height: 340 }) : null;
  if (summary) scheduleWalkMapMount();
  const sections = report ? Object.entries(report.sections || {}).filter(([, value]) => value && (value.done || Object.keys(value.fields || {}).length || (value.photoDocumentIds || []).length)) : [];
  const shares = (report?.shares || []).filter((share) => !share.revokedAt);
  const participants = walk ? siteWalkParticipants(walk).map((person) => person.displayName).join(", ") : "";
  // Phase 25 B.4 (2026-09-29): the walk's sketches and its filed report show here too.
  const sketches = report ? projectWalkSketches({ report }, opportunity?.id || "") : [];
  const filedReport = walk ? siteWalkReportDocumentFor(walk.id) : null;
  return `
    <article class="panel crm-profile-grid-full site-walk-report-panel">
      <div class="panel-header">
        <div><h3>Site walk report</h3><span>${escapeHtml(walk ? `${formatDate(walk.date)}${walk.startTime ? ` ${walk.startTime}` : ""}${participants ? ` · ${participants}` : ""}` : "No walk scheduled yet")}</span></div>
        <div class="inline-actions">
          <span class="tag">${escapeHtml(status)}</span>
          ${walk ? `<button class="mini-button" type="button" data-action="open-site-walk" data-id="${escapeAttribute(walk.id)}">Open site walk</button>` : ""}
          ${walk && !report?.completedAt ? `<button class="mini-button" type="button" data-action="walk-open-field" data-walk-event-id="${escapeAttribute(walk.id)}">Open on this device</button>` : ""}
          ${report ? `<button class="mini-button" type="button" data-action="walk-open-share" data-report-id="${escapeAttribute(report.id)}">Share link${shares.length ? ` (${shares.length})` : ""}</button>` : ""}
          ${walk ? `<button class="mini-button" type="button" data-action="walk-export-pdf" data-walk-event-id="${escapeAttribute(walk.id)}">Export PDF</button>` : ""}
          ${walk && observations.length ? `<button class="mini-button" type="button" data-action="walk-export-zip" data-walk-event-id="${escapeAttribute(walk.id)}">Site package</button>` : ""}
          ${!walk && status === "Incomplete" ? `<button class="mini-button" type="button" data-action="quick-schedule-site-walk" data-opportunity-id="${escapeAttribute(opportunity.id)}">Schedule</button>` : ""}
        </div>
      </div>
      <div class="panel-body site-walk-report-body">
        <div class="site-walk-report-facts">
          <dl class="detail-list">
            <div><dt>Check-in</dt><dd>${report?.checkIn ? `${escapeHtml(formatDateTime(report.checkIn.at))}${report.checkIn.accuracyM ? ` · GPS ±${Math.round(report.checkIn.accuracyM)} m` : " · no GPS fix"}` : "Not checked in"}</dd></div>
            <div><dt>Completed</dt><dd>${report?.completedAt ? `${escapeHtml(formatDateTime(report.completedAt))}${report.completedBy ? ` by ${escapeHtml(report.completedBy)}` : ""}` : report ? "In progress" : "—"}</dd></div>
            <div><dt>Summary</dt><dd>${escapeHtml(report?.summary || "Not written")}</dd></div>
            <div><dt>Pins &amp; shapes</dt><dd>${observations.length}${observations.some((row) => row.areaSqFt) ? ` · areas ${observations.filter((row) => row.areaSqFt).map((row) => `${Math.round(row.areaSqFt).toLocaleString()} sq ft`).join(", ")}` : ""}</dd></div>
            <div><dt>Measurements</dt><dd>${(report?.measurements || []).length ? report.measurements.map((item) => `${escapeHtml(item.label || item.kind)} ${escapeHtml(item.value)} ${escapeHtml(item.unit)}${item.note ? ` (${escapeHtml(item.note)})` : ""}`).join("; ") : "None"}</dd></div>
            <div><dt>Contacts met</dt><dd>${(report?.contactsMet || []).length ? report.contactsMet.map((id) => escapeHtml(findContact(id)?.name || id)).join(", ") : "None recorded"}</dd></div>
            <div><dt>Reference layers</dt><dd>${(report?.referenceSnapshot?.layers || []).length ? report.referenceSnapshot.layers.map((layer) => escapeHtml(`${layer.label} (${[layer.source, layer.sourceDate].filter(Boolean).join(", ")})`)).join("; ") : "None on the map"}</dd></div>
          </dl>
          ${
            sections.length
              ? `<div class="site-walk-sections">${sections
                  .map(
                    ([key, value]) => `
                    <details class="site-walk-section">
                      <summary>${escapeHtml(walkSectionLabel(key))}${value.done ? " ✓" : ""}${(value.photoDocumentIds || []).length ? ` · ${(value.photoDocumentIds || []).length} photo${(value.photoDocumentIds || []).length === 1 ? "" : "s"}` : ""}</summary>
                      <dl class="detail-list">${Object.entries(value.fields || {})
                        .filter(([, fieldValue]) => fieldValue !== "" && fieldValue !== null && fieldValue !== undefined && !(Array.isArray(fieldValue) && !fieldValue.length))
                        .map(([fieldKey, fieldValue]) => `<div><dt>${escapeHtml(fieldKey.replace(/([A-Z])/g, " $1").replace(/^./, (c) => c.toUpperCase()))}</dt><dd>${escapeHtml(Array.isArray(fieldValue) ? fieldValue.join(", ") : fieldValue)}</dd></div>`)
                        .join("")}</dl>
                      ${(value.photoDocumentIds || []).length ? `<div class="photo-grid document-list">${value.photoDocumentIds.map((id) => findDocument(id)).filter(Boolean).map(renderPhotoTile).join("")}</div>` : ""}
                    </details>`,
                  )
                  .join("")}</div>`
              : ""
          }
          ${sketches.length ? `<div class="site-walk-panel-sketches"><h4>Sketch${sketches.length === 1 ? "" : "es"}</h4><div class="photo-grid document-list">${sketches.map((document) => renderSiteWalkPhotoTile(document, "Sketch")).join("")}</div></div>` : ""}
          ${filedReport ? `<p class="help-text">Filed report: <a href="/api/documents/${encodeURIComponent(filedReport.id)}/view" target="_blank" rel="noopener">${escapeHtml(filedReport.fileName)}</a> (v${Number(filedReport.versionNumber || 1)}, ${escapeHtml(formatDateTime(filedReport.uploadedAt))})</p>` : ""}
        </div>
        <div class="site-walk-report-map">${summary ? summary.html : `<div class="empty-state compact">${walk ? "This site has no coordinates yet." : "Schedule a walk to start a map."}</div>`}</div>
      </div>
    </article>
  `;
}

// The same map on the project's Plan tab, read from the originating opportunity's walk.
function renderProjectWalkMapPanel(job) {
  const report = siteWalksForProject(job).find((walk) => walk.report)?.report || null;
  const facility = findFacility(job.facilityId || report?.facilityId || "");
  if (!report && !facilityCoordinates(facility)) return "";
  const summary = window.fieldMap?.renderWalkMapSummary?.(report ? { walkEventId: report.walkEventId } : { facilityId: facility.id }, { height: 320 });
  if (!summary) return "";
  scheduleWalkMapMount();
  return `
    <article class="panel">
      <div class="panel-header">
        <div><h3>Site map from the walk</h3><span>${escapeHtml(report ? `${report.completedAt ? "Completed" : "In progress"} · ${siteWalkObservationsForWalk(report.walkEventId).length} pins & shapes` : "No walk recorded; the facility's location")}</span></div>
        ${report ? `<button class="mini-button" type="button" data-action="walk-export-pdf" data-walk-event-id="${escapeAttribute(report.walkEventId)}">Export PDF</button>` : ""}
      </div>
      <div class="panel-body">${summary.html}</div>
    </article>
  `;
}

// ---- Phase 25 Wave B items 6–8 (2026-09-29): the site walk carried onto the project -------------
//
// A walk belongs to the opportunity (scheduleEvents kind:"site_walk" + its siteWalkReports row +
// siteWalkObservations pins). When the deal is won, saveProjectFromOpportunity stamps projectId on the
// walk's siteWalkReports row. The walk's scheduleEvents row deliberately does NOT get projectId: the
// server's project delete cascade soft-deletes scheduleEvents by projectId (and, through them, the walk
// report and pins), so a deleted project would take the opportunity's walk with it; and every
// "schedule events for this project" reader (chronology, client portal) would pick it up as work.
// Projects won before this shipped have no stamp, and nothing is backfilled on load, so every reader
// resolves by the report's projectId OR the project's source opportunity.
function siteWalksForProject(project) {
  if (!project) return [];
  const opportunityId = project.opportunityId || "";
  const reports = liveRows(state.backend.siteWalkReports).filter((report) => report.projectId === project.id || (opportunityId && report.opportunityId === opportunityId));
  const events = getScheduleEvents().filter((event) => !event.deletedAt && event.kind === "site_walk" && event.status !== "Cancelled" && opportunityId && event.opportunityId === opportunityId);
  const byEvent = new Map();
  events.forEach((event) => byEvent.set(event.id, { event, report: null }));
  reports.forEach((report) => {
    const key = report.walkEventId || report.id;
    const entry = byEvent.get(key) || { event: getScheduleEvents().find((event) => event.id === report.walkEventId && !event.deletedAt) || null, report: null };
    // Two report rows for one walk should not happen; keep the newest.
    if (!entry.report || String(report.updatedAt || "").localeCompare(String(entry.report.updatedAt || "")) > 0) entry.report = report;
    byEvent.set(key, entry);
  });
  return [...byEvent.values()].sort((a, b) => String(projectWalkTimestamp(b)).localeCompare(String(projectWalkTimestamp(a))));
}

// When the walk happened: its completion, else when it was scheduled, else its check-in.
function projectWalkTimestamp({ event, report }) {
  if (report?.completedAt) return report.completedAt;
  if (event?.date) {
    const start = new Date(siteWalkStart(event));
    return Number.isNaN(start.getTime()) ? event.date : start.toISOString();
  }
  return report?.checkIn?.at || report?.createdAt || "";
}

function projectWalkStatusLabel({ event, report }) {
  if (report?.completedAt) return "Completed";
  if (report) return "In progress";
  return event?.status || "Scheduled";
}

function projectWalkFacility({ event, report }, project = null) {
  return findFacility(event?.facilityId || report?.facilityId || project?.facilityId || "") || null;
}

function projectWalkContactName(contactId) {
  const contact = findContact(contactId);
  return contact?.name || contact?.fullName || [contact?.firstName, contact?.lastName].filter(Boolean).join(" ") || "Unknown contact";
}

// The walk's lead is whoever closed it; before it closes, the first person scheduled on it.
function projectWalkPeople({ event, report }) {
  const staff = event ? siteWalkParticipants(event).map((person) => person.displayName).filter(Boolean) : [];
  const lead = report?.completedBy || staff[0] || "";
  const customer = (report?.contactsMet || []).map(projectWalkContactName);
  return { lead, staff, customer };
}

// Every photo the walk holds, section photos first, then pin photos in pin order; unique ids.
function projectWalkPhotoIds({ event, report }) {
  const ids = [];
  Object.values(report?.sections || {}).forEach((section) => (section?.photoDocumentIds || []).forEach((id) => ids.push(id)));
  siteWalkObservationsForWalk(event?.id || report?.walkEventId || "").forEach((row) => (row.photoDocumentIds || []).forEach((id) => ids.push(id)));
  return [...new Set(ids)].filter((id) => {
    const document = findDocument(id);
    return document && !document.deletedAt;
  });
}

// The sketch(es) the walk saved (report.sketchDocumentIds since Wave A item 9). A walk closed before
// the report kept the ids falls back to the site-sketch documents on its opportunity; a walk that has
// its own ids never borrows another walk's sketches.
function projectWalkSketches({ report }, opportunityId = "") {
  const byId = new Map();
  (report?.sketchDocumentIds || []).map(findDocument).filter((document) => document && !document.deletedAt).forEach((document) => byId.set(document.id, document));
  if (opportunityId && !byId.size) {
    latestDocumentsForEntity("opportunity", opportunityId)
      .filter((document) => findDocumentType(document.documentTypeId)?.code === "site-sketch")
      .forEach((document) => byId.set(document.id, document));
  }
  return [...byId.values()];
}

// The walk report filed as a document (Wave B item 5, built alongside this): a "site-walk-report"
// document on the opportunity (or on the walk itself). Matched to this walk when the row names it;
// with one walk on the opportunity, the newest such document is that walk's.
function projectWalkFiledReportDocument({ event, report }, opportunityId = "", walkCount = 1) {
  const walkEventId = event?.id || report?.walkEventId || "";
  const isWalkReportType = (document) => findDocumentType(document.documentTypeId)?.code === "site-walk-report";
  const candidates = [
    ...(opportunityId ? latestDocumentsForEntity("opportunity", opportunityId) : []),
    ...(report ? latestDocumentsForEntity("siteWalk", report.id) : []),
    ...(walkEventId ? latestDocumentsForEntity("siteWalk", walkEventId) : []),
  ].filter(isWalkReportType);
  const namesThisWalk = (document) =>
    document.walkEventId === walkEventId ||
    (report && document.siteWalkReportId === report.id) ||
    (document.entityType === "siteWalk" && [walkEventId, report?.id].includes(document.entityId)) ||
    (document.relatedRecords || []).some((link) => [walkEventId, report?.id].includes(link?.id));
  return candidates.find(namesThisWalk) || (walkCount === 1 ? candidates[0] : null) || null;
}

function projectWalkDistanceMeters(a, b) {
  const toRad = (value) => (value * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(s));
}

// A check-in worth a second look: far from the facility (~500 m, the Wave D threshold) or a GPS fix
// too loose to place anyone on the site (worse than ±100 m).
function projectWalkCheckInWarnings(checkIn, facility) {
  if (!checkIn) return [];
  const warnings = [];
  const lat = Number(checkIn.lat);
  const lng = Number(checkIn.lng);
  const site = facilityCoordinates(facility);
  if (site && checkIn.lat != null && checkIn.lng != null && Number.isFinite(lat) && Number.isFinite(lng)) {
    const meters = projectWalkDistanceMeters({ lat, lng }, site);
    if (meters > 500) warnings.push(`${meters >= 1000 ? `${(meters / 1000).toFixed(1)} km` : `${Math.round(meters)} m`} from the facility`);
  }
  if (Number(checkIn.accuracyM) > 100) warnings.push(`Low GPS accuracy (±${Math.round(Number(checkIn.accuracyM))} m)`);
  return warnings;
}

function projectWalkMeasurementSize(item) {
  const value = item.value ?? item.area ?? item.length ?? item.depth ?? item.volume;
  return value === undefined || value === null || value === "" ? "" : `${value} ${item.unit || ""}`.trim();
}

function renderProjectWalkThumb(document) {
  const viewUrl = `/api/documents/${encodeURIComponent(document.id)}/view`;
  return `<a class="project-walk-thumb" href="${viewUrl}" target="_blank" rel="noopener" title="${escapeAttribute(document.caption || document.fileName || "")}"><img src="${viewUrl}" alt="${escapeAttribute(document.caption || document.fileName || "Site walk image")}" loading="lazy" /></a>`;
}

function renderProjectSiteWalkCard(walk, job, walkCount) {
  const { event, report } = walk;
  const walkEventId = event?.id || report?.walkEventId || "";
  const facility = projectWalkFacility(walk, job);
  const people = projectWalkPeople(walk);
  const photoIds = projectWalkPhotoIds(walk);
  const sketches = projectWalkSketches(walk, job.opportunityId);
  const filed = projectWalkFiledReportDocument(walk, job.opportunityId, walkCount);
  const warnings = projectWalkCheckInWarnings(report?.checkIn, facility);
  const measurements = report?.measurements || [];
  const pins = walkEventId ? siteWalkObservationsForWalk(walkEventId).length : 0;
  const status = projectWalkStatusLabel(walk);
  const when = event?.date ? `${formatDate(event.date)}${event.startTime ? ` ${event.startTime}` : ""}` : report?.checkIn?.at ? formatDateTime(report.checkIn.at) : "Not scheduled";
  return `
    <div class="project-site-walk" data-walk-event-id="${escapeAttribute(walkEventId)}">
      <div class="row-meta">
        <strong>${escapeHtml(facility?.name || "Site walk")}</strong>
        <span class="risk-badge ${status === "Completed" ? "low" : "medium"}">${escapeHtml(status)}</span>
      </div>
      <dl class="detail-list">
        <div><dt>When</dt><dd>${escapeHtml(when)}${report?.completedAt ? ` · closed ${escapeHtml(formatDateTime(report.completedAt))}` : ""}</dd></div>
        <div><dt>Lead</dt><dd>${escapeHtml(people.lead || "Not recorded")}</dd></div>
        <div><dt>Attendees</dt><dd>${escapeHtml([...people.staff, ...people.customer.map((name) => `${name} (customer)`)].join(", ") || "Not recorded")}</dd></div>
        <div><dt>Check-in</dt><dd>${
          report?.checkIn
            ? `${escapeHtml(formatDateTime(report.checkIn.at))}${report.checkIn.accuracyM ? ` · GPS ±${Math.round(Number(report.checkIn.accuracyM))} m` : " · no GPS fix"}${warnings.map((warning) => ` <span class="risk-badge high" title="Check this check-in before relying on its location">${escapeHtml(warning)}</span>`).join("")}`
            : "Not checked in"
        }</dd></div>
        <div><dt>Closure summary</dt><dd>${escapeHtml(report?.summary || (report?.completedAt ? "No summary written" : "Not closed yet"))}</dd></div>
        <div><dt>Photos</dt><dd>${photoIds.length} photo${photoIds.length === 1 ? "" : "s"}${pins ? ` · ${pins} pin${pins === 1 ? "" : "s"} & shapes` : ""}</dd></div>
      </dl>
      ${
        measurements.length
          ? `<table class="project-walk-measurements"><thead><tr><th>Measurement</th><th class="num">Size</th><th>Method</th><th>Note</th></tr></thead><tbody>${measurements
              .map((item) => `<tr><td>${escapeHtml(item.label || item.kind || "Measurement")}</td><td class="num">${escapeHtml(projectWalkMeasurementSize(item))}</td><td>${escapeHtml(item.method || "")}</td><td>${escapeHtml(item.note || "")}</td></tr>`)
              .join("")}</tbody></table>`
          : `<p class="help-text">No measurements taken on the walk.</p>`
      }
      ${sketches.length ? `<div class="project-walk-thumbs" aria-label="Site sketches">${sketches.map(renderProjectWalkThumb).join("")}</div>` : ""}
      <div class="inline-actions">
        ${walkEventId ? `<button class="mini-button" type="button" data-action="open-site-walk" data-id="${escapeAttribute(walkEventId)}">Open site walk</button>` : ""}
        ${filed ? `<a class="mini-button" href="/api/documents/${encodeURIComponent(filed.id)}/view" target="_blank" rel="noopener">Filed walk report</a>` : ""}
        ${walkEventId && report ? `<button class="mini-button" type="button" data-action="walk-export-pdf" data-walk-event-id="${escapeAttribute(walkEventId)}">Print report</button>` : ""}
      </div>
    </div>
  `;
}

// Plan tab, top right: the walk(s) behind this project, from the source opportunity.
function renderProjectSiteWalkPanel(job) {
  const walks = siteWalksForProject(job);
  const opportunity = job.opportunityId ? findOpportunity(job.opportunityId) : null;
  return `
    <article class="panel project-site-walk-panel">
      <div class="panel-header">
        <div><h3>Site walk</h3><span>${walks.length ? `From the source opportunity${walks.length > 1 ? ` · ${walks.length} walks, newest first` : ""}` : "What sales saw on site before the win"}</span></div>
        ${opportunity ? `<button class="mini-button" type="button" data-action="view-opportunity" data-id="${escapeAttribute(opportunity.id)}">Open opportunity</button>` : ""}
      </div>
      <div class="panel-body record-list">
        ${
          walks.length
            ? walks.map((walk) => renderProjectSiteWalkCard(walk, job, walks.length)).join("")
            : `<div class="empty-state">${opportunity ? "No site walk on the source opportunity." : "This project did not come from an opportunity, so there is no sales site walk."}${
                opportunity ? ` <button class="mini-button" type="button" data-action="quick-schedule-site-walk" data-opportunity-id="${escapeAttribute(opportunity.id)}">Schedule a site walk</button>` : ""
              }</div>`
        }
      </div>
    </article>
  `;
}

// Live tab chronology: one event per walk instead of one per walk photo.
function projectWalkChronologyEvents(job) {
  const walks = siteWalksForProject(job);
  return walks.map((walk) => {
    const { event, report } = walk;
    const walkEventId = event?.id || report?.walkEventId || "";
    const facility = projectWalkFacility(walk, job);
    const people = projectWalkPeople(walk);
    const photoIds = projectWalkPhotoIds(walk);
    const title = `Site walk — ${facility?.name || "site"}`;
    const sections = Object.entries(report?.sections || {}).filter(([, value]) => value && (value.done || Object.keys(value.fields || {}).length || (value.photoDocumentIds || []).length));
    const thumbs = photoIds.slice(0, 6).map(findDocument).filter(Boolean);
    const bodyHtml = `
      ${
        sections.length
          ? `<ul class="project-walk-sections">${sections
              .map(([key, value]) => `<li>${escapeHtml(walkSectionLabel(key))}${value.done ? " ✓" : ""}${(value.photoDocumentIds || []).length ? ` <small class="muted-text">${(value.photoDocumentIds || []).length} photo${(value.photoDocumentIds || []).length === 1 ? "" : "s"}</small>` : ""}</li>`)
              .join("")}</ul>`
          : ""
      }
      ${thumbs.length ? `<div class="project-walk-thumbs">${thumbs.map(renderProjectWalkThumb).join("")}${photoIds.length > thumbs.length ? `<span class="tag">+${photoIds.length - thumbs.length} more</span>` : ""}</div>` : ""}
      ${walkEventId ? `<div class="inline-actions"><button class="mini-button" type="button" data-action="open-site-walk" data-id="${escapeAttribute(walkEventId)}">Open site walk</button></div>` : ""}
    `;
    return {
      kind: "Site walk",
      title,
      titleAction: walkEventId ? { action: "open-site-walk", id: walkEventId } : null,
      timestamp: projectWalkTimestamp(walk),
      detail: [
        projectWalkStatusLabel(walk),
        people.lead ? `Lead ${people.lead}` : "",
        [...people.staff, ...people.customer].length ? `Attendees: ${[...people.staff, ...people.customer.map((name) => `${name} (customer)`)].join(", ")}` : "",
        `${photoIds.length} photo${photoIds.length === 1 ? "" : "s"}`,
        report?.summary ? `Summary: ${report.summary}` : "",
      ]
        .filter(Boolean)
        .join(" · "),
      meta: [],
      bodyHtml,
    };
  });
}

// Files tab › Project documents: what else belongs with the project's own files. Documents on the source
// opportunity, documents filed on the walk itself, and any document whose relatedRecords (Regarding)
// names the opportunity or the project. Images are left to the photo grids. The newest version of each
// document group, once, labelled with the first reason it qualified.
function projectRelatedDocuments(job) {
  const rows = new Map();
  const add = (document, source) => {
    if (!document || document.deletedAt || isImageDocument(document)) return;
    if (document.entityType === "project" && document.entityId === job.id) return;
    const key = document.groupId || document.id;
    if (!rows.has(key)) rows.set(key, { document, source });
  };
  if (job.opportunityId) latestDocumentsForEntity("opportunity", job.opportunityId).forEach((document) => add(document, "From opportunity"));
  siteWalksForProject(job).forEach(({ report }) => {
    if (report) latestDocumentsForEntity("siteWalk", report.id).forEach((document) => add(document, "From the site walk"));
  });
  const regarding = getDocuments().filter((document) =>
    (document.relatedRecords || []).some((link) => (link?.type === "project" && link.id === job.id) || (job.opportunityId && link?.type === "opportunity" && link.id === job.opportunityId)),
  );
  const newest = new Map();
  regarding.forEach((document) => {
    const key = document.groupId || document.id;
    const current = newest.get(key);
    if (!current || Number(document.versionNumber || 1) > Number(current.versionNumber || 1)) newest.set(key, document);
  });
  [...newest.values()].forEach((document) =>
    add(document, (document.relatedRecords || []).some((link) => link?.type === "project" && link.id === job.id) ? "Regarding this project" : "Regarding the opportunity"),
  );
  return [...rows.values()];
}

// The quote/estimate are records, not files: they print from the opportunity. Listed as link rows.
function renderProjectPricingDocumentLinks(job) {
  const opportunityId = job.opportunityId || "";
  const quotes = liveRows(state.backend.quotes).filter((quote) => (opportunityId && quote.opportunityId === opportunityId) || quote.id === job.quoteId);
  const estimates = liveRows(state.backend.estimates).filter((estimate) => (opportunityId && estimate.opportunityId === opportunityId) || estimate.id === job.estimateId);
  const row = (kind, record, printAction) => `
    <div class="detail-card document-row">
      <span class="document-ext">${kind === "Quote" ? "QUO" : "EST"}</span>
      <div class="document-main">
        <div class="row-meta">
          <strong>${escapeHtml(record.name || record.quoteNumber || record.estimateNumber || kind)}</strong>
          <span>${escapeHtml(kind)}${record.status ? ` · ${escapeHtml(record.status)}` : ""} · ${money(record.totalAmount || 0)}${record.updatedAt ? ` · ${formatDateTime(record.updatedAt)}` : ""}</span>
        </div>
        <div class="inline-actions">
          <span class="tag">From opportunity</span>
          ${[job.quoteId, job.estimateId].includes(record.id) ? `<span class="tag">Priced baseline</span>` : ""}
          ${record.opportunityId ? `<button class="mini-button" type="button" data-action="${printAction}" data-opportunity-id="${escapeAttribute(record.opportunityId)}" data-id="${escapeAttribute(record.id)}">Print</button>` : ""}
        </div>
      </div>
    </div>
  `;
  return [...quotes.map((quote) => row("Quote", quote, "print-opportunity-quote")), ...estimates.map((estimate) => row("Estimate", estimate, "print-opportunity-estimate"))].join("");
}

// ---- Phase 25 B.4/B.5 (2026-09-29): the site walk page and its filed report ----
//
// #view=site-walk&id=<walkEventId>. The office's second renderer of a walk (Phase 22 rule 4): the same
// records the phone writes, the same read-only map (field/map.js → map-core.js) and the same print
// page (field/walk.js buildWalkExportHtml, reached through window.fieldWalk). Timeline rows, the
// siteWalk Regarding type and the project tabs link here with
// data-action="open-site-walk" data-id="<walkEventId>". The filed report is a `site-walk-report`
// document on the opportunity whose `walkEventId` names the walk (siteWalkReportDocumentFor).
const SITE_WALK_CHECKIN_FAR_METERS = 500;
const SITE_WALK_CHECKIN_POOR_ACCURACY_METERS = 100;

function findSiteWalkEvent(walkEventId) {
  return walkEventId ? getScheduleEvents().find((event) => event.id === walkEventId && event.kind === "site_walk") || null : null;
}

function siteWalkReportForEvent(walkEventId) {
  return walkEventId ? liveRows(state.backend.siteWalkReports).find((report) => report.walkEventId === walkEventId) || null : null;
}

// The project the walk carried over to: the report's or event's projectId, the opportunity's, or a
// project created from the opportunity.
function siteWalkProjectFor(walk, report) {
  const opportunity = findOpportunity(walk?.opportunityId || report?.opportunityId || "");
  const directId = report?.projectId || walk?.projectId || opportunity?.projectId || "";
  const direct = directId ? findProject(directId) : null;
  if (direct) return direct;
  return opportunity ? state.projects.find((project) => project.opportunityId === opportunity.id && !project.deletedAt) || null : null;
}

// The newest version of the walk's filed report, or null.
function siteWalkReportDocumentFor(walkEventId) {
  const type = documentTypeByCode("site-walk-report");
  if (!type || !walkEventId) return null;
  return (
    getDocuments()
      .filter((document) => document.documentTypeId === type.id && document.walkEventId === walkEventId)
      .sort((a, b) => Number(b.versionNumber || 1) - Number(a.versionNumber || 1) || String(b.uploadedAt || "").localeCompare(String(a.uploadedAt || "")))[0] || null
  );
}

// The filed report's URL (it opens as a printable page), or "" when nothing is filed yet. For the live
// print page use data-action="walk-export-pdf" data-walk-event-id="<walkEventId>".
function siteWalkPrintUrl(walkEventId) {
  const document = siteWalkReportDocumentFor(walkEventId);
  return document ? `/api/documents/${encodeURIComponent(document.id)}/view` : "";
}

function openSiteWalkPage(walkEventId) {
  if (!walkEventId) return;
  if (!canAccessView("site-walk")) {
    showToast("Your current role cannot open site walks.");
    return;
  }
  state.selectedSiteWalkId = walkEventId;
  state.view = "site-walk";
  render();
  app.focus({ preventScroll: true });
}

async function fileSiteWalkReport(walkEventId, button = null) {
  if (!window.fieldWalk?.fileWalkReport) {
    showToast("The walk module has not loaded yet. Try again in a moment.");
    return;
  }
  if (button) {
    button.disabled = true;
    button.textContent = "Filing…";
  }
  try {
    const saved = await window.fieldWalk.fileWalkReport(walkEventId);
    render();
    if (saved?.unchanged) {
      showToast("Nothing has changed since the last filed copy, so no new version was added.");
      return;
    }
    showToast(`Walk report filed on the opportunity${Number(saved?.versionNumber || 1) > 1 ? ` as version ${saved.versionNumber}` : ""}.`);
  } catch (error) {
    showToast(error.message || "Could not file the walk report.");
    if (button?.isConnected) {
      button.disabled = false;
      button.textContent = "File report";
    }
  }
}

function siteWalkDistanceMeters(a, b) {
  const rad = (degrees) => (degrees * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.min(1, Math.sqrt(h)));
}

function formatSiteWalkDistance(meters) {
  const feet = meters * 3.28084;
  if (feet < 1000) return `${Math.round(feet).toLocaleString()} ft`;
  const miles = meters / 1609.344;
  return `${miles < 10 ? miles.toFixed(1) : Math.round(miles).toLocaleString()} mi`;
}

// Where the check-in was, against where the site is. The reference is the facility's own coordinates,
// else a GPS point logged at the facility -- never the check-in's own point (the walk logs one at the
// facility, and measuring the check-in against itself would always say 0 ft).
function siteWalkCheckInAssessment(walk, report) {
  const checkIn = report?.checkIn;
  if (!checkIn) return null;
  const real = (value) => value !== "" && value != null && Number.isFinite(Number(value));
  const fix = real(checkIn.lat) && real(checkIn.lng) ? { lat: Number(checkIn.lat), lng: Number(checkIn.lng) } : null;
  const facility = findFacility(walk?.facilityId || report.facilityId || "");
  let reference = null;
  let referenceLabel = "";
  if (facility && real(facility.latitude) && real(facility.longitude)) {
    reference = { lat: Number(facility.latitude), lng: Number(facility.longitude) };
    referenceLabel = "the facility's coordinates";
  } else if (facility) {
    const samePoint = (location) => fix && Math.abs(Number(location.latitude) - fix.lat) < 1e-6 && Math.abs(Number(location.longitude) - fix.lng) < 1e-6;
    const point = locationsForFacility(facility.id).filter(hasGpsCoordinates).find((location) => location.id !== checkIn.locationId && !samePoint(location));
    if (point) {
      reference = { lat: Number(point.latitude), lng: Number(point.longitude) };
      referenceLabel = `a GPS point logged at the facility${point.name ? ` (${point.name})` : ""}`;
    }
  }
  const accuracy = real(checkIn.accuracyM) ? Number(checkIn.accuracyM) : null;
  const distance = fix && reference ? siteWalkDistanceMeters(fix, reference) : null;
  const warnings = [];
  if (!fix) warnings.push("No GPS fix at check-in, so nothing shows the walker was at the site.");
  if (distance !== null && distance > SITE_WALK_CHECKIN_FAR_METERS) warnings.push(`Checked in ${formatSiteWalkDistance(distance)} from ${referenceLabel}. GPS may not be at the site.`);
  if (fix && (accuracy === null || accuracy > SITE_WALK_CHECKIN_POOR_ACCURACY_METERS)) warnings.push(`${accuracy === null ? "No GPS accuracy was reported" : `GPS accuracy was poor (±${Math.round(accuracy)} m)`}. GPS may not be at the site; a laptop or desk position is often this far off.`);
  return { checkIn, fix, facility, reference, referenceLabel, accuracy, distance, warnings };
}

function renderSiteWalkPhotoTile(document, label = "") {
  const viewUrl = `/api/documents/${encodeURIComponent(document.id)}/view`;
  const caption = document.caption || document.fileName || "Photo";
  return `
    <figure class="photo-tile">
      <a href="${viewUrl}" target="_blank" rel="noopener" title="Open full size"><img src="${viewUrl}" alt="${escapeAttribute(caption)}" loading="lazy" /></a>
      <figcaption>${escapeHtml(caption)}<small>${escapeHtml([label, document.uploadedAt ? formatDateTime(document.uploadedAt) : ""].filter(Boolean).join(" · "))}</small></figcaption>
    </figure>
  `;
}

function siteWalkFieldLabel(sectionKey, fieldKey) {
  const section = (window.fieldWalk?.WALK_SECTIONS || []).find((item) => item.key === sectionKey);
  return section?.fields?.find((field) => field.key === fieldKey)?.label || fieldKey.replace(/([A-Z])/g, " $1").replace(/^./, (c) => c.toUpperCase());
}

function siteWalkFieldValue(value) {
  if (Array.isArray(value)) return value.join(", ");
  if (value === true) return "Yes";
  if (value === false) return "No";
  return String(value);
}

function renderSiteWalkPage() {
  const walkEventId = state.selectedSiteWalkId || "";
  const event = findSiteWalkEvent(walkEventId);
  const report = siteWalkReportForEvent(walkEventId);
  if (!event && !report) {
    app.innerHTML = `
      <section class="empty-state">
        <h2>Site walk not found</h2>
        <p>It may have been cancelled or deleted.</p>
        <button class="secondary-button" type="button" data-action="nav-back">Back</button>
      </section>
    `;
    return;
  }
  const walk = event || { id: walkEventId, title: "Site walk", facilityId: report.facilityId || "", opportunityId: report.opportunityId || "", participantEmployeeIds: [], date: String(report.startedAt || "").slice(0, 10), status: report.completedAt ? "Completed" : "" };
  const opportunity = findOpportunity(walk.opportunityId || report?.opportunityId || "");
  const account = findAccount(walk.accountId || opportunity?.accountId || "");
  const facility = findFacility(walk.facilityId || report?.facilityId || "");
  const project = siteWalkProjectFor(walk, report);
  const observations = siteWalkObservationsForWalk(walkEventId);
  const completed = Boolean(report?.completedAt) || walk.status === "Completed";
  const status = completed ? "Completed" : walk.status === "Cancelled" ? "Cancelled" : report?.checkIn ? "In progress" : walk.status || "Scheduled";
  const participants = siteWalkParticipants(walk);
  const contactsMet = (report?.contactsMet || []).map((id) => ({ id, contact: findContact(id) }));
  const assessment = siteWalkCheckInAssessment(walk, report);
  const filed = siteWalkReportDocumentFor(walkEventId);
  const sections = window.fieldWalk?.WALK_SECTIONS || [];
  const sectionEntries = Object.entries(report?.sections || {});
  const orderedSections = [...sections.filter((section) => report?.sections?.[section.key]).map((section) => [section.key, report.sections[section.key]]), ...sectionEntries.filter(([key]) => !sections.some((section) => section.key === key))];
  const shownSections = orderedSections.filter(([, value]) => value && (value.done || Object.values(value.fields || {}).some((fieldValue) => fieldValue !== "" && fieldValue != null && !(Array.isArray(fieldValue) && !fieldValue.length)) || (value.photoDocumentIds || []).length));
  const sketches = projectWalkSketches({ report }, walk.opportunityId || report?.opportunityId || "");
  const sketchIds = new Set(sketches.map((document) => document.id));
  const photoLabels = new Map();
  orderedSections.forEach(([key, value]) => {
    const shotBy = new Map(Object.entries(value?.shots || {}).map(([label, id]) => [id, label]));
    (value?.photoDocumentIds || []).forEach((id) => {
      if (!photoLabels.has(id)) photoLabels.set(id, [walkSectionLabel(key), shotBy.get(id)].filter(Boolean).join(": "));
    });
  });
  observations.forEach((row) => (row.photoDocumentIds || []).forEach((id) => photoLabels.has(id) || photoLabels.set(id, `Pin ${row.seq}${row.label ? ` · ${row.label}` : ""}`)));
  const photos = [...photoLabels.entries()].filter(([id]) => !sketchIds.has(id)).map(([id, label]) => ({ document: findDocument(id), label })).filter((item) => item.document && !item.document.deletedAt);
  const measurementRows = [
    ...(report?.measurements || []).map((item) => ({
      what: item.label || item.kind || "Measurement",
      value: window.fieldWalk?.measurementDimensions ? window.fieldWalk.measurementDimensions(item) : `${item.value ?? ""} ${item.unit || ""}`.trim(),
      method: `${window.fieldWalk?.measurementMethodLabel ? window.fieldWalk.measurementMethodLabel(item.method) : item.method || ""}${item.geometry ? ` (${(item.geometry.coordinates?.[0] || []).length} GPS points)` : ""}`,
      note: item.note || "",
      by: [item.by, item.at ? formatDateTime(item.at) : ""].filter(Boolean).join(" · "),
    })),
    ...observations
      .filter((row) => row.areaSqFt || row.lengthFt)
      .map((row) => ({
        what: `Map ${row.geometry ? "shape" : "pin"} ${row.seq}${row.label ? ` · ${row.label}` : ""}`,
        value: [row.areaSqFt ? `${Math.round(row.areaSqFt).toLocaleString()} sq ft` : "", row.lengthFt ? `${Math.round(row.lengthFt).toLocaleString()} ft` : ""].filter(Boolean).join(" · "),
        method: "Drawn on the map",
        note: row.note || "",
        by: [row.createdBy, row.createdAt ? formatDateTime(row.createdAt) : ""].filter(Boolean).join(" · "),
      })),
  ];
  const needs = opportunity ? Object.values(OPPORTUNITY_NEEDS_LIST_CONFIG).map((config) => ({ title: config.title, items: opportunity[config.field] || [] })).filter((group) => group.items.length) : [];
  const shares = report?.shares || [];
  const summaryMap = window.fieldMap?.renderWalkMapSummary?.({ walkEventId }, { height: 460 }) || null;
  if (summaryMap) scheduleWalkMapMount();
  const when = `${walk.date ? formatDate(walk.date) : "No date"}${walk.startTime ? ` ${walk.startTime}` : ""}${walk.endTime && walk.endTime > (walk.startTime || "") ? `–${walk.endTime}` : ""}`;
  const checkInPanelClass = assessment?.warnings.length ? "panel-needs-attention" : "";

  app.innerHTML = `
    <section class="view">
      <div class="account-detail-shell site-walk-page" data-site-walk-page="${escapeAttribute(walkEventId)}">
        <div class="account-hero">
          <div class="account-hero-identity">
            <span class="person-avatar large">SW</span>
            <div>
              <div class="account-hero-backrow">
                ${opportunity ? `<button class="text-button" type="button" data-action="view-opportunity" data-id="${escapeAttribute(opportunity.id)}">Back to ${escapeHtml(opportunity.name)}</button>` : `<button class="text-button" type="button" data-action="nav-back">Back</button>`}
              </div>
              <h2>${escapeHtml(walk.title || "Site walk")}</h2>
              <p class="eyebrow">Site walk · ${escapeHtml(when)}</p>
              <p class="site-walk-page-links">
                ${facility ? `<span>Facility <button class="link-button" type="button" data-action="view-facility" data-id="${escapeAttribute(facility.id)}">${escapeHtml(facility.name)}</button></span>` : ""}
                ${account ? `<span>Account <button class="link-button" type="button" data-action="view-account" data-id="${escapeAttribute(account.id)}">${escapeHtml(account.name)}</button></span>` : ""}
                ${opportunity ? `<span>Opportunity <button class="link-button" type="button" data-action="view-opportunity" data-id="${escapeAttribute(opportunity.id)}">${escapeHtml(opportunity.name)}</button></span>` : ""}
                ${project ? `<span>Project <button class="link-button" type="button" data-action="view-project" data-id="${escapeAttribute(project.id)}">${escapeHtml(project.name || project.id)}</button></span>` : ""}
              </p>
            </div>
          </div>
          <div class="account-hero-stats">
            <span class="stage-badge">${escapeHtml(status)}</span>
            ${assessment?.warnings.length ? `<span class="risk-badge high" title="${escapeAttribute(assessment.warnings.join(" "))}">Check-in location doubtful</span>` : ""}
          </div>
        </div>
        <div class="inline-actions site-walk-page-actions">
          ${event ? `<button class="primary-button" type="button" data-action="walk-export-pdf" data-walk-event-id="${escapeAttribute(walkEventId)}">Print / Save as PDF</button>` : ""}
          ${event && (opportunity || report?.opportunityId) ? `<button class="secondary-button" type="button" data-action="site-walk-file-report" data-id="${escapeAttribute(walkEventId)}">${filed ? "File report again" : "File report"}</button>` : ""}
          ${filed ? `<a class="secondary-button" href="/api/documents/${encodeURIComponent(filed.id)}/view" target="_blank" rel="noopener" data-site-walk-filed-report>Filed report (v${Number(filed.versionNumber || 1)}, ${escapeHtml(formatDateTime(filed.uploadedAt))})</a>` : ""}
          ${report ? `<button class="secondary-button" type="button" data-action="walk-share-mint" data-report-id="${escapeAttribute(report.id)}">Create share link</button>` : ""}
          ${event ? `<button class="secondary-button" type="button" data-action="walk-open-field" data-walk-event-id="${escapeAttribute(walkEventId)}">Open in phone view</button>` : ""}
          ${event && observations.length ? `<button class="secondary-button" type="button" data-action="walk-export-zip" data-walk-event-id="${escapeAttribute(walkEventId)}">Site package</button>` : ""}
        </div>
        <section class="crm-profile-grid">
          <div class="detail-stack">
            <article class="panel">
              <div class="panel-header"><h3>Who and when</h3></div>
              <div class="panel-body">
                <dl class="detail-list">
                  <div><dt>Scheduled</dt><dd>${escapeHtml(when)}</dd></div>
                  <div><dt>Lead</dt><dd>${participants[0] ? `<button class="link-button" type="button" data-action="view-employee" data-id="${escapeAttribute(participants[0].id)}">${escapeHtml(participants[0].displayName)}</button>` : "Nobody assigned"}</dd></div>
                  <div><dt>BioRemedy attendees</dt><dd>${participants.length > 1 ? participants.slice(1).map((person) => `<button class="link-button" type="button" data-action="view-employee" data-id="${escapeAttribute(person.id)}">${escapeHtml(person.displayName)}</button>`).join(", ") : participants.length ? "Lead only" : "None"}</dd></div>
                  <div><dt>Customer contacts met</dt><dd>${contactsMet.length ? contactsMet.map(({ id, contact }) => (contact ? `<button class="link-button" type="button" data-action="view-contact" data-id="${escapeAttribute(id)}">${escapeHtml(contact.name)}</button>` : escapeHtml(id))).join(", ") : "None recorded"}</dd></div>
                  <div><dt>Started</dt><dd>${report?.startedAt || report?.checkIn?.at ? escapeHtml(formatDateTime(report.startedAt || report.checkIn.at)) : "Not started"}${report?.createdBy ? ` by ${escapeHtml(report.createdBy)}` : ""}</dd></div>
                  <div><dt>Completed</dt><dd>${report?.completedAt ? `${escapeHtml(formatDateTime(report.completedAt))}${report.completedBy ? ` by ${escapeHtml(report.completedBy)}` : ""}` : "Not completed"}</dd></div>
                  ${walk.notes ? `<div><dt>Scheduling notes</dt><dd>${escapeHtml(walk.notes)}</dd></div>` : ""}
                </dl>
              </div>
            </article>
            <article class="panel ${checkInPanelClass}" data-site-walk-checkin>
              <div class="panel-header"><h3>Check-in</h3></div>
              <div class="panel-body">
                ${
                  assessment
                    ? `
                      ${assessment.warnings.length ? `<div class="site-walk-warning" role="alert">${assessment.warnings.map((warning) => `<p>${escapeHtml(warning)}</p>`).join("")}</div>` : ""}
                      <dl class="detail-list">
                        <div><dt>Time</dt><dd>${escapeHtml(formatDateTime(assessment.checkIn.at))}</dd></div>
                        <div><dt>Position</dt><dd>${assessment.fix ? `${assessment.fix.lat.toFixed(6)}, ${assessment.fix.lng.toFixed(6)}` : "No GPS fix"}</dd></div>
                        <div><dt>Accuracy</dt><dd>${assessment.accuracy !== null ? `±${Math.round(assessment.accuracy)} m` : "Not reported"}</dd></div>
                        <div><dt>Distance from the site</dt><dd>${assessment.distance !== null ? `${escapeHtml(formatSiteWalkDistance(assessment.distance))} from ${escapeHtml(assessment.referenceLabel)}` : assessment.fix ? "Unknown: the facility has no coordinates of its own" : "Unknown"}</dd></div>
                      </dl>`
                    : `<div class="empty-state compact">${completed ? "Completed without a check-in." : "Not checked in yet."}</div>`
                }
              </div>
            </article>
            <article class="panel">
              <div class="panel-header"><h3>Summary</h3>${opportunity ? `<span class="tag">Opportunity site walk: ${escapeHtml(opportunity.siteWalkStatus || "Incomplete")}</span>` : ""}</div>
              <div class="panel-body">
                <p class="site-walk-summary-text">${escapeHtml(report?.summary || "No summary written.")}</p>
                ${report?.needs?.samplingNeeded ? `<p><span class="tag">Sampling needed</span></p>` : ""}
              </div>
            </article>
            <article class="panel">
              <div class="panel-header"><h3>Checklist</h3><span>${sections.filter((section) => report?.sections?.[section.key]?.done).length} of ${sections.length || orderedSections.length} sections complete</span></div>
              <div class="panel-body site-walk-sections">
                ${
                  shownSections.length
                    ? shownSections
                        .map(([key, value]) => {
                          const fields = Object.entries(value.fields || {}).filter(([, fieldValue]) => fieldValue !== "" && fieldValue != null && !(Array.isArray(fieldValue) && !fieldValue.length));
                          const sectionPhotos = (value.photoDocumentIds || []).map(findDocument).filter((document) => document && !document.deletedAt);
                          return `
                            <details class="site-walk-section" open>
                              <summary>${value.done ? '<span class="site-walk-done" aria-label="Complete">✓</span>' : '<span class="site-walk-open" aria-label="Not complete">○</span>'} ${escapeHtml(walkSectionLabel(key))}${sectionPhotos.length ? ` · ${sectionPhotos.length} photo${sectionPhotos.length === 1 ? "" : "s"}` : ""}</summary>
                              ${fields.length ? `<dl class="detail-list">${fields.map(([fieldKey, fieldValue]) => `<div><dt>${escapeHtml(siteWalkFieldLabel(key, fieldKey))}</dt><dd>${escapeHtml(siteWalkFieldValue(fieldValue))}</dd></div>`).join("")}</dl>` : ""}
                              ${sectionPhotos.length ? `<div class="photo-grid">${sectionPhotos.map((document) => renderSiteWalkPhotoTile(document, photoLabels.get(document.id) || "")).join("")}</div>` : ""}
                            </details>`;
                        })
                        .join("")
                    : `<div class="empty-state compact">Nothing recorded in the checklist.</div>`
                }
              </div>
            </article>
          </div>
          <div class="detail-stack">
            <article class="panel">
              <div class="panel-header"><div><h3>Site map</h3><span>${observations.length} pin${observations.length === 1 ? "" : "s"} &amp; shapes${(report?.referenceSnapshot?.layers || []).length ? ` · ${report.referenceSnapshot.layers.length} reference layer${report.referenceSnapshot.layers.length === 1 ? "" : "s"}` : ""}</span></div></div>
              <div class="panel-body">${summaryMap ? summaryMap.html : `<div class="empty-state compact">The map module has not loaded.</div>`}</div>
            </article>
            <article class="panel">
              <div class="panel-header"><h3>Measurements</h3></div>
              <div class="panel-body">
                ${
                  measurementRows.length
                    ? `<div class="data-table-scroll"><table class="data-table site-walk-measurements"><thead><tr><th>What</th><th>Value</th><th>Method</th><th>Note</th><th>By</th></tr></thead><tbody>${measurementRows.map((row) => `<tr><td>${escapeHtml(row.what)}</td><td>${escapeHtml(row.value)}</td><td>${escapeHtml(row.method)}</td><td>${escapeHtml(row.note)}</td><td>${escapeHtml(row.by)}</td></tr>`).join("")}</tbody></table></div>`
                    : `<div class="empty-state compact">Nothing measured.</div>`
                }
              </div>
            </article>
            <article class="panel" data-site-walk-sketches>
              <div class="panel-header"><h3>Sketches</h3></div>
              <div class="panel-body">
                ${sketches.length ? `<div class="photo-grid site-walk-sketch-grid">${sketches.map((document) => renderSiteWalkPhotoTile(document, "Sketch")).join("")}</div>` : `<div class="empty-state compact">No sketches on this walk.</div>`}
              </div>
            </article>
            <article class="panel">
              <div class="panel-header"><h3>Needs</h3></div>
              <div class="panel-body">
                ${
                  needs.length || report?.needs?.samplingNeeded
                    ? `<dl class="detail-list">${needs.map((group) => `<div><dt>${escapeHtml(group.title)}</dt><dd class="site-walk-needs">${renderOpportunityNeedsChips(group.items)}</dd></div>`).join("")}${report?.needs?.samplingNeeded ? `<div><dt>Sampling</dt><dd>Needed</dd></div>` : ""}</dl>`
                    : `<div class="empty-state compact">No needs recorded on the opportunity.</div>`
                }
              </div>
            </article>
            <article class="panel">
              <div class="panel-header">
                <h3>Share links</h3>
                ${report ? `<button class="mini-button" type="button" data-action="walk-open-share" data-report-id="${escapeAttribute(report.id)}">Manage</button>` : ""}
              </div>
              <div class="panel-body record-list">
                ${
                  shares.length
                    ? shares
                        .map((share) => {
                          const url = share.url ? (share.url.startsWith("http") ? share.url : `${location.origin}${share.url}`) : "";
                          return `
                            <div class="detail-card">
                              <div class="row-meta">
                                <div><strong>${share.audience === "customer" ? "Customer link" : "Staff link"} · ${share.revokedAt ? "Revoked" : `Expires ${escapeHtml(formatDate(share.expiresAt))}`}</strong><span>Created ${escapeHtml(formatDateTime(share.createdAt))}${share.createdBy ? ` by ${escapeHtml(share.createdBy)}` : ""} · ${Number(share.opens || 0)} open${Number(share.opens || 0) === 1 ? "" : "s"}</span></div>
                                ${url && !share.revokedAt ? `<button class="mini-button" type="button" data-action="site-walk-copy-share" data-url="${escapeAttribute(url)}">Copy</button>` : ""}
                              </div>
                              ${url ? `<code class="file-ref">${escapeHtml(url)}</code>` : `<p class="help-text">The link itself was only shown when it was created.</p>`}
                            </div>`;
                        })
                        .join("")
                    : `<div class="empty-state compact">No share links yet.</div>`
                }
              </div>
            </article>
          </div>
          <article class="panel crm-profile-grid-full">
            <div class="panel-header"><div><h3>Photos</h3><span>${photos.length} from the checklist and the map pins</span></div></div>
            <div class="panel-body">
              ${photos.length ? `<div class="photo-grid">${photos.map((item) => renderSiteWalkPhotoTile(item.document, item.label)).join("")}</div>` : `<div class="empty-state compact">No photos on this walk.</div>`}
            </div>
          </article>
        </section>
      </div>
    </section>
  `;
}

function renderFacilityReferenceLayersPanel(facility) {
  const rows = liveRows(state.backend.siteReferenceLayers).filter((row) => row.facilityId === facility.id);
  const point = facilityCoordinates(facility);
  return `
    <article class="panel">
      <div class="panel-header">
        <div><h3>Reference layers</h3><span>Parcel lines and customer drawings under this site's maps</span></div>
        <div class="inline-actions">
          <button class="mini-button" type="button" data-action="facility-fetch-parcel" data-facility-id="${escapeAttribute(facility.id)}" ${point ? "" : 'disabled title="Add coordinates to the facility first"'}>Fetch parcel</button>
          <button class="mini-button" type="button" data-action="facility-download-tiles" data-facility-id="${escapeAttribute(facility.id)}" ${point ? "" : 'disabled title="Add coordinates to the facility first"'}>Download facility tiles</button>
        </div>
      </div>
      <div class="panel-body record-list">
        ${
          rows
            .map(
              (row) => `
              <article class="detail-card">
                <div class="row-meta">
                  <div><strong>${escapeHtml(row.label || row.kind)}</strong><span class="tag">${escapeHtml(row.kind || "other")} · ${escapeHtml(row.mode || (row.geojson ? "snapshot" : "live"))}</span></div>
                  <button class="mini-button" type="button" data-action="facility-remove-layer" data-id="${escapeAttribute(row.id)}">Remove</button>
                </div>
                <p class="help-text">${escapeHtml([row.source, row.sourceDate].filter(Boolean).join(" · ") || "No source recorded")}${row.properties?.legalArea ? ` · legal area ${escapeHtml(row.properties.legalArea)} ac` : ""}</p>
              </article>`,
            )
            .join("") || `<div class="empty-state compact">${point ? "No reference layers yet. Fetch parcel pulls the approximate parcel outline from the county appraisal district via TxGIO." : "This facility has no coordinates, so nothing can be fetched or downloaded for it yet."}</div>`
        }
        <p class="help-text">Parcel lines are tax-map accuracy (3–15 m), never a survey. No public data shows underground lines; a Texas 811 locate is still required before digging.</p>
      </div>
    </article>
  `;
}

function openWalkInField(walkEventId) {
  if (!walkEventId) return;
  if (!state.frontlineSession && state.session?.employeeId) state.frontlineSession = { employeeId: state.session.employeeId, loginAt: new Date().toISOString() };
  if (window.fieldWalk?.openWalk) {
    window.fieldWalk.openWalk(walkEventId, "brief");
    return;
  }
  state.fieldWalkEventId = walkEventId;
  state.view = "field-walk";
  render();
}

function openWalkShareDialog(reportId) {
  const report = liveRows(state.backend.siteWalkReports).find((row) => row.id === reportId);
  const dialog = document.querySelector("#walkShareDialog");
  if (!report || !dialog) return;
  const shares = report.shares || [];
  dialog.querySelector("[data-walk-share-list]").innerHTML =
    shares
      .map(
        (share) => `
        <article class="detail-card">
          <div class="row-meta">
            <div><strong>${share.audience === "customer" ? "Customer link" : "Staff link"} · ${share.revokedAt ? "Revoked" : `Expires ${escapeHtml(formatDate(share.expiresAt))}`}</strong><span>Created ${escapeHtml(formatDateTime(share.createdAt))}${share.createdBy ? ` by ${escapeHtml(share.createdBy)}` : ""} · ${Number(share.opens || 0)} open${Number(share.opens || 0) === 1 ? "" : "s"}</span></div>
            ${share.revokedAt ? "" : `<button class="mini-button" type="button" data-action="walk-share-revoke" data-report-id="${escapeAttribute(report.id)}" data-share-id="${escapeAttribute(share.id)}">Revoke</button>`}
          </div>
          ${share.url ? `<code class="file-ref">${escapeHtml(share.url)}</code>` : `<p class="help-text">The link itself is only shown once, when it is created.</p>`}
        </article>`,
      )
      .join("") || `<div class="empty-state compact">No share links yet.</div>`;
  dialog.querySelectorAll('[data-action="walk-share-mint"]').forEach((button) => (button.dataset.reportId = report.id));
  dialog.showModal();
}

async function mintWalkShare(reportId, audience = "staff") {
  if (!reportId || !window.fieldWalk?.mintShareLink) return;
  try {
    const result = await window.fieldWalk.mintShareLink(reportId, { expiresInDays: 14, audience });
    const url = result?.url?.startsWith("http") ? result.url : `${location.origin}${result?.url || ""}`;
    try {
      await navigator.clipboard?.writeText(url);
    } catch {
      // clipboard may be unavailable
    }
    await refreshBackendState();
    render();
    window.prompt("Share link (copied to the clipboard):", url);
  } catch (error) {
    showToast(/does not have/.test(error?.message || "") ? "Share links need the server update: the walk share route is not deployed yet." : error.message || "Could not create a share link.");
  }
}

async function revokeWalkShare(reportId, shareId) {
  if (!reportId || !shareId || !window.fieldWalk?.revokeShareLink) return;
  try {
    await window.fieldWalk.revokeShareLink(reportId, shareId);
    await refreshBackendState();
    closeDialogs();
    render();
    showToast("Share link revoked.");
  } catch (error) {
    showToast(/does not have/.test(error?.message || "") ? "Revoking needs the server update: the walk share route is not deployed yet." : error.message || "Could not revoke the link.");
  }
}

async function fetchFacilityParcel(facilityId) {
  try {
    showToast("Looking up the parcel…");
    const module = await import("./field/layers.js");
    const row = await module.fetchParcelForFacility(facilityId);
    render();
    showToast(`Parcel saved: ${row.label}`);
  } catch (error) {
    showToast(error.message || "Parcel lookup failed.");
  }
}

async function downloadFacilityTilesAction(facilityId) {
  if (!window.fieldMap?.downloadFacilityTiles) return;
  try {
    await window.fieldMap.downloadFacilityTiles(facilityId);
  } catch (error) {
    showToast(error.message || "Tile download failed.");
  }
}

async function removeFacilityReferenceLayer(id) {
  const row = liveRows(state.backend.siteReferenceLayers).find((item) => item.id === id);
  if (!row) return;
  if (!window.confirm(`Remove the reference layer "${row.label || row.kind}"?`)) return;
  try {
    await apiRequest(`/api/backend/siteReferenceLayers/${encodeURIComponent(id)}`, { method: "DELETE" });
    await refreshBackendState();
    render();
    showToast("Reference layer removed.");
  } catch (error) {
    showToast(error.message || "Could not remove the layer.");
  }
}


